# Дописывается к SYSTEM только при включённом канале (--world). Без файла мира
# вопрос модели упал бы в пустоту, а звать спрашивать и молча выбрасывать — ровно
# та беда, из-за которой модель трижды за день «сходила с ума».
SYSTEM_QUESTION = """

ТЫ МОЖЕШЬ СПРОСИТЬ ЧЕЛОВЕКА. Необязательное поле "question" — ОДИН вопрос на
всю партию. Спрашивай о том, чего не видно в состоянии и нельзя выяснить
командой: сколько чего на карте и где оно лежит, что чему требуется, почему
приказ не проходит. Человек видит игру целиком и ответит между партиями; ответ
придёт в раздел «ЧТО МЫ ЗНАЕМ О МИРЕ» и останется там навсегда — для тебя и для
всех следующих партий. Вопрос один, поэтому трать его на то, что мешает больше
всего, а не на мелочь. Не спрашивай о том, что уже есть в состоянии, в
подсказках или в разделе о мире, — это потраченный впустую вопрос. Вопрос не
заменяет команды: в том же ответе играй как обычно. Вот как он выглядит:
{"why": "ставлю кузницу", "ok": "", "stuck": "", "cause": "",
 "question": "сколько залежей железа рядом с базой и как далеко?",
 "commands": [{"cmd":"BUILD","role":"smith","total":1}]}"""


# Разбор партии ПОСЛЕ её конца. Один вызов, вне такта: спешить некуда, и можно
