KEY_FILES = ("nim_key.txt", os.path.expanduser("~/.coss3_nim_key"))


def load_key(explicit: str = "") -> tuple[str, str]:
    """Ключ и откуда он взялся. Файл рядом со скриптом — чтобы не звать setx."""
    if explicit:
        return explicit.strip(), "--key"
    for имя in ("OPENROUTER_API_KEY", "NVIDIA_API_KEY"):
        env = os.environ.get(имя, "").strip()
        if env:
            return env, имя
    here = os.path.dirname(os.path.abspath(__file__))
    for name in KEY_FILES:
        path = name if os.path.isabs(name) else os.path.join(here, name)
        try:
            with open(path, encoding="utf-8") as f:
                key = f.read().strip()
        except OSError:
            continue
        if key:
            return key, path
    return "", ""


def похожие(model: str, ids: list[str]) -> tuple[list[str], list[str]]:
    """Делим кандидатов на «та же модель» и «просто похоже называется».

    Сильное совпадение — один корень является продолжением другого ПО ГРАНИЦЕ
    дефиса: nemotron-3.5-lightning против nemotron-3.5-lightning-30b-a3b.
    Без проверки границы mistral-nemo сходит за mistral-nemotron, а это разные
    модели, и уехать на них молча — худшее, что может случиться.
    """
    корень = model.split("/")[-1].lower()
    куски = {c for c in корень.replace(".", "-").split("-") if len(c) > 3}
    сильные, слабые = [], []
    for x in ids:
        сво = x.split("/")[-1].lower()
        длин, крат = (сво, корень) if len(сво) > len(корень) else (корень, сво)
        if длин == крат or (длин.startswith(крат) and длин[len(крат)] == "-"):
            сильные.append(x)
            continue
        свои = {c for c in сво.replace(".", "-").split("-") if len(c) > 3}
        if len(куски & свои) >= 2:
            слабые.append(x)
    return sorted(сильные), sorted(слабые)


def list_models(client, needle: str) -> int:
    """Поиск по каталогу: у OpenRouter их четыре сотни, глазами не найти."""
    try:
        ids = sorted(m.id for m in client.models.list().data)
    except Exception as e:
        print(f"каталог недоступен: {e}")
        return 1
    n = needle.lower()
    нашлись = [x for x in ids if n in x.lower()] if n else ids
    print(f"каталог по адресу {BASE_URL}: {len(ids)} моделей, "
          f"под «{needle}» подходит {len(нашлись)}")
    for x in нашлись[:40]:
        print(f"  {x}")
    if len(нашлись) > 40:
        print(f"  …и ещё {len(нашлись) - 40}")
    return 0


def check(client, model: str, think: bool = False,
          probes: int = 3, every: int = 30) -> int:
    """Жив ли ключ и жива ли модель. Заодно меряем задержку одного вызова."""
    try:
        ids = [m.id for m in client.models.list().data]
    except Exception as e:
        print(f"каталог недоступен — сеть? {e}")
        return 1
    # Внимание: листинг отдают и без ключа. Ключ проверяет только вызов ниже.
    print(f"каталог доступен, в нём {len(ids)} моделей")
    # Пресет OpenRouter (@preset/<slug>) в каталог не попадает — это НЕ модель,
    # а сохранённый набор настроек. Сверять его со списком бессмысленно, а
    # прежняя проверка отказывалась звонить и уходила с ошибкой.
    пресет = model.startswith("@preset/")
    if пресет:
        print(f"это пресет OpenRouter, а не модель: {model}")
        print("  ВНИМАНИЕ: если в пресете задан свой system prompt, он вступает в")
        print("  спор с нашим — мост требует строгий JSON, и любой другой формат")
        print("  ответа означает такт впустую. Смотрите на 'ответ:' ниже: там")
        print("  должен быть разобранный словарь с ключом 'commands'.")
    if not пресет and model not in ids:
        print(f"модель {model} НЕ значится в каталоге по адресу {BASE_URL}")
        print("  (у разных провайдеров свои id одной и той же модели, а адрес,\n"
              "   заданный через setx, на текущее окно PowerShell не действует)")
        сильные, слабые = похожие(model, ids)
        if сильные:
            print("  та же модель под другим именем:")
            for i in сильные[:5]:
                print(f"        {i}")
            print(f"  запустить: python llm_policy.py --model {сильные[0]}")
        if слабые:
            print("  похожи по названию, но это ДРУГИЕ модели — сверьтесь:")
            for i in слабые[:5]:
                print(f"        {i}")
        if not сильные and not слабые:
            print(f"  ничего похожего. Искать по каталогу: "
                  f"python llm_policy.py --models <часть имени>")
        return 1
    if not пресет:
        print(f"модель {model} в каталоге есть")
    waits, alls, bad = [], [], 0
    for i in range(probes):
        t = time.time()
        try:
            data = ask(client, model, "Время 0:30. Ресурсов нет, крестьян 20. "
                                      "Что строить первым? Ответь JSON.", think)
        except Exception as e:
            bad += 1                        # не выходим: доля сбоев — тоже замер
            alls.append(time.time() - t)    # сбой тоже жжёт такт, он в задержке
            print(f"вызов {i + 1}: {alls[-1]:5.1f} с, СБОЙ: {e}")
            continue
        waits.append(time.time() - t)
        alls.append(waits[-1])
        tok = LAST_TOKENS
        rate = f", {tok / waits[-1]:.0f} ток/с" if tok and waits[-1] else ""
        кто = f", через {LAST_PROVIDER}" if LAST_PROVIDER else ""
        # У пресета показываем ответ подробнее: главный вопрос к нему —
        # пережил ли наш формат чужой system prompt.
        видно = 400 if пресет else 50
        print(f"вызов {i + 1}: {waits[-1]:5.1f} с, {tok} токенов{rate}{кто}"
              f", ответ: {str(data)[:видно]}…")
        if пресет and i == 0:
            есть = isinstance(data, dict) and "commands" in data
            print(f"        формат ответа {'ЦЕЛ: ключ commands на месте' if есть else 'СЛОМАН: ключа commands нет — пресет перебил наш system prompt'}")
    if bad:
        print(f"сбоев {bad} из {probes} — в бою это столько же потерянных тактов")
    if not waits:
        print("ни один вызов не разобрался, мерить нечего")
        return 1
    worst = max(alls)                       # по всем: слепота такта от сбоя та же
    print(f"ключ принят. Задержка по всем вызовам: лучшая {min(alls):.1f} с, "
          f"худшая {worst:.1f} с" + (f" (из них разобрались {len(waits)})" if bad else ""))
    if worst > min(waits) * 3:
        print("        разброс больше трёхкратного. Если ток/с примерно равны — "
              "модель просто болтлива; если разные — это очередь тира, и смена "
              "модели не поможет")
    # Судим по худшей: один медленный вызов ослепляет цикл на весь такт.
    budget = every / 1.38
    a_every_hint = every
    print(f"бюджет такта при 1,38× и --every {every} — {budget:.0f} с: "
          f"{'укладывается' if worst < budget else 'НЕ укладывается'}")
    if bad:
        доля = bad / probes
        print(f"        сбоев {bad} из {probes}. Вызов идёт в фоне, повторяется до "
              f"--tries раз, провалы прикрывает эталон раша,")
        if доля >= 0.5:
            print(f"        но при такой доле модель будет решать реже, чем раз в "
                  f"{int(a_every_hint / max(1 - доля, 0.1))} игровых секунд — играбельно, но жидко")
        else:
            print(f"        так что в бой идти можно: потеряется примерно каждый "
                  f"{int(1 / доля)}-й такт")
        return 1
    if worst >= budget * 0.8:
        safe = int(worst * 1.38 * 1.5 / 5 + 1) * 5
        if safe > 120:
            # 120 игровых секунд — это 7 решений на эпизод в 900 с. Меньше уже
            # не политика. Значит модель в такт не встаёт, и подгонять нечего.
            print(f"        чтобы уложиться, нужен был бы --every {safe} — это "
                  f"{900 // safe} решений на эпизод. Модель в такт не встаёт; "
                  f"её место вне партии (TRAINING_PLAN, роль L2)")
        else:
            print(f"        запас меньше 20% — возьмите --every {safe} "
                  f"или модель побыстрее (nvidia/nemotron-nano-3-30b-a3b)")
    return 0


# Кандидаты в такт. Рассуждающие сюда не годятся: они пишут по тысяче токенов
# на ответ из шестидесяти. Проверено, что все эти id есть в каталоге NIM.
CANDIDATES = [
    "nvidia/llama-3.1-nemotron-51b-instruct",   # instruct, без рассуждений
    "nvidia/llama-3.1-nemotron-70b-instruct",   # instruct, крупнее
    "mistralai/mistral-nemotron",               # заявлена под агентные задачи
    "nvidia/nemotron-nano-3-30b-a3b",           # 3B активных
    "deepseek-ai/deepseek-v4-flash-0731",       # 13B активных
    "nvidia/nemotron-3.5-lightning-30b-a3b",    # текущая, рассуждающая — эталон
]


def compare(client, models: list[str], think: bool, probes: int, every: int) -> int:
    """Гоняем один и тот же запрос по моделям и печатаем таблицу. Решает не
    средняя скорость, а худший вызов: он и определяет, слепнет ли цикл."""
    budget = every / 1.38
    rows = []
    for model in models:
        waits, toks, bad, why = [], [], 0, ""
        for _ in range(probes):
            t = time.time()
            try:
                ask(client, model, "Время 0:30. Ресурсов нет, крестьян 20. "
                                   "Что строить первым? Ответь JSON.", think, retry=0)
                waits.append(time.time() - t)
                toks.append(LAST_TOKENS)
            except Exception as e:
                bad += 1
                waits.append(time.time() - t)
                why = why or str(e).replace("\n", " ")[:100]
                if waits[-1] < 3:           # мгновенный отказ повторять незачем
                    bad = probes
                    break
        worst = max(waits) if waits else 0.0
        avg_tok = sum(toks) // len(toks) if toks else 0
        rows.append((model, worst, avg_tok, bad))
        print(f"  {model:44s} худшая {worst:6.1f} с  {avg_tok:5d} ток  "
              f"сбоев {bad}/{probes}")
        if why:
            print(f"      причина: {why}")
    print(f"\nбюджет такта при 1,38× и --every {every}: {budget:.0f} с")
    годные = [r for r in rows if r[3] == 0 and r[1] < budget]
    if not годные:
        print("в такт не встала ни одна — модели место вне партии (роль L2)")
        return 1
    годные.sort(key=lambda r: r[1])
    print("годятся в такт, от быстрой к медленной:")
    for m, w, t, _ in годные:
        print(f"  {m}  ({w:.1f} с, {t} токенов)")
    print(f"\nставьте её так: python llm_policy.py --model {годные[0][0]}")
    return 0


def diagnose(d: str, human: bool = False) -> None:
    """Почему не видно ИИ-слота. Причин всего несколько, проверим по порядку."""
    чей = "человеческий слот" if human else "ИИ-слот"
    print(f"не нашёл живой {чей} в {d}")
    if not os.path.isdir(d):
        print("  каталога обмена НЕТ. Либо мост не установлен, либо --outdir при\n"
              "  установке был другой. Поставить:\n"
              '    python install_bridge.py "C:\\program files (x86)\\steam\\'
              'steamapps\\common\\Cossacks 3" --reinstall --outdir %USERPROFILE%\\coss3-io\n'
              "  Игру закрыть ДО установки: скрипты читаются при старте.")
        return
    eco = [f for f in os.listdir(d) if re.fullmatch(r"coss3_eco_P\d+\.dat", f)]
    if not eco:
        print("  каталог есть, но файлов состояния в нём нет. Мост не установлен\n"
              "  или игра ни разу не запускалась после установки.")
        return
    now = time.time()
    print(f"  файлы состояния есть ({len(eco)} шт), возраст:")
    свежие = []
    for f in sorted(eco):
        age = now - os.path.getmtime(os.path.join(d, f))
        n = int(re.fullmatch(r"coss3_eco_P(\d+)\.dat", f).group(1))
        try:
            st = Bridge(d, n).read_state() or Bridge(d, n).read_state() or {}
        except Exception:
            st = {}
        # На человеческом слоте флага bai нет вовсе — там смотрим human.
        # Печатать «ИИ=нет» про свой же слот значило бы врать в диагностике.
        свой = st.get("human") if human else st.get("bai")
        метка = "человек" if human else "ИИ"
        print(f"    {f}: {age:.0f} с назад, {метка}={'да' if свой else 'нет'}")
        if age <= 30:
            свежие.append((n, свой))
    if not свежие:
        print("  все старше 30 с — бой не идёт, игра на паузе или свёрнута.\n"
              "  Файлы могли остаться от прошлых запусков: это не признак того,\n"
              "  что мост работает сейчас.\n"
              "  Порядок такой: СНАЧАЛА начать схватку и оставить её идти,\n"
              "  и только потом запускать скрипт. Окно игры держать активным —\n"
              "  свёрнутая игра останавливает симуляцию вместе с блоком.")
    elif not any(b for _, b in свежие):
        if human:
            print("  свежие файлы есть, но ни один слот не помечен как человеческий.\n"
                  "  Проверьте: свой слот в лобби — ЧЕЛОВЕК, советник ВЫКЛЮЧЕН.\n"
                  "  Если файл пишет только компьютерный слот, значит стоит старый\n"
                  "  мост: переустановите ступенью 3 (--human-only --human-state\n"
                  "  --human-cmd) и проверьте, что progress.inc стал 1057 строк.\n"
                  "  Либо укажите слот прямо: --plind N")
        else:
            print("  свежие есть, но ни один слот не помечен как ИИ.\n"
                  "  Нужна схватка, где противник — КОМПЬЮТЕР: политика ведёт ИИ-слот,\n"
                  "  а не вашу базу. Либо укажите слот прямо: --plind N")


# С какой игровой секунды подключение считается поздним. Пятнадцать, потому что
# контейнер укладывается в 6-10 с, а всё, что заметно больше, — это уже запуск
# руками, и его надо назвать вслух.
ПОЗДНО = 15

# Сколько СВОИХ ПРОШЛЫХ ХОДОВ показывать модели. Переписки с моделью нет: каждый
# такт — отдельный вызов из двух сообщений, и всю память ей пересобирает мост.
# Пять тактов стояли здесь с самого начала и никем не проверялись; при такте в
# 20 секунд это минута сорок памяти о собственных действиях.
ОКНО_ИСТОРИИ = 5

# Сколько апгрейдов показывать модели. У нации их две с лишним сотни, и весь
# список — пять килобайт в каждом запросе.
СПИСОК_АПГРЕЙДОВ = 40

# Место апгрейда -> чем считается это здание в состоянии. Место это первая часть
# имени: 'bar.pikeman.2.1' живёт в казарме, 'mil.1' в мельнице. Соответствие
# взято из country.script, где место собирается как csid+'bar' и т.д.
МЕСТО_АПГРЕЙДА = {"cen": "centers", "mil": "mills", "bla": "smiths",
                  "bar": "ba17", "ba2": "ba18", "sta": "stables"}


def _мои_бойцы(st: dict) -> list[str]:
    """Sid'ы юнитов, которых МОЖНО нанять: 'infantry17=pikeman,hp90,...'."""
    из_поля = []
    for кусок in str(st.get("fighters", "") or "").split():
        _, _, хвост = кусок.partition("=")
        sid = хвост.split(",")[0].strip()
        if sid:
            из_поля.append(sid)
    return из_поля


# --- ПОЛИТИКА МОСТА: что модель может, что мост режет и кто это проверяет ----
#
# До 16.09 она была разбросана: предел команд литералом [:6] в двух местах,
# цели ATTACK и MOVE — двумя кортежами в разборе, порог волны и запреты —
# глобалями, а обещания модели — текстом промпта. Расхождение промпта и кода
# уже стоило проекту серии: промпт учил ставить BUILDERS 2-3 каждый такт, а код
# читал команду только вместе с BUILD, и 75 тактов ушли вхолостую.
#
# Здесь не «безопасность» — в игре необратимого нет. Здесь ОДИН ИСТОЧНИК: то,
# что сказано модели, и то, что проверяет мост, берутся отсюда оба, а
# selftest_policy.py следит, чтобы они не разошлись.
ЧИСЛИТЕЛЬНОЕ = {3: "трёх", 4: "четырёх", 5: "пяти", 6: "шести", 7: "семи",
                8: "восьми", 9: "девяти", 10: "десяти"}

