def замеры_для_критика() -> str:
    """Свод замеров проекта — критику в системную строку.

    Зачем. Критику давали дневник партии и запрет выдумывать здания, и больше
    НИЧЕГО: ни world.md, ни прошлых серий. Счёт по архиву 20.09 показал, во что
    это обошлось: из 349 гипотез за весь проект 83 звали атаковать больше или
    раньше и лишь 6 — держать армию дома, при замере, что поход втрое
    убыточнее обороны. Смещение не случайное — он просто не знал числа.

    Набор нарочно РАЗНОРОДНЫЙ: бой, время, экономика, цель. Блок, называющий
    одну цель, задаёт приоритет — 20.09 подсказка про накопление на казарму
    втрое уронила приказы UPGRADE, и лечится это не отменой подсказки, а
    конкурентами рядом в той же мере.
    """
    return ЗАМЕРЫ_ДЛЯ_КРИТИКА


def уже_проверено(путь: str = "") -> str:
    """Итоги отыгранных идей — одной строкой каждая, для критика.

    Критику дают дневник ТЕКУЩЕЙ партии и больше ничего: ни world.md, ни
    прошлых серий. Поэтому 16.09 он предложил ставить шахту золота раньше
    казармы — ровно ту идею, что серия gold_first2 отыграла 15.09 и
    опровергла: механика сработала (шахта на 188-й секунде против 358-й), а
    цель стала 0 из 9 против 2 из 9. Гипотеза стоит серии, и тратить её на уже
    отвеченный вопрос — потеря дня.

    Берём поле «итог» из experiments.ini: там результаты и так записаны.
    """
    путь = путь or os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "docker", "experiments.ini")
    if not os.path.exists(путь):
        return ""
    # interpolation=None: одиночный «%» в описании идеи ронял чтение целиком, а
    # except ниже глотал это МОЛЧА — описание идеи просто исчезало из запроса.
    # Нашлось 25.09 на «79 %» в [no_gather].
    cfg = configparser.ConfigParser(interpolation=None)
    try:
        cfg.read(путь, encoding="utf-8")
    except configparser.Error:
        return ""
    строки = []
    for имя in cfg.sections():
        итог = " ".join((cfg[имя].get("итог", "") or "").split())
        if итог:
            строки.append(f"  {имя}: {итог[:220]}")
    if not строки:
        return ""
    return ("\n\nУЖЕ ОТЫГРАНО СЕРИЯМИ — не предлагай это снова как новое:\n"
            + "\n".join(строки[:12]))


def карта_открыта(st: dict) -> bool:
    """Открыта ли карта (монгольфьер выдан всем, --balloon 2).

    Одна функция на весь мост: замок на числа врага стоит в нескольких местах,
    и две копии одного условия однажды разойдутся.
    """
    return str(st.get("map_open", "")).lower() in ("1", "true", "да", "yes")


def поле_врага(st: dict, mp: dict, поле: str):
    """Число врага по имени поля: p<номер>_<поле>. None, если его нет.

    Замок на открытую карту тут НЕ ставится: его ставит тот, кто зовёт, — и
    ставит один раз на весь блок. Две проверки в двух местах однажды разойдутся.
    """
    зн = None
    for п in range(8):
        ист = mp if f"p{п}_{поле}" in mp else st
        if st.get(f"p{п}_enemy") and f"p{п}_{поле}" in ист:
            зн = ист[f"p{п}_{поле}"]
    return зн


def чужие_со_строем(st: dict, mp: dict) -> tuple[dict, dict]:
    """Его бойцы в числах С ПОПРАВКОЙ НА СТРОЙ и сама поправка.

    Одна точка для всех мест, где мост считает размен: иначе дуэль в одной
    строке шла бы с поправкой, а «сколько нужно на отпор» — без неё.
    """
    чужие = combat_math.разобрать(поле_врага(st, mp, "fighters"))
    # Поля отрядов СО СТРОЕМ, не всех отрядов: живая игра 25.09 — крупнейший
    # отряд врага без офицера, строй у меньшего. Бонусы — лучшего из них.
    _строй = combat_math.поправка_на_строй(поле_врага(st, mp, "squads_form"),
                                           поле_врага(st, mp, "squads_form_hold"),
                                           поле_врага(st, mp, "squad_dmg"),
                                           поле_врага(st, mp, "squad_def"),
                                           поле_врага(st, mp, "squad_hdmg"),
                                           поле_врага(st, mp, "squad_hdef"))
    if чужие and (_строй["урон"] or _строй["щит"]):
        чужие = {и: combat_math.со_строем(х, _строй["урон"], _строй["щит"])
                 for и, х in чужие.items()}
    return чужие, _строй


def строки_размена(st: dict, mp: dict) -> list[str]:
    """Размен наших бойцов на его — посчитанный, а не описанный словами.

    Берём пары одного вида (наш пикинёр против его пикинёра и так далее): это
    основная масса боя, и именно её модель сравнивает, решая, идти ли в лоб.
    Числа обеих сторон лежат в состоянии с 19.09 — свои в `fighters`, его в
    `p<n>_fighters`, атака и защита уже с апгрейдами.
    """
    свои = combat_math.разобрать(st.get("fighters"))
    чужие, _строй = чужие_со_строем(st, mp)
    if not свои or not чужие:
        return []
    out = []
    # СТРОЙ ВРАГА — числом, до размена. 24.09 сверка по 329 боям показала, что
    # без этой прибавки калькулятор переоценивал нас втрое, а численный
    # перевес на факт потерь не влиял вовсе.
    if _строй["урон"] or _строй["щит"]:
        out.append(f"    СТРОЙ ВРАГА: +{_строй['урон']} к его урону и +{_строй['щит']} к "
                   f"защите ({_строй['почему']}). Всё ниже посчитано С ЭТОЙ поправкой; "
                   f"числа его бойцов в строке «в числах» — без неё")
    else:
        out.append(f"    строя у врага нет ({_строй['почему']}): размен без поправки")
    for имя, наш in свои.items():
        его = чужие.get(имя)
        if not его or not наш.get("atk") or not его.get("atk"):
            continue
        р = combat_math.размен(наш, его)
        часть = (f"    {имя}: твой бьёт его на {р['наш_урон']}, его тебя на "
                 f"{р['его_урон']} — тебе нужно {р['наших_ударов']} ударов, "
                 f"ему {р['его_ударов']}")
        if not р["скорость_учтена"]:
            часть += " (скорость удара не учтена)"
        out.append(часть)
        # ДАЛЬНОСТЬ И ФОРА. Пришли в состояние 20.09 полем `rmax`: у пикинёра
        # 1,9 единицы, у мушкетёра 15,0 — разрыв восьмикратный, и он решает,
        # сколько раз стрелок ударит, пока до него доходят.
        _дальность = (наш.get("rmax") or 0) / 100.0
        # Говорим только при ПЕРЕКОСЕ: у пары одного вида дальность одинакова,
        # и строка «твой 1.9, его 1.9» была бы шумом в каждом такте.
        if _дальность and abs(_дальность - (его.get("rmax") or 0) / 100.0) > 0.5:
            _з = combat_math.залпы_форы(наш, его)
            _с = f"      дальность: твой бьёт на {_дальность:.1f}, его на {(его.get('rmax') or 0) / 100.0:.1f}"
            if _з:
                _с += (f" — ты успеешь {_з} залп(а) по {р['наш_урон']} УРОНА, пока он "
                      f"сближается, и это {_з * р['наш_урон']} из его {его.get('hp')} жизней "
                      f"ДО контакта. Дальше ближний бой, где стрелок слаб")
            elif (его.get("rmax") or 0) > (наш.get("rmax") or 0):
                _с += " — ОН достаёт дальше тебя: сближаться придётся под огнём"
            out.append(_с)
        out.append(f"      размен {р['отношение']} — {р['вердикт'].upper()}; "
                   f"перевес нужен {р['нужен_кулаком']} к 1, если придёшь ОДНИМ "
                   f"КУЛАКОМ, и {р['нужен_цепочкой']} к 1, если растянешься "
                   f"цепочкой")
        # Что дала бы следующая ступень. Из-за порога «не меньше единицы»
        # прибавка атаки ниже его защиты не меняет НИЧЕГО, и это надо показать
        # числом, а не советом «бери атаку».
        атака = combat_math.что_даст(наш, его, прибавка_атаки=1)
        защита = combat_math.что_даст(наш, его, прибавка_защиты=1)
        сов = []
        if атака["выигрыш"] > 0:
            сов.append(f"+1 атаки: размен {атака['стало']} (урон "
                       f"{атака['урон_был']} -> {атака['урон_стал']})")
        else:
            сов.append(f"+1 атаки НИЧЕГО не даст: урон как был "
                       f"{атака['урон_был']}, так и останется — его защита выше")
        if защита["выигрыш"] > 0:
            сов.append(f"+1 защиты: размен {защита['стало']} (его урон "
                       f"{защита['его_урон_был']} -> {защита['его_урон_стал']})")
        else:
            сов.append("+1 защиты ничего не даст")
        out.append("      " + "; ".join(сов))
        # ОКУПАЕМОСТЬ: что даст следующая доступная ступень и чего она стоит.
        # Цены военных апгрейдов приходят в `upg_avail` с 19.09. Без них модель
        # видела только «дорого/дёшево» и брала дешёвое: защита на входе втрое
        # дешевле атаки, а отдачи даёт меньше.
        цены = combat_math.цены_апгрейдов(st.get("upg_avail"))
        if цены:
            запас = {"food": _чис(st.get("food")), "gold": _чис(st.get("gold"))}
            # СКОЛЬКИХ КАСАЕТСЯ. Апгрейд покупается один раз, а действует на
            # всю армию этого вида: формула игрока T_payback = C / (m * dq).
            # Без множителя счёт врал в пользу редких видов — живая партия
            # 19.09, 176 пикинёров против 31 мушкетёра.
            _сколько = _чис(st.get(combat_math.СОСТАВ_НАШ.get(имя, "")))
            for о in combat_math.окупаемость(наш, его, наш.get("игровое_имя"),
                                             цены, взятые_апгрейды(st), запас,
                                             _сколько):
                ц = ", ".join(f"{к} {v}" for к, v in о["цена"].items() if v)
                строка = (f"      {о['имя']} ({о['вид']} {о['уровень']}): размен "
                          f"станет {о['размен_станет']}, цена {ц}")
                if о.get("скольких"):
                    строка += (f", касается СРАЗУ {о['скольких']} твоих "
                              f"(общий выигрыш {о['выигрыш_армии']})")
                if о["на_тысячу_еды"] is not None:
                    строка += f" — выигрыш {о['на_тысячу_еды']} на тысячу еды"
                if not о["хватает"]:
                    строка += "; СЕЙЧАС НЕ ХВАТАЕТ"
                out.append(строка)
                # АКАДЕМИЯ — той же мерой. Её апгрейды не попадали в счёт вовсе:
                # `_ступень` разбирает имена вида `bar.pikeman.1.4`, а `aca.12`
                # для неё None. Пока академия была под запретом, это никого не
                # трогало; с 20.09 она разрешена обеим сторонам, и без счёта
                # модель видела цену, но не выигрыш — в отличие от казарменных.
                for о2 in combat_math.окупаемость_академии(
                        наш, его, АКАДЕМИЯ_ЭФФЕКТ, цены,
                        взятые_апгрейды(st), запас, _сколько):
                    _ц = ", ".join(f"{к} {v}" for к, v in о2["цена"].items() if v)
                    _что = ("урон +%d%%" % о2["что_знач"]
                            if о2["что"] == "damageperc" else
                            ("перезарядка %d%%" % о2["что_знач"]
                             if о2["что"] == "attpauseperc"
                             else "урон +%d" % о2["что_знач"]))
                    _стр = (f"      {о2['имя']} (академия, {_что}): размен "
                            f"{о2['было']} -> {о2['стало']}, цена {_ц}")
                    if _сколько:
                        _стр += f", касается СРАЗУ {_сколько} твоих"
                    if о2["на_тысячу"]:
                        _стр += f" — выигрыш {о2['на_тысячу']} на тысячу"
                    out.append(_стр)
    # ГРУППОВОЙ размен: армия на армию, по матрице «каждый наш вид против смеси
    # его видов». Дуэль один на один не отвечает на вопрос «идти ли ВСЕМ», если
    # составы разные: 19.09 у пикинёров размен вышел 10, а у мушкетёров 1, и по
    # отдельным парам не видно, что даёт их смесь.
    г = combat_math.групповой_размен(st, {k[3:]: v for k, v in st.items()
                                          if k.startswith("p1_")}, свои, чужие)
    if г:
        наш = ", ".join(f"{и} {n}" for и, n in г["состав_наш"].items())
        его_с = ", ".join(f"{и} {n}" for и, n in г["состав_его"].items())
        out.append(f"    ВСЯ АРМИЯ: твои {г['наших']} ({наш}) против его "
                   f"{г['его']} ({его_с})")
        строка = (f"      групповой размен {г['отношение']} — "
                  f"{г['вердикт'].upper()}; на этот состав нужно "
                  f"{г['нужно_кулаком']} бойцов ОДНИМ КУЛАКОМ или "
                  f"{г['нужно_цепочкой']}, если подходить по одному")
        if not г["скорость_учтена"]:
            строка += " (скорость удара не сравнима: считано по ударам)"
        out.append(строка)
    if out:
        out.insert(0, "  РАЗМЕН (посчитан мостом по формуле игры: "
                      "урон = атака минус защита по типу оружия, не меньше 1). "
                      "ДВА ЧИСЛА ПЕРЕВЕСА не описка: когда бойцы бьют ВСЕ СРАЗУ, "
                      "каждый лишний и наносит урон, и делит на себя чужой, и "
                      "нужное число растёт как КОРЕНЬ из размена; когда подходят "
                      "по одному, каждый дерётся в одиночку и нужное число растёт "
                      "ЛИНЕЙНО. Волна без сбора растягивается (замер 16.09: с "
                      "пятерых разрыв 22 единицы, и он держится всю дорогу), то "
                      "есть бьётся вторым способом. Сбор через via — это не "
                      "аккуратность, это переход с большего числа на меньшее:")
    return out


def _ч_врага(st: dict, mp: dict, поле: str):
    """Числовое поле противника или None."""
    v = поле_врага(st, mp, поле)
    try:
        return int(float(v)) if v not in (None, "") else None
    except (TypeError, ValueError):
        return None


def строки_цели(st: dict, mp: dict) -> list[str]:
    """Три числа цели «win10» словами: его база как точка, крестьяне снаружи,
    наших у его базы. Считается по сеткам brow/prow/arow; без сеток молчит
    честно — говорит, чего не видно."""
    n = _чис(st.get("grid_n")) or 16
    клетка_в_ед = (_чис(st.get("map_w")) or 256) / n
    база = coss3_map.база_врага(st)
    армия = sum(_ч_врага(st, mp, k) or 0 for k in ("inf", "shoot", "cav"))
    снаружи = coss3_map.крестьян_снаружи(st)
    всего = _ч_врага(st, mp, "peasants")
    gt = _чис(st.get("gametime"))
    out = ["  ЦЕЛЬ ПАРТИИ (три условия разом, с 7:00, и держатся 30 с): его армия "
           "меньше 10, его крестьян СНАРУЖИ меньше 10, твоих у его базы больше 50"]
    if база:
        mx, my = _чис(st.get("my_cx")), _чис(st.get("my_cy"))
        d = max(abs(база["cx"] - mx), abs(база["cy"] - my))
        сек = int(round(d * клетка_в_ед / СКОРОСТЬ_ПЕХОТЫ))
        у_базы = coss3_map.наших_у(st, база["cx"], база["cy"])
        # Сетка режет клетку на 36 («+»): 80 бойцов в одной клетке читаются как
        # 36. Для условия «больше 50» это нижняя граница, и сказать это надо.
        _насыщ = any("+" in str(st.get(f"arow{_y}") or "")[max(0, база["cx"] - 2):база["cx"] + 3]
                     for _y in range(max(0, база["cy"] - 2), база["cy"] + 3))
        out.append(f"    его база: клетка ({база['cx']},{база['cy']}) — центр его зданий "
                   f"(они в {база['клеток']} клетках), {d} клеток от твоей ратуши, ~{сек} с хода; "
                   f"«у его базы» = в двух клетках от неё")
    else:
        у_базы, _насыщ = None, False
        out.append("    его базы на карте не видно: зданий врага в сетке нет")
    out.append(f"    сейчас: его армия {армия}"
               + (" — ЕСТЬ" if армия < 10 else " — нет")
               + f"; его крестьян снаружи {снаружи}"
               + (f" из {всего} всего" if всего is not None else "")
               + (" — ЕСТЬ" if снаружи < 10 else " — нет")
               + (f"; твоих у его базы {'не меньше ' if _насыщ else ''}{у_базы}"
                  + (" — ЕСТЬ" if у_базы > 50 else " — нет")
                  if у_базы is not None else "; твоих у его базы — считать не по чему")
               + ("" if gt >= 420 else f"; до 7:00 ещё {420 - gt} с, раньше не засчитывается"))
    return out


def открытая_информация(st: dict, mp: dict) -> list[str]:
    """Что о противнике знает мост с 18.09, когда правило «как человек» снято.

    Матч идёт против ДРУГОГО БОТА по сети, и новые правила хакатона разрешают
    всю информацию о партии. block_hstate.inc (ветка idea/open-info) пишет для
    каждого чужого игрока: ресурсы (p<n>_food..coal), взятые апгрейды
    (p<n>_upg_done), что куют его здания (p<n>_train), сколько его бойцов идут
    и куда (p<n>_mv_n, средняя клетка p<n>_mv_cx/cy, сколько из них к нашей
    ратуше p<n>_mv_base), и сетку его крестьян по клеткам (prow0..15).
    Пустые поля молчат: состояние старого моста этих ключей не несёт, и
    выдумывать нули за него нельзя.
    """
    def _ч(поле):
        зн = поле_врага(st, mp, поле)
        try:
            return int(float(зн)) if зн not in (None, "") else None
        except (TypeError, ValueError):
            return None
    out: list[str] = []
    # ЕГО БАЗА КАК ТОЧКА и три числа цели (24.09, --goal win10). До этого
    # ратуши врага в состоянии не было: его здания шли только сеткой, крестьяне
    # СНАРУЖИ нигде не складывались, а «наших у его базы» модель могла лишь
    # прикинуть по картинке. Под ключом, потому что это строка промпта.
    if ЦЕЛЬ_ПАРТИИ == "win10":
        out += строки_цели(st, mp)
    рес = [(_ч(k), имя) for k, имя in (("food", "еда"), ("wood", "дерево"), ("stone", "камень"),
                                        ("gold", "золото"), ("iron", "железо"), ("coal", "уголь"))]
    if all(v is not None for v, _ in рес):
        out.append("  ресурсы противника: " + ", ".join(f"{имя} {v}" for v, имя in рес))
        _зол, _жел = рес[3][0], рес[4][0]
        if _зол is not None and _зол >= 2500:
            out.append("    у него хватает золота на вторую казарму (2500) — жди роста найма")
    _упг = поле_врага(st, mp, "upg_done")
    if _упг is not None:
        _упг = str(_упг).strip()
        out.append("  апгрейды противника взяты: " + (_упг if _упг else "ни одного"))
    # ЕГО БОЙЦЫ В ЧИСЛАХ (19.09). Имена апгрейдов говорят, ЧТО он взял, но не
    # что это дало, а свои числа модель видит в карточке бойца — сравнить своего
    # пикинёра с его она не могла. Числа те же самые, что у нас: атака и защита
    # из objbase, апгрейды уже включены.
    # ЕГО АРМИЯ УШЛА С БАЗЫ — сколько осталось дома. Пока она в походе, его
    # крестьяне защищены хуже: это и есть окно, которого модель ждала, копя
    # кулак. Мост знает числа и говорит их прямо, чтобы не пришлось вычитать.
    _вся = _ч_врага(st, mp, "army")
    _ушло = _ч_врага(st, mp, "mv_n")
    if _вся and _ушло:
        _дома = max(0, _вся - _ушло)
        _к_нам = _ч_врага(st, mp, "mv_base") or 0
        _стр = (f"  ЕГО АРМИЯ В ПОХОДЕ: из {_вся} ушли {_ушло}, дома осталось "
                f"{_дома}")
        if _к_нам:
            _стр += f"; к ТВОЕЙ базе идут {_к_нам}"
        out.append(_стр + ". Пока они в пути, его крестьяне прикрыты слабее")
        # СКОЛЬКО НУЖНО НА ПЕРЕХВАТ. Идущие к нам - это известное число
        # известных бойцов, и размен с ними считается той же формулой, что и
        # всё остальное. Модель спрашивала это словами («его армия идёт к базе,
        # успею ли»), а мост до 19.09 отвечал только «идут N».
        if _к_нам:
            _свои = combat_math.разобрать(st.get("fighters"))
            _чужие, _ = чужие_со_строем(st, mp)
            _пары = [(и, _свои[и], _чужие[и]) for и in _свои if и in _чужие
                     and _свои[и].get("atk") and _чужие[и].get("atk")]
            if _пары:
                # Берём ХУДШУЮ для нас пару: если его отряд смешанный, считать
                # по лучшей значило бы занижать нужное число.
                _худ = max((combat_math.размен(н, ч)["отношение"], и)
                           for и, н, ч in _пары)
                _er, _вид = _худ
                import math as _math
                _кулаком = int(round(_к_нам * _math.sqrt(_er) * combat_math.ЗАПАС))
                _цепочкой = int(round(_к_нам * _er * combat_math.ЗАПАС))
                _есть = _чис(st.get("my_freewar"))
                _стр2 = (f"    на перехват этих {_к_нам} нужно {_кулаком} твоих "
                         f"одним кулаком или {_цепочкой} вразнобой "
                         f"(размен по {_вид} {round(_er, 2)})")
                if _есть:
                    _стр2 += (f"; свободных дома {_есть}"
                              + (" — хватит на кулак" if _есть >= _кулаком
                                 else " — НЕ хватает даже на кулак"))
                out.append(_стр2)
    # ЕГО ОТРЯД У НАШЕЙ БАЗЫ - ПО РАССТОЯНИЮ, А НЕ ПО ФЛАГУ `mv_base`.
    #
    # Наблюдение игрока 19.09: он куёт сотню, шлёт к нам и ставит вторую
    # казарму - дома у него двести, но у нашей базы дерётся первая сотня и
    # ДОТЕКАНИЕ, а не двести разом.
    #
    # ПОЧЕМУ НЕ `mv_base`, хотя он ровно про это. Он считает бойцов, чья ЦЕЛЬ
    # ПРИКАЗА ближе 60 единиц карты к нашей ратуше (block_hstate.inc:968), а
    # это 3,75 клетки при сетке 16 на 256 - почти вплотную. Живая партия
    # 19.09: его армия дошла до 201, отряды по 21-48 стояли в 3-5 клетках от
    # нас с 10:27 и до конца, марш шёл ЧЕРЕЗ СЕРЕДИНУ карты (его центр 13,10 ->
    # цель 13,5-8 при нашей базе 14,2), а `mv_base` был НОЛЬ во всех тактах.
    # Флаг не врёт - он отвечает на другой вопрос, слишком узкий.
    #
    # ПОЧЕМУ ПОРОГ ПЯТЬ КЛЕТОК, а не по боям. По 252 тактам (20 партий) наша
    # армия убывала на 3+ при своих дома ровно ДВАЖДЫ, и в обоих его отряд был
    # в 1-2 клетках: боёв у базы почти нет, калибровать не на чем. Поэтому
    # основание другое и честное - ВРЕМЯ ПОДХОДА: клетка это map_w/grid_n = 16
    # единиц, пехота идёт 2,0 в секунду, значит пять клеток - около сорока
    # секунд. Ближе сорока секунд - он уже здесь, что бы ни говорил флаг.
    #
    # Порог 60 единиц в `.inc` не трогаю: правка в python дешевле и не роняет
    # тик, а `mv_base` нужен и в других местах как «цель приказа - наша база».
    _вся_а = _ч_врага(st, mp, "army") or 0
    if _вся_а > 0 and not (ЧЕСТНО and not карта_открыта(st)):
        _нц = coss3_map.центр_сетки(st, "arow") or {}
        _бx, _бy = _нц.get("cx"), _нц.get("cy")
        _клетки_его = coss3_map.клетки_силы(st, "frow", _вся_а) if _бx is not None else []
        # Берём БЛИЖАЙШИЙ заметный отряд: одиночки на карте не угроза и не цель.
        _ближние = [(max(abs(c["x"] - _бx), abs(c["y"] - _бy)), c)
                    for c in _клетки_его if c["n"] >= 5]
        _ближние = [(d, c) for d, c in _ближние if d <= 5]
        if _ближние:
            _d, _отряд = min(_ближние, key=lambda t: t[0])
            _n = _отряд["n"]
            _своб = _чис(st.get("my_freewar"))
            _перевес_д = round(_своб / max(1, _n), 2)
            _ост = max(0, _вся_а - _n)
            _клетка_в_ед = (_чис(st.get("map_w")) or 256) / (_чис(st.get("grid_n")) or 16)
            _сек = int(_d * _клетка_в_ед / СКОРОСТЬ_ПЕХОТЫ)
            _где = ("УЖЕ У ТВОЕЙ БАЗЫ" if _d <= 2
                   else f"в {_d} клетках от твоей базы, это ~{_сек} с хода")
            _каз = _ч_врага(st, mp, "ba17") or 0
            _в_мин = int(_каз * ПОДКРЕПЛЕНИЕ_КАЗАРМЫ * 60)
            # СКОЛЬКО НУЖНО НА ЭТОТ ОТРЯД — тем же расчётом, что и перехват
            # выше: размен по ХУДШЕЙ для нас паре и запас. Считается ЗДЕСЬ, до
            # строки про дотекание, потому что от ответа зависит и она: звать
            # «бей» в такте, где бить нечем, значит спорить с самим собой.
            _нужно = _разм = _вид_о = None
            if УДАР_ПО_ОТРЯДУ and _d >= 3 and _своб:
                import math as _math2
                _св = combat_math.разобрать(st.get("fighters"))
                _чж, _ = чужие_со_строем(st, mp)
                _пр = [(combat_math.размен(_св[и], _чж[и])["отношение"], и)
                       for и in _св if и in _чж
                       and _св[и].get("atk") and _чж[и].get("atk")]
                if _пр:
                    _разм, _вид_о = max(_пр)
                    _нужно = int(round(_n * _math2.sqrt(_разм) * combat_math.ЗАПАС))
            _хватает = _нужно is None or _своб >= _нужно
            _с = (f"  ЕГО ОТРЯД {_n} — {_где} ({_отряд['x']},{_отряд['y']}). "
                 f"Это НЕ вся его армия {_вся_а}: остальные {_ост} дальше и подойдут "
                 f"НЕ РАЗОМ. Свободных у тебя {_своб}, перевес против ЭТОГО отряда "
                 f"{_перевес_д}")
            if _в_мин:
                _с += (f"; его {_каз} казарм добавят ~{_в_мин} за минуту — это "
                      + ("ДОТЕКАНИЕ, бей этот отряд ДО подхода следующих"
                         if _хватает else
                         "ДОТЕКАНИЕ: чем дольше ждёшь, тем их больше"))
            out.append(_с)
            # СВЯЗКА 1: ГОТОВЫЙ ПРИКАЗ РЯДОМ СО СТРОКОЙ. Сама строка говорится
            # с 19.09, и её мало: команда, названная без числа и без готового
            # приказа, всё равно что не названа (MOVE в 75 процентах тактов —
            # ноль приказов; UPGRADE в 2 процентах — 56 приказов, замер 20.09).
            #
            # Только при _d >= 3: ближе говорит блок `набег` (радиус у_базы
            # два), и два приказа на один отряд в одном такте — это спор с
            # самим собой, а не подсказка.
            # БЕЗ ПРОВЕРКИ СИЛЫ связка звала бы бить отряд 8 последними
            # десятью бойцами при 130 его рядом — на состояниях base21 такой
            # такт есть, и совет был бы вреден. Не хватает — сказать вслух, а
            # не промолчать: молчаливый отброс неотличим от бездействия.
            if УДАР_ПО_ОТРЯДУ and _d >= 3 and _своб:
                if _хватает:
                    out.append(
                        f'  ОТБИТЬ ЕГО ЗДЕСЬ, одним кулаком: '
                        f'{{"cmd":"ATTACK","count":"all","target":"cell",'
                        f'"cx":{_отряд["x"]},"cy":{_отряд["y"]}}}')
                    _почему = (f"    почему здесь: у своей базы размен 0,67 врага за "
                               f"твоего, в поле 0,19 (замер 30 партий) — подкрепление "
                               f"из казарм выходит рядом. Против ЭТОГО отряда перевес "
                               f"{_перевес_д}, против всей его армии было бы "
                               f"{round(_своб / max(1, _вся_а), 2)}")
                    if _нужно is not None:
                        _почему += (f"; на эти {_n} нужно {_нужно} одним кулаком "
                                    f"(размен по {_вид_о} {round(_разм, 2)}), "
                                    f"свободных {_своб}")
                    out.append(_почему)
                    out.append(
                        f"    плата: пока бьёшь эти {_n}, дом без прикрытия, а "
                        f"остальные {_ост} подходят; ждать дома дешевле по размену, "
                        f"но тогда он сам выбирает миг и место")
                else:
                    out.append(
                        f"    бить этот отряд НЕЧЕМ: на {_n} нужно {_нужно} одним "
                        f"кулаком (размен по {_вид_о} {round(_разм, 2)}), свободных "
                        f"{_своб}. Держи их дома — у базы размен 0,67 против 0,19 в "
                        f"поле, и подкрепление выходит из казарм сюда")
    _бой = поле_врага(st, mp, "fighters")
    if _бой and str(_бой).strip() not in ("", "none-found"):
        _части = []
        for _к in str(_бой).split():
            if "=" in _к:
                _имя, _зн = _к.split("=", 1)
                _части.append(f"{_имя} {_зн.replace(',', ' ')}")
        if _части:
            out.append("  его бойцы в числах (апгрейды уже учтены): "
                       + "; ".join(_части))
        # РАЗМЕН СЧИТАЕТ МОСТ, а не модель в уме. Формула — из кода игры:
        # урон = атака минус защита цели по типу оружия, не меньше единицы
        # (lib/miscext2.script:380). Модель получает готовое отношение и порог
        # численного перевеса; вычитать и делить каждый такт ей незачем, а
        # ошибиться в этом легко: 19.09 она пять раз подряд брала ступени
        # атаки, не заметив, что первые из них не давали НИЧЕГО — урон упирался
        # в единицу.
        out += строки_размена(st, mp)
    _тр = поле_врага(st, mp, "train")
    if _тр is not None:
        _тр = str(_тр).strip()
        out.append("  противник куёт сейчас: " + (_тр if _тр else "НИЧЕГО — его здания стоят пустые"))
    # ПОТЕРИ ПО СЧЁТУ ДВИЖКА (20.09): gPlayer[pl].stat.killed считает погибших
    # у их владельца, захват исключён. До этого убитого крестьянина мост
    # угадывал по падению счётчика, а тот падает и когда крестьяне уходят в
    # шахту: 20.09 волна стояла в семи клетках, а «веха» уже была взята.
    _пкр, _пми = _ч("pea_lost"), _ч("mil_lost")
    if _пкр is not None:
        out.append(f"  ЕГО ПОТЕРИ с начала партии (счёт движка): крестьян {_пкр}, бойцов {_пми or 0}; "
                   f"наши: крестьян {_чис(st.get('my_pea_lost'))}, бойцов {_чис(st.get('my_mil_lost'))}")
    _n, _b = _ч("mv_n"), _ч("mv_base")
    if _n is not None:
        if _n <= 0:
            out.append("  бойцы противника стоят: ни у одного нет приказа идти")
        else:
            _cx, _cy = _ч("mv_cx"), _ч("mv_cy")
            _mx, _my = _чис(st.get("my_cx")), _чис(st.get("my_cy"))
            куда = ""
            if _cx is not None and _cy is not None:
                куда = f", средняя цель клетка ({_cx},{_cy})"
                if "my_cx" in st:
                    if _cx == _mx and _cy == _my:
                        куда += " — это КЛЕТКА ТВОЕЙ РАТУШИ"
                    else:
                        куда += f" — это {coss3_map.compass(_cx - _mx, _cy - _my)} от твоей ратуши"
            out.append(f"  бойцов противника в движении: {_n}{куда}")
            # ПО ОТРЯДАМ (24.09, --enemy-march). Средняя клетка врёт, когда
            # отрядов два: точка между ними. Сетка целей drow даёт каждый.
            if ПОХОДЫ_ВРАГА:
                for _о in coss3_map.походы_врага(st)[:4]:
                    _с = (f"    отряд {_о['n']} идёт в клетку ({_о['x']},{_о['y']}) — "
                          f"{_о['сторона']} от твоей ратуши, {_о['до_нас']} кл. от неё")
                    if _о["куда"]:
                        _с += f", это {_о['куда']}"
                    if _о.get("на_месте"):
                        _с += ("; его бойцы УЖЕ стоят в этой клетке — приказ исполнен "
                               "или это стоянка, а не поход")
                    elif _о["откуда"] is not None:
                        _с += (f"; ближайший его отряд к этой цели стоит в "
                               f"({_о['откуда'][0]},{_о['откуда'][1]}), ему {_о['клеток']} кл. "
                               f"— дойдёт за ~{_о['сек']} с (кто именно идёт, состояние не знает; это ближайший)")
                    out.append(_с)
            # Наперерез ВОЛНЕ: контейнер на маке 19.09 показал, что к нашей базе
            # враг может не пойти вовсе, а его 36-73 бойца двинулись в клетки
            # между базами ровно тогда, когда вышел наш кулак. Цель их приказа
            # рядом с клеткой нашей волны — это перехват, и сказать это надо
            # до того, как колонна растянется.
            _wx, _wy, _wn = _чис(st.get("wave_cx")), _чис(st.get("wave_cy")), _чис(st.get("wave_n"))
            if (_cx is not None and _cy is not None and _wn > 0 and "wave_cx" in st
                    and abs(_cx - _wx) <= 2 and abs(_cy - _wy) <= 2):
                out.append(f"  ИДУТ НАПЕРЕРЕЗ ТВОЕЙ ВОЛНЕ: их цель ({_cx},{_cy}) рядом с твоей "
                           f"волной в ({_wx},{_wy}), волна {_wn} против {_n} идущих. Решай сейчас: "
                           f"RETREAT, пока не растянулись, или ENGAGE всем кулаком")
            if _b:
                out.append(f"  ИДУТ НА ТЕБЯ: {_b} бойцов противника с приказом в точку ближе 60 "
                           f"от твоей ратуши. Собирай отпор ОДНИМ кулаком у своих зданий "
                           f"(ATTACK target=cell в клетку их прихода), стрелков — за пехоту")
    клетки = coss3_map.крестьяне_врага(st)
    if клетки:
        части = [f"({c['x']},{c['y']}) крестьян {c['крестьян']}, бойцов врага рядом {c['бойцов_рядом']}"
                 for c in клетки]
        out.append("  крестьяне противника по клеткам (сначала где охраны меньше): " + "; ".join(части))
        лучшая = клетки[0]
        if лучшая["бойцов_рядом"] == 0:
            out.append(f"    КЛЕТКА БЕЗ ОХРАНЫ: ({лучшая['x']},{лучшая['y']}) — {лучшая['крестьян']} крестьян "
                       f"и ни одного бойца в ней и вокруг. ATTACK peasants пошёл бы к БЛИЖАЙШЕМУ "
                       f"крестьянину под их армией; бей сюда: "
                       f'{{"cmd":"ATTACK","count":<все свободные>,"target":"cell","cx":{лучшая["x"]},"cy":{лучшая["y"]}}}')
    out += строки_оценки(оценка_обстановки(st, mp))
    return out


# Замеры проекта, на которых стоит оценка обстановки. Не веса, а числа из игры:
# ПОДКРЕПЛЕНИЕ_КАЗАРМЫ — одна казарма даёт +21 бойца за 92 с (17.09, живая
# игра); СКОРОСТЬ_ПЕХОТЫ — RETREAT 18.09: 46 бойцов из 107 от базы вернулись
# за 45 с, марш руками: сбор за 80-105 с, — берём 2,0 единицы в секунду, это
# нижняя оценка; ПОРОГ_ПЕРЕВЕСА — тот же 1,3, что стоял в проверенном контракте
# марша (hold_if_outnumbered), при нём удар 25 против 36+ был остановлен верно.
ПОДКРЕПЛЕНИЕ_КАЗАРМЫ = 21.0 / 92.0      # бойцов в секунду на одну казарму
# «Всех свободных» числом: больше, чем бывает бойцов в партии. Игра сама возьмёт
# столько, сколько есть простаивающих, — обрезать здесь нечего.
ВСЕ_СВОБОДНЫЕ = 9999
СКОРОСТЬ_ПЕХОТЫ = 2.0                   # единиц карты в секунду
ПОРОГ_ПЕРЕВЕСА = 1.3
# Горизонт партии виден и промпту: «что успеет окупиться» без него не считается.
# Ставится из ключа --horizon в main, умолчание то же (1200 с с 19.09).
ГОРИЗОНТ = 1200
# СМЕНА СОСТАВА (связка 4 из СВЯЗКИ.md). Говорить ли вслух, что наш основной
# вид упёрся в пол урона, а другой — нет. По умолчанию ВЫКЛЮЧЕНО: связка
# меряется ключом против базы, иначе отличий выходит два и разделить их нечем
# (так вышло со stage_num 20.09).
СМЕНА_СОСТАВА = 0
# УДАР ПО ОТРЯДУ У БАЗЫ (связка 1 из СВЯЗКИ.md). Давать ли ГОТОВЫЙ ПРИКАЗ
# рядом со строкой «ЕГО ОТРЯД N — в K клетках». Строка есть с 19.09, приказа
# при ней нет, и по правилу матрицы это то же, что молчание: MOVE упомянут в
# 75 процентах тактов и отдан ноль раз, UPGRADE назван в 2 процентах и отдан
# 56 раз, потому что рядом стоят цена и выигрыш (замер 20.09, 51 такт).
# По умолчанию ВЫКЛЮЧЕНО: связка меряется ключом против базы.
УДАР_ПО_ОТРЯДУ = 0
# ВСТРЕТИТЬ УГРОЗУ СОБРАННЫМИ (связка 8 из СВЯЗКИ.md). Наблюдение игрока
# 20.09: армия стоит там, где вышла из казарм, и в бой вступает частями.
# По умолчанию ВЫКЛЮЧЕНО: связка меряется ключом против базы.
ВСТРЕТИТЬ_УГРОЗУ = 0
# ОТДАЧА И РАСХОД (замысел игрока 21.09 по калькулятору производственных
# функций). В формуле моста не было члена расхода C_r вовсе: `net` — уже
# случившееся изменение запаса, а сколько даст ПОСТАВЛЕННЫЙ сюда человек, мост
# не говорил нигде. Счёт по base24: простаивают 12,5 процента всего труда
# крестьян, и в 100 процентах этих крестьяно-секунд поставить их БЫЛО КУДА
# (дерево и камень открыты во всех 422 тактах с простоем), а в 29 и 24
# процентах на дереве и камне стоял НОЛЬ человек. По умолчанию ВЫКЛЮЧЕНО:
# меряется ключом --need против базы.
ПОКАЗ_РАСХОДА = 0
# Доля посланных, которая должна ДОЙТИ до клетки сбора, чтобы марш пошёл в
# бой. Две трети: большинство с запасом на потери по дороге. Ниже половины
# кулака нет вовсе, а ждать последнюю треть дороже — хвост идёт столько же,
# сколько вся волна (растянутость мерена 16.09: с пятерых разрыв 22 единицы
# и держится всю дорогу).
ДОЛЯ_СБОРА = 2 / 3
СТОП_ТИШИНЫ = 30          # --stall: сколько ждать состояния
ПОТЕРИ_БЫЛО: dict = {}    # накопительные потери прошлого такта
ПЛАНКА_ЧЕСТНАЯ = 0.0      # --gather-share: доля от min(послано, живая армия)
БЕЗ_СБОРА = False         # --no-gather: клетка сбора не заводится ВООБЩЕ, удар
                          # идёт прямо. Бьёт в механизм, найденный 25.09:
                          # убийства идут при совместной клетке с его
                          # крестьянами (13 / 8 / 4 процента тактов у
                          # base27 / base28 / tier1, и 98 из 102 убитых у
                          # base27 именно там), а решает ПРИСУТСТВИЕ, не масса —
                          # base27 убила 98 при медианно 7,5 бойцах в клетке,
                          # tier1 с 18 не убил ни одного. Сбор же только
                          # откладывает: до клетки доходит 29 процентов колонны
                          # у tier1 и 8 у base28, а оба выхода из «сбора»
                          # требуют половины и двух третей, то есть не
                          # срабатывают (порог взят 1 раз из 55 тактов).
ПОТОЛОК_ИССЯКА = False    # --drain-cap: второй выход из сбора («приток иссяк»)
                          # считается по СВОЕЙ колонне, а не по wave_n и не по
                          # накопленному «послано». Замер 25.09 по 91 такту
                          # сбора: по отдельности ни одна половина не
                          # развязывает выход (0 из 91), вместе — 18 из 53 у
                          # base27 и 0 у base28/tier1.
ПРЕДЕЛ_СБРОСОВ = 0        # --gather-resets: сколько раз подкрепление вправе
                          # обнулить срок сбора. 0 — без предела, как было.
ПОХОДЫ_ВРАГА = False      # --enemy-march 1: его идущие бойцы ПО ОТРЯДАМ (куда, откуда,
                          # когда дойдут) по сетке drow вместо одной средней клетки.
ЦЕЛЬ_ПАРТИИ = ""          # --goal win10: новая цель партии (решение игрока 24.09) —
                          # армия врага <10, крестьян снаружи <10, наших у его
                          # базы >50, с 7:00 и держится 30 с. Первый шаг (24.09,
                          # мак): три числа цели в запросе. Пусто — как было.


def оценка_обстановки(st: dict, mp: dict) -> dict:
    """Локальная оценка по клеткам с крестьянами врага и прогноз на минуту.

    Формула игрока от 19.09 (situation awareness: факты → смысл → прогноз →
    безопасность), сведённая к тому, что в этой партии измеримо. Глобальный
    счёт одним числом не считается нарочно: на десятой минуте армии РАВНЫ, а
    партия уже проиграна — единый счёт это спрятал бы. (Прежде здесь стояло «враг
    восполняет 15,9 в минуту против 4,4»; число заменено 20.09 на 12,3 против
    13,1 по base21 — темпы сравнялись, но довод против единого счёта остался.)
    Считается:

    * по каждой клетке с крестьянами врага — его бойцы в ней и вокруг, его
      подкрепление (остальная армия по центру frow) и когда оно дойдёт, наш
      кулак (живая волна, иначе свободные у центра arow) и когда дойдёт он,
      перевес К МОМЕНТУ ПРИХОДА и вердикт по ПОРОГ_ПЕРЕВЕСА;
    * прогноз на 60 с: прирост армий из очередей и числа казарм, приход его
      идущих бойцов к их цели;
    * режим — одно слово по правилам, а не число: ОПАСНОСТЬ (идут к базе или
      голод), ПЕРЕХВАТ (наперерез волне), УДАР (есть клетка с перевесом),
      КОПИТЬ (иначе).

    Все слагаемые видны модели и ложатся в трассу, чтобы серия потом сказала,
    при каких отношениях волны убивали, а при каких гибли, — порог 1,3 взят из
    контракта марша и подлежит той же проверке.
    """
    if not any(f"prow{y}" in st for y in range(16)):
        return {}
    n = _чис(st.get("grid_n")) or 16
    клетка_в_ед = (_чис(st.get("map_w")) or 256) / n
    def ед(ax, ay, bx, by):
        return ((ax - bx) ** 2 + (ay - by) ** 2) ** 0.5 * клетка_в_ед
    def секунд(d):
        return int(round(d / СКОРОСТЬ_ПЕХОТЫ))
    def _ч(поле):
        зн = поле_врага(st, mp, поле)
        try:
            return int(float(зн)) if зн not in (None, "") else None
        except (TypeError, ValueError):
            return None
    # наш кулак: живая волна, иначе свободные у центра своей армии
    # Волна жива только если её ОТПРАВЛЯЛИ: wave_n считает всех своих вдали от
    # базы, и без отправки там 1-2 отбившихся (контейнер 19.09, 5:05-7:37 —
    # оценка мерила «кулак 2» при 28 свободных дома).
    wave_n = _чис(st.get("wave_n"))
    центр = coss3_map.центр_сетки(st, "arow") or {"cx": _чис(st.get("my_cx")), "cy": _чис(st.get("my_cy"))}
    дома = {"n": _чис(st.get("my_freewar")), "cx": центр.get("cx"), "cy": центр.get("cy"), "что": "свободные"}
    # Кулак — БОЛЬШАЯ из двух групп: живая волна или свободные дома. Контейнер
    # 19.09: волна из 9 в поле держала оценку на «кулак 9» при 49 свободных
    # дома, и все клетки читались «нет».
    if wave_n > 0 and _чис(st.get("wave_sent")) > 0 and "wave_cx" in st and wave_n >= дома["n"]:
        кулак = {"n": wave_n, "cx": _чис(st.get("wave_cx")), "cy": _чис(st.get("wave_cy")), "что": "волна"}
    else:
        кулак = дома
    их_центр = coss3_map.центр_сетки(st, "frow")
    их_всего = _ч("army") or (их_центр.get("n", 0) if их_центр else 0)
    клетки = []
    for c in coss3_map.крестьяне_врага(st, топ=6):
        x, y = c["x"], c["y"]
        # «Рядом» и подкрепление считаются ИЗ ОДНОГО источника — поклеточной
        # силы с разложенной недостачей знака '+'. Брать «рядом» из
        # `крестьяне_врага` нельзя: там '+' читается как 36, а раньше недостачу
        # добирал остаток армии, и с поклеточным счётом она просто пропадала —
        # у ратуши врага «рядом» выходило 36 вместо 50.
        рядом = 0
        наш_eta = секунд(ед(кулак["cx"], кулак["cy"], x, y)) if кулак["cx"] is not None else None
        # Подкрепление считается ПО КЛЕТКАМ, а не одним комком из центра масс
        # его армии. Центр масс лежит между отрядами — там, где никого нет, —
        # и его eta делал условие «успеют» истинным ВСЕГДА: 1229 случаев из
        # 1229 (`assess_report.py`, 19.09). «Перевес» тогда читался как «наш
        # кулак против ВСЕЙ его армии», то есть мерил глобальный перевес, от
        # которого проект отказывался нарочно, — и порог 1,3 на такой величине
        # после десятой минуты недостижим. (Довод опирался на темпы 15,9
        # против 4,4; по base21 они 12,3 против 13,1 — вывод про глобальный
        # перевес держится не на них, а на том, что его подкрепление успевает
        # всюду: 299 случаев из 417.)
        # Клетки внутри 3x3 вокруг цели пропускаются: они уже сосчитаны в
        # «рядом» (`coss3_map.крестьяне_врага`), иначе те же бойцы вошли бы
        # дважды.
        подкреп = успело = 0
        их_eta = None
        # ОТРЯДЫ: его сила не комок, а несколько групп, разнесённых расстоянием.
        # Держим их ПООТДЕЛЬНО, со сроком подхода каждой, чтобы можно было
        # спросить не «сколько успеет всего», а «сколько встретит НАС В МОМЕНТ
        # ПРИХОДА и сколько дотечёт потом».
        отряды = []
        for б in coss3_map.клетки_силы(st, "frow", их_всего):
            if max(abs(б["x"] - x), abs(б["y"] - y)) <= 1:
                рядом += б["n"]        # та же клетка и восемь соседних
                continue
            подкреп += б["n"]
            d = секунд(ед(б["x"], б["y"], x, y))
            отряды.append({"n": б["n"], "eta": d})
            if их_eta is None or d < их_eta:
                их_eta = d
            # успевает тот, кто дойдёт не позже нас плюс полминуты боя
            if наш_eta is not None and d <= наш_eta + 30:
                успело += б["n"]
        отряды.sort(key=lambda o: o["eta"])
        # УШЕДШИЕ НЕ ЗАЩИТНИКИ. Сетка показывает, где его армия СТОИТ, и до
        # 19.09 этого хватало: она не двигалась. Но в движении она 43 процента
        # тактов, и тогда счёт врал в его пользу — тот, кто марширует к НАШЕЙ
        # базе, не развернётся защищать своих крестьян, а формула числила его
        # защитником. Живой случай: армия 109, из них 36 идут к нам, у цели
        # стоят двое — «встретит» выходило 109, перевес 0,75 и вердикт «нет»;
        # без ушедших это 73 и перевес 1,12.
        #
        # Вычитаем ТОЛЬКО тех, кто не успеет вернуться: от клетки, куда он
        # ведёт своих (p<n>_mv_cx/cy), до нашей цели путь считается так же, как
        # для стоящих. Если успеет — не вычитаем, оговорка не нужна.
        ушли = _ч("mv_n") or 0
        к_нам = _ч("mv_base") or 0
        ушло_мимо = 0
        if ушли > 0:
            # Идущие К НАШЕЙ БАЗЕ вычитаются ВСЕГДА, не по геометрии: они
            # придут к нам и свяжутся боем там. Живой случай 19.09: их 36 шли к
            # нам и по расстоянию «успевали» вернуться (140 с против наших
            # 149), поэтому чистый счёт пути их не отсекал — а защитниками они
            # не были.
            ушло_мимо = к_нам
            # Остальных ушедших судим по пути: доберутся ли они от своей цели
            # до нашей раньше, чем мы.
            прочие = ушли - к_нам
            мx, мy = _ч("mv_cx"), _ч("mv_cy")
            if прочие > 0 and мx is not None and мy is not None:
                назад = секунд(ед(мx, мy, x, y))
                if наш_eta is not None and назад > наш_eta + 30:
                    ушло_мимо += прочие
            # Больше, чем успевало подойти, вычесть нельзя: ушедшие уже
            # посчитаны среди «успевших» по своим клеткам.
            ушло_мимо = min(ушло_мимо, успело)
        успело = max(0, успело - ушло_мимо)
        # Два перевеса: худший случай (успевающие к нам подойдут) и лучший
        # (никто не двинется — армия стоит у ратуши, как стояла всю партию
        # 19.09). Худший не должен глушить лучший: шахта без охраны с шестью
        # крестьянами — это и есть цель матча, и риск при ней надо назвать,
        # а не спрятать за словом «спорно».
        встретит = рядом + успело
        перевес = кулак["n"] / max(1, встретит)
        перевес_без = кулак["n"] / max(1, рядом)
        # СКОЛЬКО ВСТРЕТИТ НАС В МОМЕНТ ПРИХОДА, а не когда-нибудь. Отряд,
        # который придёт через минуту после нас, в первом столкновении не
        # участвует: он ДОТЕКАЕТ. Складывать его с теми, кто уже на месте,
        # значит мерить удар трёхсот там, где бой идёт против ста.
        сразу = sum(o["n"] for o in отряды
                     if наш_eta is not None and o["eta"] <= наш_eta)
        сразу = max(0, сразу - ушло_мимо)
        встретит_сразу = рядом + сразу
        перевес_сразу = кулак["n"] / max(1, встретит_сразу)
        # ДОТЕКАНИЕ: сколько подойдёт ещё за полминуты и за минуту после
        # контакта. Это не угроза «сейчас», это скорость, с которой перевес
        # тает, — и она решает, хватит ли времени добить крестьян и уйти.
        дотекание = []
        if наш_eta is not None:
            for через in (30, 60):
                дотекание.append(sum(
                    o["n"] for o in отряды
                    if наш_eta < o["eta"] <= наш_eta + через))
        # Оговорка «если его армия не двинется» законна ТОЛЬКО когда мы приходим
        # первыми: контейнер 19.09, 4:49 — его 16 доходили до клетки за 22 с,
        # наши 5 за 80, а вердикт «можно, если» повёл модель слать пятерых.
        мы_первые = (их_eta is None) or (наш_eta is not None and наш_eta < их_eta)
        # ВЕРДИКТ УДАРА судится по прежнему числу. Разделение «встретит сразу»
        # и «дотекание» здесь проверено и оказалось ПУСТЫМ: замер base20 по 132
        # состояниям — наш подход до цели медиана 120 с, его отряды доходят за
        # 18 с (максимум 96), и бойцов, приходящих ПОЗЖЕ нас, ноль в 118 тактах
        # из 118. К нашему приходу у цели уже все, дотекать некому. Числа всё
        # равно кладём в клетку: на другой карте разрыв может появиться, и
        # тогда это будет видно по трассе задним числом.
        if кулак["n"] <= 0:
            вердикт = "нет"
        elif перевес >= ПОРОГ_ПЕРЕВЕСА:
            вердикт = "можно"
        elif перевес_без >= ПОРОГ_ПЕРЕВЕСА and мы_первые:
            вердикт = "можно, если его армия не двинется"
        elif перевес >= 0.8:
            вердикт = "спорно"
        else:
            вердикт = "нет"
        клетки.append({"x": x, "y": y, "крестьян": c["крестьян"], "их_рядом": рядом,
                       "их_подкрепление": подкреп, "их_успеют": успело,
                       "ушли_мимо": ушло_мимо,
                       "их_eta": их_eta, "наш_кулак": кулак["n"],
                       "наш_eta": наш_eta, "встретит": встретит, "перевес": round(перевес, 2),
                       "встретит_сразу": встретит_сразу,
                       "перевес_сразу": round(перевес_сразу, 2),
                       "дотекание": дотекание,
                       "отрядов": len(отряды),
                       "перевес_без_подкрепления": round(перевес_без, 2), "вердикт": вердикт})
    порядок = {"можно": 0, "можно, если его армия не двинется": 1, "спорно": 2, "нет": 3}
    # Внутри одного вердикта первой идёт БОЛЕЕ БЕЗОПАСНАЯ клетка (перевес без
    # подкрепления), потом где крестьян больше: цель матча — убить хотя бы
    # одного, а не больше всех.
    клетки.sort(key=lambda k: (порядок[k["вердикт"]], -k["перевес_без_подкрепления"], -k["крестьян"]))
    # прогноз на минуту
    их_каз = _ч("ba17") or 0
    их_очередь = str(поле_врага(st, mp, "train") or "")
    их_куют = их_каз if any(w in их_очередь for w in ("pikeman", "musk", "dragoon", "infantry", "shooter")) else 0
    наши_каз = _чис(st.get("ba17"))
    наши_очередь = str(st.get("ba_queues") or "")
    наши_куют = sum(1 for q in наши_очередь.split(",") if q and not q.endswith(":none") and "none" not in q) if наши_каз else 0
    голод = _чис(st.get("food")) < 500
    прогноз = {"их_армия": их_всего, "их_через_60": их_всего + int(их_куют * ПОДКРЕПЛЕНИЕ_КАЗАРМЫ * 60),
               "наша_армия": _чис(st.get("mil_inf")) + _чис(st.get("mil_shooters")) + _чис(st.get("mil_cav")),
               "наша_через_60": (_чис(st.get("mil_inf")) + _чис(st.get("mil_shooters")) + _чис(st.get("mil_cav"))
                                 + (0 if голод else int(наши_куют * ПОДКРЕПЛЕНИЕ_КАЗАРМЫ * 60))),
               "голод": голод}
    mv_n, mv_b = _ч("mv_n") or 0, _ч("mv_base") or 0
    # ОБОРОНА В ЧИСЛАХ - в снимок, чтобы серия могла их посчитать. Бой у нашей
    # базы принимают ПРИШЕДШИЕ, а не вся его армия; остальные дотекают из
    # казарм. Без этих полей «перевес у базы» по трассе задним числом не
    # восстановить.
    прогноз["к_нашей_базе"] = mv_b
    прогноз["у_него_дома"] = max(0, их_всего - mv_n)
    прогноз["наших_дома"] = _чис(st.get("my_freewar"))
    прогноз["перевес_у_базы"] = round(
        _чис(st.get("my_freewar")) / max(1, mv_b), 2) if mv_b else None
    прогноз["его_дотекание_в_минуту"] = int(
        (_ч("ba17") or 0) * ПОДКРЕПЛЕНИЕ_КАЗАРМЫ * 60)
    mv_cx, mv_cy = _ч("mv_cx"), _ч("mv_cy")
    if mv_n and mv_cx is not None and их_центр:
        прогноз["идущих"] = mv_n
        прогноз["дойдут_через"] = секунд(ед(их_центр["cx"], их_центр["cy"], mv_cx, mv_cy))
        прогноз["куда"] = (mv_cx, mv_cy)
    # режим
    перехват = (mv_n and mv_cx is not None and кулак["что"] == "волна"
                and abs(mv_cx - кулак["cx"]) <= 2 and abs(mv_cy - кулак["cy"]) <= 2)
    if mv_b > 0 or голод:
        режим = "ОПАСНОСТЬ"
    elif перехват:
        режим = "ПЕРЕХВАТ"
    elif клетки and клетки[0]["вердикт"] == "можно":
        режим = "УДАР"
    elif клетки and клетки[0]["вердикт"].startswith("можно"):
        режим = "ШАНС"
    else:
        режим = "КОПИТЬ"
    return {"клетки": клетки[:3], "прогноз": прогноз, "режим": режим, "кулак": кулак}


def строки_оценки(оц: dict) -> list[str]:
    """Оценка обстановки словами для запроса: слагаемые видны, число не прячет их."""
    if not оц:
        return []
    out = ["  ОЦЕНКА ОБСТАНОВКИ (счёт моста по замерам, не мнение):"]
    п = оц["прогноз"]
    s = (f"    прогноз на минуту: у врага {п['их_армия']} -> ~{п['их_через_60']}, "
         f"у тебя {п['наша_армия']} -> ~{п['наша_через_60']}")
    if п.get("голод"):
        s += " (еда ниже 500 — твой найм СТОИТ)"
    if п.get("идущих"):
        s += f"; его {п['идущих']} идущих дойдут до {п['куда']} через ~{п['дойдут_через']} с"
    out.append(s)
    к = оц["кулак"]
    if к["n"] <= 0:
        out.append("    твоего кулака нет: свободных бойцов 0, оценивать удар нечем")
    for c in оц["клетки"]:
        s = (f"    клетка ({c['x']},{c['y']}): крестьян {c['крестьян']}, его бойцов рядом {c['их_рядом']}")
        if c.get("ушли_мимо"):
            s += (f", НО {c['ушли_мимо']} его бойцов ушли в другую сторону и к "
                  f"твоему приходу не вернутся — они в этот счёт не вошли")
        if c["их_подкрепление"] and c["их_eta"] is not None:
            # «Успеют» и «всего в стороне» — разные числа, и модель должна
            # видеть оба: считается по клеткам, и ближний отряд приходит
            # раньше дальнего.
            s += (f", в стороне ещё {c['их_подкрепление']}, из них к твоему "
                  f"приходу успеют {c['их_успеют']} (ближние за ~{c['их_eta']} с)")
        if к["n"] > 0 and c["наш_eta"] is not None:
            s += f"; твой кулак ({к['что']}) {c['наш_кулак']} дойдёт за ~{c['наш_eta']} с"
        if к["n"] > 0:
            s += (f" — если успевающие двинутся: {c['наш_кулак']} против {c['встретит']}, перевес {c['перевес']}; "
                  f"если нет: против {c['их_рядом']}, перевес {c['перевес_без_подкрепления']} — "
                  f"{c['вердикт'].upper()} (порог {ПОРОГ_ПЕРЕВЕСА})")
        out.append(s)
        # ЕГО СИЛА ПРИХОДИТ НЕ РАЗОМ. Строка отвечает на вопрос, который сумма
        # «встретит» прячет: сколько их будет в миг контакта и как быстро
        # подойдут остальные. Его сто идут к нам, дома копится ещё сто — но
        # первый бой против первой сотни, а не против двухсот.
        if к["n"] > 0 and c.get("отрядов"):
            дт = c.get("дотекание") or []
            стр = (f"      его сила разнесена на {c['отрядов']} отрядов: в миг твоего "
                   f"прихода встретит {c['встретит_сразу']}, перевес {c['перевес_сразу']}")
            if дт:
                стр += (f"; дотечёт ещё +{дт[0]} за полминуты"
                        + (f", +{дт[1]} за минуту" if len(дт) > 1 else ""))
            out.append(стр)
    режим = оц["режим"]
    пояснение = {"ОПАСНОСТЬ": "враг идёт к базе или голод — сначала отпор и еда, никаких походов",
                 "ПЕРЕХВАТ": "его цель рядом с твоей волной — RETREAT или ENGAGE сейчас",
                 "УДАР": "есть клетка с перевесом выше порога даже если успевающие к ней подойдут — бей туда ВСЕМ кулаком",
                 "ШАНС": "есть клетка без охраны, куда ты дойдёшь раньше его армии, но если она двинется — перевеса нет: "
                         "идти только ВСЕМ кулаком сразу и с if_intercepted, пятёрка туда погибнет",
                 "КОПИТЬ": "перевеса нет ни в одной клетке — копи, не дроби армию"}[режим]
    out.append(f"    режим: {режим} — {пояснение}")
    # ЧТО ДАЛО БЫ НАКОПЛЕНИЕ — ЧИСЛОМ, А НЕ УПОМИНАНИЕМ КОМАНДЫ.
    #
    # Замер 20.09 по серии base21, и он объясняет всю историю разом: модель
    # действует по КОНКРЕТНОМУ ПОСЧИТАННОМУ ЧИСЛУ С ЦЕЛЬЮ, а не по наличию
    # команды. `UPGRADE` по имени встречается в 2 процентах тактов и отдан 56
    # раз — потому что рядом стоит «bar.pikeman.2.1: размен станет 0.78, цена
    # 250 еды, выигрыш 0,88 на тысячу». `MOVE` упомянут в 75 процентах тактов
    # («Выбор твой: ... MOVE подводит бойцов») и НЕ ОТДАН НИ РАЗУ за серию.
    # `STAGE` не упоминался в запросе вовсе — 0 тактов из 51 — и тоже ноль.
    # Упомянутая вообще команда всё равно что отсутствующая.
    #
    # Поэтому здесь не совет «накопи заранее», а два числа: на сколько секунд
    # клетка сбора сократит подход и чем за это платишь.
    # НАКОПЛЕНИЕ ДЕРЖИТ БОЙЦОВ, А В МИГ УДАРА ЭТО ПОМЕХА. Живая партия 20.09,
    # такт 14:26: мост объявил режим УДАР (перевес 1,5 при пороге 1,3, кулак
    # 129 против 48 у него дома) — и промолчал о том, что стоячий приказ STAGE
    # держит армию в клетке сбора. Модель написала «коплю кулак в (2,8) по
    # STAGE» и никуда не пошла; окно, которое игрок видел глазами — первая
    # волна врага снесена, — закрылось само. Копить полезно ДО удара, а не
    # ВМЕСТО него, и сказать об этом обязан мост: отмена собственного приказа
    # модели в голову не приходит.
    if НАКОПЛЕНИЕ and режим in ("УДАР", "ШАНС"):
        out.append(
            f"    ВНИМАНИЕ: у тебя стоит НАКОПЛЕНИЕ в ({НАКОПЛЕНИЕ.get('cx')},"
            f"{НАКОПЛЕНИЕ.get('cy')}) — оно держит свежих бойцов в клетке сбора "
            f"и мешает этому удару. Копить было полезно ДО того, как перевес "
            f"появился; сейчас он уже есть. Отмени и бей: "
            f'{{"cmd":"STAGE","off":1}}, и следом ATTACK всем кулаком')
    if not НАКОПЛЕНИЕ and к["n"] > 0 and к.get("cx") is not None:
        цель = next((c for c in оц["клетки"] if c.get("наш_eta")), None)
        if цель and цель["наш_eta"] >= 60:
            # Клетка на полпути: остаток дороги вдвое короче, и это видно без
            # обращения к размеру карты — срок подхода уже посчитан выше.
            _сx = (к["cx"] + цель["x"]) // 2
            _сy = (к["cy"] + цель["y"]) // 2
            _стало = цель["наш_eta"] // 2
            out.append(
                f"    ЕСЛИ КОПИТЬ ЗАРАНЕЕ: клетка сбора ({_сx},{_сy}) на полпути к "
                f"({цель['x']},{цель['y']}) сократит твой подход с {цель['наш_eta']} с до "
                f"~{_стало} с, и кулак будет собран ДО удара, а не в его миг — это "
                f"переводит бой с линейного закона на корень из размена. "
                f"Стоячий приказ: {{\"cmd\":\"STAGE\",\"cx\":{_сx},\"cy\":{_сy},\"keep\":N}}, "
                f"мост сам досылает туда свежих. ПЛАТА: возврат домой те же "
                f"~{_стало} с, а у своей базы размен 0,67 против 0,19 в поле — "
                f"оставь дома keep на прикрытие крестьян")
    return out


def цена_армии(st: dict) -> dict:
    """Во что обошлась армия, по ценам найма из состояния.

    Слагаемое «армейская стоимость» из формулы готовности, которую назвал игрок.
    Считается ПРИБЛИЖЁННО и честно об этом говорит: состояние знает три класса
    (пехота, стрелки, конница), а цена есть у конкретных ролей, поэтому класс
    считается по цене первой роли своего вида из строки найма. Точнее нельзя:
    в mil_inf сложены все пехотинцы, какими бы они ни были.
    """
    цены: dict[str, dict[str, int]] = {}
    for кусок in str(st.get("fighters", "") or "").split():
        роль, _, хвост = кусок.partition("=")
        части = хвост.split(",")
        цены[роль] = {}
        for ч in части[1:]:
            м = re.fullmatch(r"([a-z]+)(-?\d+)", ч)
            if м and м.group(1) in РЕСУРС_РУС:
                цены[роль][м.group(1)] = int(м.group(2))
    класс_роль = (("mil_inf", ("infantry17", "uniq_inf17")),
                  ("mil_shooters", ("musk17",)),
                  ("mil_cav", ("dragoon17",)))
    итог: dict[str, int] = {}
    for поле, роли in класс_роль:
        сколько = _чис(st.get(поле))
        if not сколько:
            continue
        цена = next((цены[р] for р in роли if цены.get(р)), {})
        for рес, за_штуку in цена.items():
            итог[рес] = итог.get(рес, 0) + за_штуку * сколько
    return {к: v for к, v in итог.items() if v}


def отобрать_апгрейды(спис: list[str], st: dict) -> tuple[list[str], int, str]:
    """Какие апгрейды показать модели: (видно, сколько скрыто, чем резали).

    До 15.09 резалось по порядку — первые сорок из двухсот двадцати. В этих
    сорока у Нидерландов оказались `l, cen.1, mil.1, mil.2` и `aca.1…aca.36`,
    то есть ТРИДЦАТЬ ШЕСТЬ апгрейдов академии, которую боту запрещено строить
    (`--ban market,academi`), и НИ ОДНОГО военного: `bar.pikeman.2.1` стоит в
    списке сто первым. Серия `upgrades` 15.09 из-за этого проверила не идею, а
    обрезку: 21 команда из 30, отданных с намерением «взять защиту пикинёра»,
    ушла именем мельницы `mil.1`.

    Отбираем то же, что видит человек: апгрейды ЗДАНИЙ, КОТОРЫЕ У НЕГО СТОЯТ.
    Он открывает казарму и видит там линейки атаки и защиты своей пехоты; он не
    видит апгрейдов академии, пока академии нет. Это сужение, а не фора.
    """
    бойцы = _мои_бойцы(st)
    стоят = {место for место, ключ in МЕСТО_АПГРЕЙДА.items()
             if _чис(st.get(ключ)) > 0}
    # ВЗЯТОЕ И ОПЛАЧИВАЕМОЕ из списка убираем. Человек в казарме видит уже
    # купленную линейку закрытой и второй раз её не покупает, а модель до
    # 16.09 не знала о своих апгрейдах ничего и могла заказывать одно и то же.
    _мимо = взятые_апгрейды(st) | идущие_апгрейды(st)
    спис = [у for у in спис if у not in _мимо]
    военные: list[str] = []
    здания: list[str] = []
    for у in спис:
        части = у.split(".")
        if len(части) == 4 and части[0] in стоят and части[1] in бойцы:
            военные.append(у)
        elif len(части) == 2 and части[0] in стоят:
            здания.append(у)
    # Порядок бойцов — как в списке найма: первым идёт то, кем воюют. Внутри
    # одного бойца имена уже отсортированы игрой: вид, потом уровень.
    военные.sort(key=lambda у: (бойцы.index(у.split(".")[1]), у))
    отобрано = военные + здания
    if not отобрано:
        # Ни одного подходящего — старый мост без `fighters`, либо у нас ещё
        # ничего не построено. Возвращаемся к прежнему поведению, чтобы правка
        # не могла сделать хуже, чем было.
        видно = спис[:СПИСОК_АПГРЕЙДОВ]
        return видно, len(спис) - len(видно), ""
    видно = отобрано[:СПИСОК_АПГРЕЙДОВ]
    чем = ("показаны апгрейды зданий, которые у тебя СТОЯТ, и только для тех "
           "бойцов, кого ты можешь нанять")
    return видно, len(спис) - len(видно), чем

ИСХОД_СЛОВОМ = {"win": "ПОБЕДА", "lose": "ПОРАЖЕНИЕ"}


def _число(v):
    """Строка игры -> int, если это число. Иначе как есть."""
    try:
        return int(str(v).strip())
    except (TypeError, ValueError):
        return v


def конец_партии(a, br, исход: str, gt: int) -> str:
    """Партия кончилась, и мы знаем чем. Сказать вслух и дописать в трассу.

    До 13.09 мост этого не умел вовсе: движок ставит victorystate и тут же
    паузу симуляции, блок состояния замирает вместе с ней, а политика видела
    только «состояние не обновлялось 30 с» и печатала три догадки. Исход при
    этом лежал в двух файлах, которые никто не читал.
    """
    mm, ss = divmod(int(gt), 60)
    слово = ИСХОД_СЛОВОМ.get(исход, исход)
    print(f"\n{'=' * 60}\n{слово} на {mm}:{ss:02d} игрового времени\n{'=' * 60}")
    if исход == "lose":
        print("Базы и населения не осталось: движок засчитывает поражение, когда\n"
              "у игрока нет ни занятых жилых мест, ни ратуши (progress.inc).")
    if a.botlog:
        try:
            with open(a.botlog, "a", encoding="utf-8") as f:
                f.write(json.dumps({
                    "gt": int(gt), "finish": исход,
                    # br.raw — это СТРОКИ, как их пишет игра. В записях тактов
                    # снимок уже приведён к числам, и разнотипица в одной трассе
                    # молча ломает счёт: '0' + '0' даёт '00', а не 0.
                    "state": {k: _число(br.raw.get(k)) for k in (
                        "gametime", "peasants", "mil_inf", "mil_shooters",
                        "food", "wood", "stone", "gold", "iron", "my_farmused")
                        if br.raw.get(k) is not None},
                }, ensure_ascii=False) + "\n")
        except OSError:
            pass                            # трасса не должна ронять партию
    return "победа" if исход == "win" else "поражение"


# ЧАСТЫЙ СНИМОК СОСТОЯНИЯ. Трасса `coss3_bot.jsonl` пишется РАЗ В ТАКТ, а такт
# идёт медианно раз в 21 игровую секунду, в десятой части случаев раз в 46 и
# дольше (максимум 107 — [замер] по 464 тактам base24). Игра же переписывает
# состояние КАЖДУЮ СЕКУНДУ: в отчётах прогонов стоит «медиана 1,2 с, записей
# 1033» против полусотни тактов. То есть двадцать девятнадцатых данных мы
# выбрасывали.
#
# Зачем это нужно. Любой счёт по трассе — простой крестьян, жизнь волны, время
# под порогом еды — считается по трём точкам на минуту и потому грубый; прогноз
# на тех же трёх точках не знает даже длины шага. 22.09 на этом встали оба
# захода: гибель волны не прогнозируется вовсе (поймано 8 эпизодов из 89), а
# провал еды ловится хуже тупого правила.
#
# ОТДЕЛЬНЫМ ФАЙЛОМ, а не строкой в общей трассе, и это главное решение здесь.
# Все инструменты проекта считают ТАКТОМ любую запись с `state`: idle_report,
# series_report, wave_report, сборщики задач стендов. Подмешай снимки в ту же
# трассу — и каждый замер в проекте молча начнёт мерить другое.
ПОЛЯ_СНИМКА = (
    "gametime", "food", "wood", "stone", "gold", "iron", "coal",
    "peasants", "idle_pea", "on_food", "on_wood", "on_stone", "on_gold",
    "on_iron", "on_coal", "on_build", "on_mine", "food_ready",
    "centers", "mills", "smiths", "ba17", "my_stores", "houses",
    "mines_gold", "mines_iron", "mines_coal", "building_now",
    "mil_inf", "mil_shooters", "mil_cav", "mil_away", "mil_near", "mil_far",
    "mil_hurt", "my_freewar", "my_agressors", "my_farm", "my_farmused",
    "wave_sent", "wave_n", "en_at_base", "en_near_dist",
    "p1_army", "p1_inf", "p1_shoot", "p1_cav", "p1_peasants", "p1_ba17",
    "p1_food", "p1_gold", "p1_iron", "p1_bldgs", "p1_mines",
    "my_pea_lost", "my_mil_lost", "p1_pea_lost", "p1_mil_lost",
    # АКАДЕМИЯ И СТРОЙ (27.09, под серию wood_academy). Трасса несёт лишь 16
    # ключей состояния, снимок — этот список; счётчиков академии и строя не было
    # ни там, ни там, и «академия к восьмой минуте» было НЕЧЕМ проверить.
    # Имена — как их пишет блок (`block_hstate.inc:465,470,471,490,491,495,496`).
    "academies", "my_officers", "my_drummers", "squads", "squad_units",
    "squad_dmg", "squad_def", "p1_squads",
)


def тыловая_клетка(st: dict, бой: tuple, клеток: int) -> tuple | None:
    """Клетка за `клеток` от боя в сторону НАШЕЙ базы, на линии между ними.

    Меньше двух клеток от боя не отводим: мушкетёр ближе шести не стреляет, но и
    сажать его на ратушу бессмысленно — тогда он не достаёт вовсе. Если ратуши в
    состоянии нет (её ещё не поставили), тыла не существует: некуда отводить.
    """
    if not бой or клеток <= 0:
        return None
    hx, hy = _чис(st.get("my_cx")), _чис(st.get("my_cy"))
    if not st.get("my_cx") or not st.get("my_cy"):
        return None
    bx, by = int(бой[0]), int(бой[1])
    dx, dy = hx - bx, hy - by
    шаг = max(abs(dx), abs(dy))
    if шаг == 0:
        return None                      # бой в клетке ратуши: тыла нет
    к = min(1.0, клеток / шаг)           # дальше ратуши не уходим
    x = int(round(bx + dx * к))
    y = int(round(by + dy * к))
    x = max(0, min(15, x))
    y = max(0, min(15, y))
    if (x, y) == (bx, by):
        return None
    return (x, y)


def писать_снимок(a, st: dict, когда: dict) -> None:
    """Снимок состояния в свой файл, не чаще раза в `--snap-every` секунд.

    Пишутся ТОЛЬКО числа из белого списка: карты `arow/frow/prow`, цены и
    списки апгрейдов дали бы по паре килобайт на строку, и партия весила бы
    мегабайты. С белым списком строка около 600 знаков, партия на двадцать
    минут при шаге 5 с — примерно 150 килобайт.

    Ошибка записи не должна ронять партию: трасса дороже партии только на
    бумаге.
    """
    каждые = int(getattr(a, "snap_every", 0) or 0)
    путь = getattr(a, "snaplog", "") or ""
    if каждые <= 0 or not путь:
        return
    gt = _чис(st.get("gametime"))
    прошлый = когда.get("gt")
    # Партия могла начаться заново: игровое время упало — пишем сразу.
    if прошлый is not None and 0 <= gt - прошлый < каждые:
        return
    когда["gt"] = gt
    строка = {k: _число(st.get(k)) for k in ПОЛЯ_СНИМКА if st.get(k) is not None}
    # БОЙ В ЧИСЛАХ ПО КЛЕТКЕ. Сами сетки в снимок не кладём — это 768 знаков на
    # строку, — а кладём выжимку: клетки, где наши и его стоят вместе, клетки,
    # где наши бойцы дотянулись до его крестьян, и по скольким клеткам размазана
    # наша армия. Ради этого снимок и заводился: [замер] 22.09 по base24 —
    # глобальный перевес в миг боя 1,27, а в самой клетке 1,00, и в 65 процентах
    # контактов мы в меньшинстве.
    try:
        бой = coss3_map.бой_по_клеткам(st)
    except Exception:
        бой = {}
    if бой.get("клетки"):
        строка["бой"] = [[к["x"], к["y"], к["наших"], к["его"]] for к in бой["клетки"]]
    if бой.get("у_крестьян"):
        строка["у_крестьян"] = [[к["x"], к["y"], к["крестьян"], к["наших"]]
                                for к in бой["у_крестьян"]]
    if бой.get("занято_клеток"):
        строка["занято_клеток"] = бой["занято_клеток"]
    # СЕТКИ, СТРОЙ ВРАГА, ЕГО АПГРЕЙДЫ И ЕГО ЧИСЛА — В СНИМОК (27.09, просьба
    # мака). Всё это давно есть в состоянии и идёт в ТРАССУ, но трасса живёт лишь
    # в тактах, где спрашивали облако: по его счёту это 8-16 процентов тактов.
    # Решение об атаке считается по десятой части партии, а бой идёт КАЖДЫЙ такт,
    # и симулятору нечем было проверять ни закон боя по клеткам, ни цену его
    # строя, ни его апгрейды в миг размена. Форма ТА ЖЕ, что в трассе, чтобы
    # разбор читал оба файла одним кодом: сетки — списком строк, остальное — как
    # пришло из состояния.
    for _сетка in ("frow", "prow", "arow", "brow", "drow"):
        _ряды = [str(st.get(f"{_сетка}{_y}") or "")
                 for _y in range(_чис(st.get("grid_n")) or 16)]
        # Пустую сетку не пишем: до ратуши их нет вовсе (секция гейтится
        # `if (hscen > 0)`), и строка «одни точки» только раздувала бы файл.
        if any(c != "." for _р in _ряды for c in _р):
            строка[_сетка] = _ряды
    # Поля врага берём ПО ОБРАЗЦУ ИМЕНИ, а не списком `p1_...`: индекс врага
    # бывает не первым, и жёсткое `p1_` молча теряло бы всё при другом слоте.
    for _к, _в in st.items():
        if not _к.startswith("p") or "_" not in _к:
            continue
        _хвост = _к.split("_", 1)[1]
        if _хвост in ("upg_done", "fighters", "squads", "squad_units",
                      "squads_form", "squads_form_hold", "squad_form",
                      "squad_form_units", "squad_dmg", "squad_def",
                      "squad_hdmg", "squad_hdef", "squad_hold",
                      "mv_n", "mv_base", "mv_cx", "mv_cy") and _в not in (None, ""):
            строка[_к] = _число(_в)
    # ТЫЛ СТРЕЛКОВ — в снимок тоже (27.09). В трассе он есть, но трасса живёт
    # только в тактах, где спрашивали облако, а мера «стрелки и пикинёры в РАЗНЫХ
    # клетках» считается по сетке 5 с. Это бридж-состояние, а не поле игры,
    # поэтому кладётся отдельно от белого списка.
    if ТЫЛ.get("клетка"):
        строка["тыл"] = [ТЫЛ["клетка"][0], ТЫЛ["клетка"][1]]
    # ТОЧНЫЕ ЧИСЛА КЛЕТОК КОНТАКТА — В СНИМОК (27.09, просьба мака). «Бой» выше
    # посчитан по СЕТКЕ, а знак в ней упирается в 61 даже с двумя алфавитами:
    # решающий бой шёл при 194 наших против 36 его в одной клетке, и обе
    # стороны читались как «+». Поле `cells` блока потолка не имеет вовсе.
    # ПОЧЕМУ ИМЕННО В СНИМОК, а не только в трассу, куда оно легло 26.09: трасса
    # есть лишь в тактах, где спрашивали ОБЛАКО, — у идей без облака в дебюте её
    # там нет ПО ПОСТРОЕНИЮ (ловушка счёта 25.09), а бой идёт каждый такт.
    # Форма ТА ЖЕ, что в трассе (список словарей из `клетки_боя`), чтобы разбор
    # читал оба файла одним кодом. Ключа нет вовсе — мост старый; есть и пуст —
    # клеток контакта не было: различать обязательно.
    if coss3_map.есть_точные_клетки(st):
        try:
            строка["cells"] = coss3_map.клетки_боя(st)
            строка["cells_n"] = _число(st.get("cells_n"))
        except Exception:
            pass
    # РАЗМЕН: голова головы не равна. На десятой минуте его пикинёр бьёт на 18
    # против наших 11 ([замер] base24), и без этого числа клетка «13 против 19»
    # читается как почти ничья, а на деле это 0,62.
    if бой.get("размен"):
        строка["размен"] = бой["размен"]
    try:
        with open(путь, "a", encoding="utf-8") as f:
            f.write(json.dumps(строка, ensure_ascii=False) + "\n")
    except OSError:
        pass


def отметить_конец(a, st: dict, gt: int, исход: str) -> None:
    """Запись `finish` в трассу. Без неё отчёт не знает, чем кончилась партия.

    14.09: цель и горизонт возвращались из цикла простым return, запись делал
    только конец_партии (победа/поражение от игры). В трассе отметки не было, а
    run_report ищет именно её — и пятнадцать партий, среди которых была ВЗЯТАЯ
    ЦЕЛЬ на 12:07, вышли в отчёте как «не кончилась, цель не взята». Ошибка
    измерения, вторая в проекте после счёта крестьян врага от старта.
    """
    if not a.botlog:
        return
    try:
        with open(a.botlog, "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "gt": int(gt), "finish": исход,
                # my_farm, centers и ba17 тут не для красоты: без них разбор
                # видит «занято 127 из 0» и делает ложный вывод про лимит
                # населения — 14.09 критик так и сделал, а запас мест ни разу не
                # падал ниже 69.
                "state": {k: _чис(st.get(k)) for k in (
                    "gametime", "peasants", "mil_inf", "mil_shooters",
                    "food", "wood", "stone", "gold", "iron",
                    "my_farmused", "my_farm", "centers", "ba17", "mills",
                    "mines_iron", "mines_gold")
                    if st.get(k) is not None},
            }, ensure_ascii=False) + "\n")
    except OSError:
        pass                                # трасса не должна ронять партию


def снять_чужую_волну(st: dict | None, волны: list, сказано: list) -> int:
    """Убирает из состояния волну ПРОШЛОЙ партии.

    `wave_sent` мост кладёт в именованный парсер `br_hwave`, а тот живёт в игре
    и переживает КОНЕЦ ПАРТИИ: новая партия начинается с числом старой. 16.09
    по 27 партиям: в 15 (все вторые и третьи эпизоды) модель с пятой секунды
    читала «в походе 8-50 бойцов», которых на карте не было, и держалось это до
    конца партии. Ни одна её жалоба на «волна не доходит» в таких партиях не
    значила ничего.

    Правило 1 проекта: молчаливый отброс неотличим от бездействия — поэтому
    первый раз за партию мост говорит, что именно он снял и почему.

    Возвращает снятое число (0, если снимать было нечего).
    """
    if not st or волны:          # своя волна ушла — поле снова честное
        return 0
    try:
        было = int(float(st.get("wave_sent") or 0))
    except (TypeError, ValueError):
        было = 0
    if было:
        st["wave_sent"] = 0
        if not сказано:
            сказано.append(True)
            print(f"        wave_sent={было} — это волна ПРОШЛОЙ партии "
                  f"(парсер br_hwave переживает конец партии). Снято: в этой "
                  f"партии ATTACK ещё не было.")
    return было


def stalled(d: str, plind: int, no_mode: bool) -> None:
    """Состояние встало. Причин три, и они различимы."""
    path = os.path.join(d, f"coss3_eco_P{plind}.dat")
    try:
        age = time.time() - os.path.getmtime(path)
    except OSError:
        print(f"файл состояния {path} исчез — игра закрыта?")
        return
    print(f"состояние не обновлялось {age:.0f} с (игра пишет его каждые 2–5 с)")
    print("  1. Игра свёрнута или на паузе? Симуляция встаёт вместе с окном —\n"
          "     оставьте окно игры активным, скрипт работает в фоне.")
    print("  2. Партия кончилась (победа или поражение)? При поражении движок\n"
          "     ставит паузу симуляции, и блок замирает вместе с ней.")
    if not no_mode:
        print("  3. Виноват MODE 1? Проверяется одной командой — если с ней\n"
              "     состояние идёт, дело в нём:\n"
              "       python llm_policy.py --no-mode --every 30")
    print("  Посмотреть, что игра пишет на самом деле:\n"
          "    powershell -ExecutionPolicy Bypass -File .\\watch.ps1")


TRANSIENT = ("500", "502", "503", "504", "timed out", "timeout",
            "connection", "overloaded", "too many requests", "429")


def think_worker(box: dict, client, model: str, prompt: str, think: bool,
                 tries: int = 3, spare: str = "", system: str = "",
                 схема: dict | None = None, усилие: str = "",
                 запас: tuple | None = None) -> None:
    """Зовёт модель в фоне. Цикл тем временем живёт своей жизнью.

    500-е и таймаумы у бесплатного тира — обычное дело. Раз вызов не держит
    цикл, повтор бесплатен: пробуем несколько раз с паузой, и такт пропадает
    только если провайдер лежит целиком.
    """
    box["log"] = []
    # Очередь из ПАР (клиент, модель): запасной может жить на ДРУГОМ адресе.
    # Событие на локальной модели иначе оставалось без замены вовсе — ollama
    # на маке 22.09 дважды переставал слушать порт, и повод пропадал молча.
    очередь = [(client, model)] + [(client, м) for м in ([spare] if spare else [])]
    if запас:
        очередь.append(запас)
    попытка = 0
    for _кл, кто in очередь:
        if запас and (_кл, кто) == запас and попытка:
            print(f"        событие уходит в ЗАПАСНУЮ модель {кто}: "
                  f"основная не ответила", flush=True)
        for n in range(tries):
            попытка += 1
            t = time.time()
            try:
                box["data"] = ask(_кл, кто, prompt, think, system=system,
                                  схема=схема, усилие=усилие)
                box["ready"] = time.time()   # когда ОТВЕТ готов, а не когда его забрали
                # Кто обслужил и сколько написал: у OpenRouter один и тот же id
                # уходит к разным провайдерам, и медленный вызов — обычно не
                # «модель думала», а «попали не к тому». Глобальные LAST_* к
                # моменту печати успевает затереть следующий вызов, поэтому
                # снимаем их здесь.
                box["provider"], box["tokens"] = LAST_PROVIDER, LAST_TOKENS
                box["tries"] = попытка
                box["model"] = кто
                return
            except Exception as e:
                msg = str(e).lower()
                box["err"] = e
                box["tries"] = попытка
                врем = any(w in msg for w in TRANSIENT)
                лимит = "429" in msg or "rate-limit" in msg
                box["log"].append(
                    f"{попытка}) {кто.split('/')[-1]}, {time.time() - t:.0f} с, "
                    f"{'лимит' if лимит else 'временная' if врем else 'НЕ временная'}: "
                    f"{str(e)[:160]}")
                if not врем:
                    # НЕ временная беда — повтор и замена обычно не спасут. Но
                    # если очередь не кончилась, ЗАПАСНОЙ ЖИВЁТ НА ДРУГОМ
                    # АДРЕСЕ, и вся беда может быть именно в том адресе:
                    # «connection refused» от упавшей ollama во временные не
                    # попадает, и до 23.09 повод на этом пропадал молча.
                    if запас and (_кл, кто) != запас:
                        break               # к запасной — она в другом месте
                    return
                if n + 1 >= tries:
                    break                   # эта модель не отвечает — пробуем запасную
                # Лимит провайдера полутора секундами не пересидеть: он общий
                # на всех и держится десятками секунд. Вызов в фоне, ждать дёшево.
                time.sleep((6.0 if лимит else 1.5) * (n + 1))


class Tee:
    """Пишем и в консоль, и в файл — overlay.ps1 показывает хвост этого файла.

    Строка уходит в файл сразу (buffering=1): окно поверх игры должно видеть
    решение в тот же миг, что и консоль, иначе смысла в нём нет.
    """

    def __init__(self, поток, path: str):
        self.поток = поток
        # Прежний лог не затираем, а отодвигаем в сторону. 11.09.2026 один
        # `--check` во время боя стёр лог партии целиком: файл открывался на
        # "w", а лог — единственная запись того, что делала модель.
        try:
            if os.path.getsize(path) > 0:
                метка = time.strftime("%m-%d_%H%M", time.localtime(os.path.getmtime(path)))
                корень, хвост = os.path.splitext(path)
                os.replace(path, f"{корень}.{метка}{хвост}")
        except OSError:
            pass                            # нет файла или не переименовать — не беда
        self.файл = open(path, "w", encoding="utf-8", buffering=1)

    def write(self, s: str) -> int:
        self.поток.write(s)
        try:
            self.файл.write(s)
        except Exception:
            pass                            # лог не должен ронять партию
        return len(s)

    def flush(self) -> None:
        self.поток.flush()
        try:
            self.файл.flush()
        except Exception:
            pass

    def isatty(self) -> bool:
        return False


def раскодировать(сырое: bytes) -> str:
    """Байты подсказок -> текст, какой бы редактор их ни сохранил.

    Файл правят и на маке, и на Windows: PowerShell при `>` пишет UTF-16LE,
    старые редакторы — CP1251, «Блокнот» умеет добавить BOM. Несовпадение
    кодировки не должно ронять партию, поэтому перебираем по очереди, а в
    самом конце декодируем с заменой — пусть лучше кракозябры, чем падение.
    """
    for bom, кодировка in ((b"\xef\xbb\xbf", "utf-8-sig"),
                           (b"\xff\xfe", "utf-16"),
                           (b"\xfe\xff", "utf-16")):
        if сырое.startswith(bom):
            try:
                return сырое.decode(кодировка).strip()
            except UnicodeDecodeError:
                break
    for кодировка in ("utf-8", "cp1251"):
        try:
            return сырое.decode(кодировка).strip()
        except UnicodeDecodeError:
            continue
    return сырое.decode("utf-8", "replace").strip()


_ПОДСКАЗКИ = {"текст": "", "когда": 0.0, "откуда": ""}


# Строки, дописанные ключом --hint-add. Живут глобально, потому что подсказки
# перечитываются из файла на каждом такте, а дописка должна переживать это.
ДОПИСКИ: list[str] = []


def _подсказки_из_файла(path: str, max_age: float = 10.0) -> str:
    """Подсказки из файла или по ссылке.

    Ссылка нужна, чтобы править их с другой машины: игра идёт на Windows, а
    редактировать удобнее с макбука. Сеть тут на горячем пути — промпт
    собирается в главном цикле, — поэтому таймаут короткий, ответ кешируется
    на max_age секунд, а при любой беде берётся последний удачный текст.
    Партия важнее свежести подсказок.
    """
    if path.startswith(("http://", "https://")):
        now = time.time()
        if _ПОДСКАЗКИ["откуда"] == path and now - _ПОДСКАЗКИ["когда"] < max_age:
            return _ПОДСКАЗКИ["текст"]
        try:
            import urllib.request
            with urllib.request.urlopen(path, timeout=3) as r:
                текст = раскодировать(r.read())
            _ПОДСКАЗКИ.update(текст=текст, когда=now, откуда=path)
            return текст
        except Exception:
            _ПОДСКАЗКИ["когда"] = now      # не долбить сеть каждый такт
            return _ПОДСКАЗКИ["текст"]
    try:
        сырое = open(path, "rb").read()
    except OSError:
        return ""
    return раскодировать(сырое)



def load_hints(path: str, max_age: float = 10.0) -> str:
    """Подсказки из файла плюс дописки ключа --hint-add.

    Дописка — это способ проверить идею КАК ЗНАНИЕ: модель узнаёт о
    возможности и решает сама, вместо того чтобы мост подменял её команду.
    13.09 игрок указал, что подмена нечестна — модель отдала BUILDERS 3,
    увидела мир, где ратуша встала втрое быстрее, и рассуждала дальше о том,
    чего не делала.
    """
    текст = _подсказки_из_файла(path, max_age)
    if ДОПИСКИ:
        текст = текст.rstrip("\n") + "\n" + "\n".join(ДОПИСКИ) + "\n"
    return текст

def _мастер_мира() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "world.md")


def _прочесть(path: str) -> str:
    try:
        return раскодировать(open(path, "rb").read())
    except OSError:
        return ""


def load_world(path: str) -> str:
    """Файл мира -> готовый раздел промпта. Нет файла — пустая строка.

    Читается ДВА файла и склеивается: мастер рядом со скриптом (он приезжает из
    git и держит знания) и рабочий в /io (в нём копятся вопросы этой серии).
    Иначе получается то, что вышло 13.09 дважды подряд: рабочий файл от прошлого
    прогона уже лежал в томе, посев не делался — и знания из git не доезжали
    вовсе, а в логе стояло безобидное «0 строк знания».

    Читается перед каждым решением, как и подсказки: отвечать на вопрос модели
    удобно, не останавливая партию. Только локальные файлы, без ссылок.
    """
    if not path:
        return ""
    текст = _прочесть(path)
    мастер = _мастер_мира()
    if os.path.abspath(мастер) != os.path.abspath(path):
        текст = _прочесть(мастер) + "\n" + текст
    return мир_для_промпта(текст)


def подготовить_мир(path: str) -> None:
    """Посев файла мира из мастера рядом со скриптом.

    В контейнере клон моста одноразовый: что модель туда запишет, сгинет вместе
    с контейнером. Поэтому играть надо на файле в /io — он уезжает в результаты
    вместе с трассой. Но начальное знание лежит в git, рядом со скриптом, и
    копировать его руками в entrypoint нельзя: скрипты контейнера запечены в
    образ и из git не обновляются. Значит сеем отсюда.
    """
    if not path or os.path.exists(path):
        return
    мастер = os.path.join(os.path.dirname(os.path.abspath(__file__)), "world.md")
    if os.path.abspath(мастер) == os.path.abspath(path):
        return
    if not os.path.exists(мастер):
        # 13.09 это стоило целой серии: в контейнер копировались только
        # *.py/*.inc/*.txt, world.md не доезжал, посев молча не делался, и все
        # четыре копии играли с ПУСТЫМ описанием мира. В логе не было ни слова.
        print(f"МАСТЕР МИРА НЕ НАЙДЕН: {мастер}. Модель начнёт с пустого "
              f"описания мира — знания в промпт не пойдут, только канал вопросов")
        return
    try:
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        with open(мастер, "rb") as и, open(path, "wb") as к:
            к.write(и.read())
        print(f"мир посеян: {мастер} -> {path}")
    except OSError as e:
        print(f"мир не посеян ({e}) — модель начнёт с пустого")


def find_ai_plind(d: str, fresh: float = 30, human: bool = False) -> int | None:
    """Чей слот вести. На компьютерном ищем bai, на человеческом — human:
    правила хакатона требуют играть за человека, а там флага bai нет вовсе."""
    best, best_mtime = None, -1.0
    try:
        names = os.listdir(d)
    except OSError:                          # каталога нет — разбираться будет diagnose
        return None
    for name in names:
        m = re.fullmatch(r"coss3_eco_P(\d+)\.dat", name)
        if not m:
            continue
        n = int(m.group(1))
        mtime = os.path.getmtime(os.path.join(d, name))
        if fresh and time.time() - mtime > fresh:
            continue
        try:
            st = Bridge(d, n).read_state() or {}
        except Exception:
            continue
        свой = st.get("human") if human else st.get("bai")
        if свой and mtime > best_mtime:
            best, best_mtime = n, mtime
    return best


# Роль в заказе -> счётчик в состоянии, по которому видно исполнение.
# Роль в заказе -> ключ в состоянии. Имена НЕ совпадают: роль minegold, ключ
# mines_gold; роль market, ключ markets. Проверял по списку ключей из
# block_state.inc, а не по догадке — на этом уже ошибался.
СЧЁТЧИК = {
    "center": "centers", "mill": "mills", "smith": "smiths",
    "ba17": "ba17", "ba18": "ba18", "store": "my_stores", "house": "houses",
    "tower": "my_towers", "market": "markets", "stable": "stables",
    "academi": "academies",
    "minegold": "mines_gold", "mineiron": "mines_iron", "minecoal": "mines_coal",
    "peasant": "peasants", "infantry17": "mil_inf", "musk17": "mil_shooters",
    "dragoon17": "mil_cav",
}


# Что чем требуется (lib/country.script, около 2926) и по какому ключу
# состояния это проверить. Игра при невыполненном требовании молчит — грабля
# №4, — поэтому называем требование сами.
ТРЕБУЕТ = {
    "smith":      [("centers", "ратуши")],
    "store":      [("centers", "ратуши")],
    "house":      [("centers", "ратуши")],
    "peasant":    [("centers", "ратуши")],
    "ba17":       [("smiths", "кузницы")],
    "ba18":       [("smiths", "кузницы")],
    "stable":     [("smiths", "кузницы")],
    "academi":    [("ba17", "казармы")],
    "tower":      [("my_stores", "склада")],
    "market":     [("mills", "мельницы"), ("my_stores", "склада")],
    "infantry17": [("ba17", "казармы")],
    "musk17":     [("ba17", "казармы")],
    "dragoon17":  [("stables", "конюшни")],
}


РЕСУРС_РУС = {"food": "еды", "wood": "дерева", "stone": "камня",
               "gold": "золота", "iron": "железа", "coal": "угля"}


def не_по_карману(role: str, st: dict) -> list[str]:
    """Каких ресурсов не хватает на ОДНОГО бойца — по цене из поля fighters.

    14.09 модель шесть раз за серию записала «дело не в еде» и не нашла причину:
    у бесконечного заказа мост отвечал «смотри, какой ресурс на нуле», а сам
    цену знал — она приходит в состоянии вместе со списком бойцов. Сравнить
    цену с запасом мы можем и в python, не трогая блок.

    Честно: цену и запас человек видит на экране, в казарме и в панели ресурсов.
    """
    for кусок in str(st.get("fighters") or "").split():
        имя, _, хвост = кусок.partition("=")
        if имя != role:
            continue
        мало = []
        for поле in хвост.split(",")[1:]:
            м = re.fullmatch(r"([a-z]+)(\d+)", поле)
            # ТОЛЬКО настоящие ресурсы. Раньше здесь пропускался один `hp`, а
            # всё остальное считалось ценой — и 16.09 это обернулось ложью:
            # в строку найма добавили боевые свойства, и мост стал печатать
            # «НЕ ХВАТАЕТ РЕСУРСОВ: atk 0 при цене 8, dpike 0 при цене 6».
            # Такого ресурса нет, запас его всегда ноль, значит заказ выглядел
            # невыполнимым ВСЕГДА. Модель поверила и пошла покупать апгрейды:
            # 13 тактов в 5 партиях из 15 (серия base9). Белый список вместо
            # чёрного — тогда новое поле в строке найма ломает не молча.
            if not м or м.group(1) not in РЕСУРС_РУС:
                continue
            рес, цена = м.group(1), int(м.group(2))
            if цена <= 0:
                continue
            try:
                есть = int(float(st.get(рес, 0) or 0))
            except (TypeError, ValueError):
                continue
            if есть < цена:
                мало.append(f"{РЕСУРС_РУС.get(рес, рес)} {есть} при цене {цена}")
        return мало
    return []


def чего_не_хватает(role: str, st: dict) -> list[str]:
    """Невыполненные требования для этой роли, человеческими словами."""
    нет = []
    for ключ, имя in ТРЕБУЕТ.get(role, []):
        try:
            если = int(float(st.get(ключ, 0) or 0))
        except (TypeError, ValueError):
            если = 0
        if если < 1:
            нет.append(имя)
    return нет


КОМАНДЫ_СЛОВА = ("BALANCE", "TRAIN", "BUILD", "ATTACK", "UPGRADE")


# Слово BALANCE в логе 11.09 встретилось в тексте всего дважды, а намерение
# перераспределить крестьян — почти в каждом такте. Ловим и его: «написал про
# перераспределение, команды нет» — то же самое расхождение.
НАМЕРЕНИЕ = {
    "BALANCE": re.compile(r"перераспредел|долю\s+крестьян|"
                          r"(перекин|перебро|переставь|переставить)\w*\s+крестьян|"
                          r"крестьян\w*\s+на\s+камень", re.I),
}


def названо_но_не_отдано(текст: str, отдано: set[str]) -> list[str]:
    """Команды, названные ЛАТИНИЦЕЙ в объяснениях модели, но не отданные.

    Ровно так пропала добыча камня в прогоне 11.09.2026: в cause такт за тактом
    стояло «перераспределить крестьян на камень через BALANCE», а команды
    BALANCE не было ни одной за эпизод. Модель ничего об этом не узнавала:
    в «Итоге прошлого решения» отражаются только ОТДАННЫЕ команды.
    Считаем по отправленным в игру, а не по JSON: команда с негодной ролью
    отбрасывается в to_commands молча, и это тоже надо показать.
    """
    if not текст:
        return []
    названо = {с for с in КОМАНДЫ_СЛОВА
               if re.search(rf"\b{с}\b", текст)}
    названо |= {с for с, рег in НАМЕРЕНИЕ.items() if рег.search(текст)}
    return sorted(названо - set(отдано))


# Что модель может приписать себе в уроке, не отдав команды. Проверяем только
# такие притязания: урок вида «заказал шахту при камне=20 — не началось» честен
# и должен проходить, если BUILD в том же ответе был.
ПРИТЯЗАНИЯ = (
    # «распредел» без приставки нарочно не берём: «при текущем распределении»
    # — это описание обстановки, а не притязание на сделанное.
    # Только СОВЕРШЁННЫЕ формы. «нужно перераспределить крестьян» — это план,
    # он честен и в журнал попасть должен; «Переставил крестьян 50/50» при нуле
    # команд BALANCE — притязание на несделанное. Разбор лога 11.09 поймал эту
    # разницу на уроке 2:07, который первая редакция фильтра забраковала зря.
    ("BALANCE", re.compile(r"переведен|переведён|перевёл|перевел|переставил|"
                           r"перераспределил|перераспределен|перераспределён|"
                           r"перекинул|перебросил|поставил\s+\d+\s*%", re.I)),
    ("TRAIN", re.compile(r"наня[лв]|нанимал", re.I)),
    ("BUILD", re.compile(r"постро(ил|или)\b|заложил", re.I)),
    ("ATTACK", re.compile(r"отправил\s+волн|послал\s+в\s+атаку", re.I)),
)


def притязание_без_команды(урок: str, отдано: set[str]) -> tuple[str, str] | None:
    """Урок заявляет действие, команды на которое в этом ответе не было.

    11.09.2026 модель дважды записала в lessons.txt «Переведено 60% на камень
    вместо 0%» и «Переставил крестьян 50/50», не отдав ни одной BALANCE.
    Такой урок — не материал для проверки гипотез, а ложь в журнале, и дальше
    она читается как факт.
    """
    if not урок:
        return None
    for имя, рег in ПРИТЯЗАНИЯ:
        if имя in отдано:
            continue
        м = рег.search(урок)
        if м:
            return м.group(0), имя
    return None


def _раздел(запрос: str, заголовок: str) -> list:
    """Строки одного раздела запроса. Нужен трассе: в ней должен лежать тот же
    итог прошлого хода, который видела модель, иначе по записи не понять, на
    что она отвечала."""
    если = []
    внутри = False
    for л in (запрос or "").split("\n"):
        if л.strip() == заголовок:
            внутри = True
            continue
        if внутри:
            if л.startswith("## "):
                break
            if л.strip():
                если.append(л.strip())
    return если

def разобрать_wip(st: dict) -> dict:
    """`wip` из блока состояния: что в закладке, сколько строителей влезает,
    сколько их там СЕЙЧАС и насколько готово.

    Формат с 15.09 — `center/12/5/40`: роль, предел по геометрии, реально
    строят, процент готовности. Старый мост отдавал две части (`center/12`), и
    они по-прежнему понимаются: недостающее становится None, а не нулём, —
    ноль значил бы «никто не строит», а это разные вещи.

    Роль -> (предел, строителей, процент).
    """
    из = {}
    for кусок in str(st.get("wip", "") or "").split(","):
        кусок = кусок.strip()
        if not кусок:
            continue
        части = кусок.split("/")
        имя = части[0]
        def ч(i):
            try:
                return int(части[i])
            except (IndexError, ValueError):
                return None
        из[имя] = (ч(1) or 0, ч(2), ч(3))
    return из

def цена_апгрейда(role: str, st: dict) -> str:
    """Цена апгрейда словами. Пусто, если её нет: выдумывать нельзя.

    Берём ТЕМ ЖЕ разбором, что и весь мост, — `combat_math.цены_апгрейдов`
    по полю `upg_avail`. 22.09 здесь был мой дефект ровно той породы, о
    которой предупреждает скилл разбора: первая версия читала `upg_shown` и
    разбирала строку своим кодом. Поля `upg_shown` в ЖИВОМ состоянии нет
    вовсе — его создаёт запись снимка в трассу, обрезая полный список. На
    base26 из-за этого цена не была названа НИ РАЗУ при 22 заказах апгрейдов,
    хотя самопроверка на синтетическом состоянии проходила: в ней поле было.
    `upg_shown` оставлен запасным — по нему считают готовые трассы."""
    цены = (combat_math.цены_апгрейдов((st or {}).get("upg_avail"))
            or combat_math.цены_апгрейдов((st or {}).get("upg_shown")))
    ц = цены.get(role) or {}
    слова = {"food": "еда", "gold": "золото", "iron": "железо",
             "wood": "дерево", "stone": "камень", "coal": "уголь"}
    return ", ".join(f"{слова.get(к, к)} {в}" for к, в in ц.items() if в)


def итог_прошлого(было: dict, стало: dict, заказ: list,
                  повторы: dict | None = None) -> list[str]:
    """Что вышло из прошлого решения. Без этого модель не знает, приняла ли
    игра её заказ, и переспрашивает одно и то же такт за тактом."""
    if not заказ:
        return []
    строки = ["", "## Итог прошлого решения"]
    # ПОПРАВКА К ПРОШЛОМУ ВЕРДИКТУ «НИКТО НЕ ПОШЁЛ». Он выносится при
    # следующем запросе, а блок дописывает wave_sent позже: по шести партиям
    # 22.09 из 26 таких вердиктов в 7 wave_sent сменился на запрошенное число
    # уже к моменту ответа модели — волна ушла, а модель записала урок
    # «свободных не было» (в коде с 19.09 то же наблюдение: 90 процентов
    # ложных при набегах). Ждём волну ещё такт и, если она объявилась,
    # говорим об этом первым делом и снимаем счётчик повторов.
    если_повторы = {} if повторы is None else повторы
    _ждём = если_повторы.get(("ATTACK", "ждём"))
    if _ждём:
        _n, _ws0 = _ждём
        _ws = int(стало.get("wave_sent", 0) or 0)
        if _ws and _ws != _ws0:
            строки.append(f"  ПОПРАВКА: прошлый ATTACK {_n} всё же УШЁЛ — блок "
                          f"взял {_ws}, вердикт «никто не пошёл» был поспешным. "
                          f"Урок «свободных не было» из него делать нельзя.")
            если_повторы.pop(("ATTACK", ""), None)
        если_повторы.pop(("ATTACK", "ждём"), None)
    занято = int(стало.get("build_slots_used", 0) or 0)
    строится_сейчас = разобрать_wip(стало)

    def впустую(ключ: tuple, строка: str) -> str:
        """Счётчик подряд идущих безрезультатных заказов одного и того же.
        В прогоне 11.09 одна и та же BUILD mineiron ушла восемь тактов подряд
        и ни разу не началась — по одиночной строке отказа это не видно."""
        n = если_повторы.get(ключ, 0) + 1
        если_повторы[ключ] = n
        if n >= 2:
            строка += (f" ЭТО {n}-Й РАЗ ПОДРЯД с тем же исходом — заказ не"
                       f" проходит, перестань его повторять и убери причину.")
        return строка
    КРЕСТЬЯНЕ = {"food": "on_food", "wood": "on_wood", "stone": "on_stone"}
    for c, role, total in заказ:
        if c == "UPGRADE":
            # Единственная команда, о которой мост молчал совсем. 15.09 серия
            # `upgrades` отдала 38 заказов за пятнадцать партий и не получила
            # ни одной строки итога: молчание неотличимо от бездействия
            # (правило 1), и модель заказывала одно и то же по шесть раз за
            # партию, каждый раз объясняя в 'why', зачем берёт защиту.
            #
            # Отказ игра называет сама: блок кладёт причину в `last_fail`
            # ('UPGRADE mil.1: not enough resources'). Успех не виден ничем —
            # движок пишет 'started' только в свой лог, а поля о ВЗЯТЫХ
            # апгрейдах в состоянии нет. Поэтому про успех говорим ровно то,
            # что знаем, и не выдаём «принят» за «готов».
            # Блок пишет причину всегда в одной форме: 'UPGRADE <имя>: <текст>';
            # отказов в такте может быть несколько — ищем СВОЙ среди всех.
            сбой = next((о for о in отказы(стало)
                         if bool(role) and о.upper().startswith(f"UPGRADE {role}:".upper())), "")
            свой = bool(сбой)
            if свой:
                причина = сбой.split(":", 1)[1].strip() if ":" in сбой else сбой
                строки.append(впустую(
                    ("UPGRADE", role),
                    f"  UPGRADE {role}: НЕ ПРОШЁЛ — {причина}"))
            else:
                # НЕ говорим «принят»: состояние отстаёт на такт, и отказ может
                # прийти следующим. Проверено на моке 15.09 — первый заказ
                # прошёл, второй игра отвергла, а в том же такте `last_fail`
                # был ещё пуст. Сказать «принят» значило бы соврать ровно там,
                # где модель ждёт правды. Сам отказ, когда он дойдёт, модель
                # увидит строкой «ПОСЛЕДНИЙ ОТКАЗ» в обстановке.
                # ЦЕНУ НАЗЫВАЕМ. 22.09 по шести партиям: все девять падений еды
                # на 2000-4300 за такт шли сразу после UPGRADE bar.pikeman.X.3
                # (4200 еды по upg_shown), а мост говорил «проверить нечем» —
                # и модель шесть раз записала урок «прокорм деревни съедает
                # больше, чем даёт поле», сажая людей на еду вместо того, чтобы
                # понять, что заплатила сама. Цена лежит в состоянии — так и
                # говорим, где её искать в падении запаса.
                _ц = цена_апгрейда(role, стало) or цена_апгрейда(role, было)
                _цс = (" Его цена по состоянию: " + _ц + " — если запас упал "
                       "примерно на столько, это плата за него, а не прокорм."
                       if _ц else "")
                строки.append(
                    f"  UPGRADE {role}: отказа пока нет, но он может прийти "
                    f"следующим тактом. Взят ли апгрейд, мост НЕ ВИДИТ: поля о "
                    f"взятых апгрейдах в состоянии нет.{_цс} Вслепую то же "
                    f"самое не повторяй — сначала дождись такта")
            continue
        if c == "BALANCE":
            key = КРЕСТЬЯНЕ.get(role)
            if key is None:                 # шахтные ресурсы в состоянии не видны
                строки.append(f"  BALANCE {role} {total}: отправлено, "
                              f"проверить нечем")
                continue
            b, st_ = int(было.get(key, 0) or 0), int(стало.get(key, 0) or 0)
            если = "не изменилось" if b == st_ else f"{b}->{st_}"
            if role == "food" and not int(стало.get("mills", 0) or 0):
                # Без мельницы движок никого на еду не шлёт (см. комментарий к
                # SYSTEM). Партия 11.09.2026 умерла от голода именно так:
                # BALANCE food 16 уходил девятнадцать раз и не делал ничего.
                строки.append(f"  BALANCE food {total}: НЕ СРАБОТАЛО И НЕ "
                              f"СРАБОТАЕТ — У ТЕБЯ НЕТ МЕЛЬНИЦЫ. Крестьяне идут "
                              f"на еду только вокруг неё. Сначала BUILD mill")
                continue
            # ПУСТАЯ КОМАНДА: ПРОСИЛИ НЕ БОЛЬШЕ, ЧЕМ УЖЕ СТОИТ (24.09).
            # BALANCE задаёт ИТОГ, а не прибавку, и просьба о числе ниже
            # текущего не двигает никого: занятые сами не уходят, а свободным
            # команда не адресована. Счёт по трём сериям (base27, base28,
            # debut4), 760 команд BALANCE в тактах со СВОБОДНЫМИ крестьянами:
            # людей прибавилось в 46 процентах, а в 38 просили НЕ БОЛЬШЕ, чем
            # уже стоит - то есть каждая третья команда была пустой. Мост
            # молчал об этом, и модель повторяла её тактами: «на дерево 6»
            # при восьми работающих. Это не отказ игры и не нехватка мест -
            # это непонимание слова «итог», и сказать о нём стоит прямо.
            if total <= b and (st_ <= b):
                строки.append(
                    f"  BALANCE {role} {total}: НИЧЕГО НЕ СДЕЛАНО — на {role} "
                    f"уже {b}, а ты просишь {total}. BALANCE задаёт ИТОГОВОЕ "
                    f"число, а не прибавку: чтобы добавить людей, проси "
                    f"БОЛЬШЕ текущего (например {b + 1} и выше). Снять "
                    f"занятых этой командой нельзя — уходят только свободные")
                continue
            # ИГРА МОГЛА ОТКАЗАТЬ. 23.09, дебют base27: на 90 с модель послала
            # шестнадцать человек на еду, игра ответила «GATHER res0: no
            # deposit of this kind within 40» (поля не засеяны), а мост сказал
            # «отправлено, проверить нечем» — и следующие четыре такта на еде
            # стоял ноль при двенадцати свободных. Отказ игры важнее нашего
            # счёта: он объясняет, ПОЧЕМУ число не изменилось.
            _отк = [о for о in отказы(стало) if "GATHER" in о.upper()]
            if b == st_ and _отк:
                строки.append(f"  BALANCE {role} {total}: НЕ СРАБОТАЛО, игра "
                              f"отказала — {_отк[0][:120]}")
                continue
            строки.append(f"  BALANCE {role} {total}: крестьян на {role} {если}"
                          + ("" if b != st_ else
                             " — перестановка идёт через СВОБОДНЫХ крестьян,"
                             " занятые сразу не уходят"))
            continue
        if c == "ATTACK":
            аг_б = int(было.get("my_agressors", 0) or 0)
            аг_с = int(стало.get("my_agressors", 0) or 0)
            св_б = int(было.get("my_freewar", 0) or 0)
            св_с = int(стало.get("my_freewar", 0) or 0)
            # Судим по СУММЕ «свободные + пул»: волна набирается сначала из
            # свободных, а если их мало — из пула, и тогда свободные не меняются
            # вовсе. Прежняя проверка по одним свободным объявляла ушедшую волну
            # неудачей, модель верила и семь раз подряд «снижала запрос» — так был
            # потерян почти весь эпизод 3 от 11.09.2026.
            #
            # 19.09: и этого мало. По 53 партиям 31 приказ при свободных не меньше
            # запрошенного получил «НИКТО НЕ ПОШЁЛ», хотя блок волну ВЗЯЛ: в 90
            # процентах таких тактов wave_sent сменился на запрошенное число. Это
            # набеги на базу (враг у базы в 71 процента случаев, ранены в 77):
            # ушедших тут же замещают вернувшиеся из стычки и новые из казармы,
            # и свободных не убывает. Блок пишет wave_sent = сколько взял, и это
            # надёжнее счёта свободных. Модель на ложном «никто не пошёл» дважды
            # записала урок «свободных не было» при 50 свободных.
            ws_б = int(было.get("wave_sent", 0) or 0)
            ws_с = int(стало.get("wave_sent", 0) or 0)
            взял = ws_с if (ws_с and ws_с != ws_б) else 0
            if взял:
                если_повторы.pop(("ATTACK", ""), None)
                строки.append(f"  ATTACK {total}: ВОЛНА УШЛА — блок взял {взял}"
                              + (f" (просил {total})" if взял != total else "")
                              + f"; бойцов у базы {св_б + аг_б}->{св_с + аг_с}"
                              + (" — не убыло, потому что ушедших заместили вернувшиеся "
                                 "из стычки и новые из казармы" if св_с + аг_с >= св_б + аг_б else ""))
            elif (св_с + аг_с) < (св_б + аг_б):
                если_повторы.pop(("ATTACK", ""), None)
                строки.append(f"  ATTACK {total}: ВОЛНА УШЛА — бойцов у базы "
                              f"{св_б + аг_б}->{св_с + аг_с} "
                              f"(свободных {св_б}->{св_с}, пул {аг_б}->{аг_с})")
            else:
                # Причина на слотах РАЗНАЯ, и назвать чужую — соврать.
                причина = ("Запрошено {n}; волна набирается из бойцов без "
                           "приказа, и если не пошёл никто — брать было "
                           "некого: проверь строку «можно послать сейчас»."
                           ).format(n=total) if ЧЕЛОВЕК else (
                          "Запрошено {n}; приказ отвергается ЦЕЛИКОМ, если "
                          "бойцов меньше запрошенного.").format(n=total)
                строки.append(впустую(
                    ("ATTACK", ""),
                    f"  ATTACK {total}: НИКТО НЕ ПОШЁЛ — бойцов у базы как было "
                    f"{св_б + аг_б}, так и осталось {св_с + аг_с} "
                    f"(свободных {св_с}, пул {аг_с}). " + причина
                    + " Вердикт НЕ окончательный: блок мог ещё не дописать "
                      "wave_sent — следующим тактом мост поправит, если волна "
                      "объявится."))
                если_повторы[("ATTACK", "ждём")] = (total, ws_с)
            continue
        key = СЧЁТЧИК.get(role)
        if key is None:
            строки.append(f"  {c} {role} {total}: проверить нечем")
            continue
        b, st = int(было.get(key, 0) or 0), int(стало.get(key, 0) or 0)
        if total < 0:                       # бесконечный заказ: смотрим только рост
            _т = f"  {c} {role} без счёта: {key} {b}->{st}"
            if st > b:
                если_повторы.pop((c, role), None)
                строки.append(_т)
            else:
                # С числами, а не «смотри ресурсы»: 11.09.2026 найм крестьян встал
                # при 2114 еды, и по одной этой фразе причину было не найти —
                # ни в логе, ни модели. Цены юнитов лежат в бинарнике игры, так
                # что единственный способ увидеть узкое место — снимок на миг
                # отказа, как это уже сделано для BUILD.
                рес = " ".join(f"{имя}={стало.get(ключ, '?')}" for имя, ключ in
                               (("еда", "food"), ("дерево", "wood"),
                                ("камень", "stone"), ("золото", "gold"),
                                ("железо", "iron"), ("уголь", "coal")))
                места = ""
                _з = _запас_мест(стало)
                if _з is not None:
                    места = (f", жилых мест {стало.get('my_farmused')}/"
                             f"{стало.get('my_farm')}")
                # Требования проверяем ПЕРВЫМИ. 14.09: в трёх партиях казармы не
                # было вовсе (золота 355 при цене 500), модель заказывала
                # мушкетёров и шесть раз писала «дело не в еде» — а мост в той же
                # строке состояния держал ba17 в cant_now. Ветка требований
                # существовала, но у бесконечного заказа своя дорога, и до неё
                # не доходило.
                нет = чего_не_хватает(role, стало)
                if нет:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ РАСТЁТ, и причина известна: НЕТ "
                             f"{' и '.join(нет).upper()}. Пока этого нет, заказ "
                             f"не сделает НИЧЕГО, сколько ни повторяй."))
                    continue
                # Цена бойца приходит в состоянии (поле fighters) — значит
                # сравнить её с запасом можно здесь, а не гадать «какой ресурс
                # ближе к нулю». can_pea/can_inf ниже — поля КОМПЬЮТЕРНОГО слота,
                # человеческий блок их не пишет, и та ветка не срабатывала ни разу.
                мало = не_по_карману(role, стало)
                if мало:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ ХВАТАЕТ РЕСУРСОВ на одного: "
                             f"{', '.join(мало)}. Заказ не пройдёт, пока этого нет."))
                    continue
                _можно = стало.get("can_pea" if role == "peasant" else "can_inf")
                if str(_можно).lower() in ("0", "false", "нет"):
                    строки.append(
                        _т + f" — ДВИЖОК ГОВОРИТ: РЕСУРСОВ НА ОДНОГО НЕ ХВАТАЕТ. "
                             f"Заказ даже не принят. Было: {рес}{места}. Цены "
                             f"юнитов в данных игры не лежат — смотри, какой "
                             f"ресурс ближе всех к нулю.")
                    continue
                вработе = стало.get("inprod_pea" if role == "peasant" else "inprod_inf")
                if вработе:
                    если_повторы.pop((c, role), None)
                    строки.append(_т + f" — но {вработе} уже В ПРОИЗВОДСТВЕ: "
                                       f"заказ принят, юнит просто ещё не вышел. "
                                       f"Не повторяй и не ищи причину.")
                else:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ РАСТЁТ, и в производстве НИКОГО. Было в этот "
                             f"миг: {рес}{места}. Смотри, какой ресурс на нуле."))
            continue
        if st >= total:
            если_повторы.pop((c, role), None)
            строки.append(f"  {c} {role} {total}: ГОТОВО ({key}={st})")
        elif st > b:
            если_повторы.pop((c, role), None)
            строки.append(f"  {c} {role} {total}: идёт ({key} {b}->{st})")
        elif c == "BUILD" and (role in строится_сейчас or занято > 0):
            # Ветка раньше смотрела только на build_slots_used — поле
            # КОМПЬЮТЕРНОГО слота, которого человеческий блок не пишет. Поэтому
            # она не срабатывала никогда, и заложенная стройка отчитывалась как
            # «НЕ НАЧАЛОСЬ»: модель выдумывала причину и повторяла заказ такт за
            # тактом. Теперь смотрим на wip — список того, что реально строится.
            если_повторы.pop((c, role), None)
            предел, строят, готово = строится_сейчас.get(role, (0, None, None))
            сколько = (f", строителей влезает {предел}" if предел
                       else ", предел строителей движок ещё не посчитал")
            if строят is not None:
                сколько += f", строят сейчас {строят}"
            if готово is not None:
                сколько += f", готово {готово}%"
            строки.append(f"  {c} {role} {total}: УЖЕ ЗАЛОЖЕНО и строится"
                          f"{сколько}. Не повторяй — дождись, заказ принят")
        else:
            # Стоимости зданий в читаемых данных игры нет, поэтому показываем
            # ресурсы на миг отказа: за несколько попыток порог виден из опыта.
            рес = " ".join(f"{имя}={стало.get(ключ, '?')}" for имя, ключ in
                           (("дерево", "wood"), ("камень", "stone"),
                            ("еда", "food"), ("золото", "gold"),
                            ("железо", "iron"), ("уголь", "coal")))
            нет = чего_не_хватает(role, стало)
            if нет:
                строки.append(впустую(
                    (c, role),
                    f"  {c} {role} {total}: НЕ НАЧАЛОСЬ, и причина "
                    f"известна — НЕТ {' и '.join(нет).upper()}. "
                    f"Сначала это, иначе заказ будет пропадать молча."))
            else:
                уже = int(стало.get(СЧЁТЧИК.get(role, ""), 0) or 0)
                дороже = (f" У тебя уже {уже} таких, а каждое следующее дороже "
                          f"предыдущего." if уже >= 1 and c == "BUILD" else "")
                # «ДЕЛО В РЕСУРСАХ» — ТОЛЬКО ЕСЛИ ИХ ПРАВДА НЕ ХВАТАЕТ. 22.09
                # по шести партиям мост шесть раз сказал это про мельницу при
                # дереве 300 и камне 300, а она стоит 60 и 300: ресурсов
                # хватало ровно. Причины были другие — на 25-54-й секунде игра
                # отвечала «nobody to build it — no peasants at all» (крестьяне
                # ещё не ищутся блоком), а дважды мельница уже стояла в wip,
                # и вердикт просто поспешил. Цена зданий у моста есть
                # (build_cost) — сверяем и говорим то, что знаем.
                _ц = (цена_построек(стало) or {}).get(role) or {}
                _хватает = bool(_ц) and all(
                    _чис(стало.get(р)) >= в for р, в in _ц.items() if в)
                if _хватает:
                    _игра = next((о for о in отказы(стало)
                                  if о.upper().startswith("BUILD")), "")
                    _цена = ", ".join(f"{РЕСУРС_РУС.get(р, р)} {в}"
                                      for р, в in _ц.items() if в)
                    строки.append(впустую(
                        (c, role),
                        f"  {c} {role} {total}: НЕ НАЧАЛОСЬ, хотя ресурсов "
                        f"ХВАТАЕТ (цена {_цена}; было: {рес}). "
                        + (f"Игра сказала: «{_игра}»." if _игра else
                           "Игра причину не назвала. В первые секунды партии "
                           "блок ещё не находит строителей — тогда повтори "
                           "через такт; если здание уже в списке "
                           "«СЕЙЧАС СТРОИТСЯ», оно началось.")
                        + дороже))
                else:
                    строки.append(впустую(
                        (c, role),
                        f"  {c} {role} {total}: НЕ НАЧАЛОСЬ. Требования "
                        f"выполнены, значит дело в ресурсах. Было в этот "
                        f"миг: {рес}.{дороже} Повторять с тем же запасом "
                        f"бесполезно."))
    return строки


