def поправить_роль(роль: str) -> tuple[str, str]:
    """Роль по синониму. Возвращает (роль, что сказать вслух или '')."""
    if not роль:
        return роль, ""
    ключ = роль.strip().lower().replace("-", "_")
    если = СИНОНИМЫ_РОЛЕЙ.get(ключ) or СИНОНИМЫ_РОЛЕЙ.get(ключ.replace("_", " "))
    if если and если != роль:
        return если, f"«{роль}» — это {если}, поправил и выполнил; зови так и дальше"
    return роль, ""


def нормализовать(item: dict) -> tuple[str, str, int]:
    """Одна команда модели -> (КОМАНДА, роль, число), как бы она её ни назвала."""
    c = str(item.get("cmd", item.get("command", ""))).upper().strip()
    роль = ""
    for k in СИНОНИМ_РОЛИ:
        v = item.get(k)
        if isinstance(v, str) and v.strip():
            роль = v.strip()
            break
    число = 0
    for k in СИНОНИМ_ЧИСЛА:
        if k in item:
            зн = item[k]
            # «all» вместо числа: ВСЕ свободные бойцы. ATTACK и так берёт только
            # простаивающих (block_hcmd: «takes idle men only»), поэтому любое
            # число больше наличных значит «всех» — но модель об этом не знала и
            # слала конкретные, заведомо меньшие: 19.09 в серии ушло 40 при 82
            # свободных. Слово понятнее числа с запасом.
            if isinstance(зн, str) and зн.strip().lower() in ("all", "все", "всех"):
                число = ВСЕ_СВОБОДНЫЕ
                break
            try:
                число = int(float(зн))
                break
            except (TypeError, ValueError):
                continue
    return c, роль, число



def отказы(st) -> list:
    """Все отказы такта из last_fail. Блок с 18.09 дописывает их через ' | ',
    а не перезаписывает: раньше из двух отказов в такте доживал последний."""
    сырое = str((st or {}).get("last_fail") or "")
    return [" ".join(ч.split()) for ч in сырое.split(" | ") if ч.strip()]

def _клетка_из(item):
    """cx/cy из ответа модели. Принимаем и пару полей, и список [x, y]:
    модель пишет то так, то так, а браковать за форму — терять такт."""
    c = item.get("cell", item.get("cxcy"))
    if isinstance(c, (list, tuple)) and len(c) == 2:
        пара = c
    else:
        пара = (item.get("cx"), item.get("cy"))
    try:
        cx, cy = int(пара[0]), int(пара[1])
    except (TypeError, ValueError):
        return None
    if 0 <= cx <= 15 and 0 <= cy <= 15:
        return (cx, cy)
    return None

def to_commands(data: dict, доступные: set[str] | None = None,
                взятые: set[str] | None = None, из_события: bool = False,
                st: dict | None = None
                ) -> tuple[list, int, str, list[str], str, int, str]:
    """JSON модели -> команды моста. Что не разобралось — возвращаем строками.

    Раньше непонятное отбрасывалось молча, и потерянная команда была неотличима
    от ненаписанной: ни в игре, ни в логе, ни в следующем запросе. Теперь брак
    называется вслух — и в консоли, и в промпте следующего такта.
    """
    cmds, attack, брак = [], 0, []
    # Отметка о STAGE живёт ОДИН такт. Без сброса здесь она залипнет, и
    # трасса скажет «модель включала накопление» в каждом такте после
    # первого — ровно та ошибка, ради поимки которой поле и заводится.
    STAGE_ЗА_ТАКТ.clear()
    цель_атаки = "base"
    кем_атака = ""        # вид бойцов для ATTACK, пусто — все
    кем_движение = ""     # то же для MOVE и RETREAT
    движение, цель_движения = 0, "home"
    # Клетка цели: (-1, -1) означает «модель её не называла».
    клетка = (-1, -1)
    # КОНТРАКТ МАРША (18.09, по документу игрока о манёврах): клетка сбора,
    # порог входа в бой, срок. Всё это пишет МОДЕЛЬ в своей команде, мост
    # только исполняет — иначе решение уходило бы от модели к мосту.
    контракт: dict = {}
    _все = data.get("commands") or []
    _предел = ПОЛИТИКА["команд_за_такт"]
    if len(_все) > _предел:
        # Молчаливый отброс неотличим от бездействия: до 16.09 седьмая команда
        # исчезала без слова, и модель считала, что отдала её.
        брак.append(f"команд в ответе {len(_все)}, мост читает первые "
                    f"{_предел} — не ушли: "
                    + ", ".join(str(i.get("cmd", "?")) for i in _все[_предел:]))
    for item in _все[:_предел]:
        if not isinstance(item, dict):
            брак.append(f"{item!r}: команда должна быть объектом JSON")
            continue
        c, role, total = нормализовать(item)
        role, поправка = поправить_роль(role)
        if поправка:
            # ВЫПОЛНЕНО, а не отвергнуто: говорим вслух тем же каналом, которым
            # мост сообщает о STAGE, чтобы модель выучила правильное имя.
            брак.append(f"{c}: {поправка}")
        # КЕМ выполнять: необязательное поле, общее для ATTACK, MOVE и RETREAT.
        # Имя вида берётся из состояния (infantry17, musk17, uniq_inf17,
        # dragoon17) — то же слово, каким модель читает свою строку найма и
        # размен. Пусто значит «всеми», как было до 19.09.
        кем = str(item.get("who", item.get("кем", "")) or "").strip()
        # «all» у who значит ВСЕ ВИДЫ — то же, что отсутствие поля. Раз
        # count:"all" уже есть, модель напишет так же и здесь, и укорять её за
        # осмысленную команду незачем: 19.09 такой ответ попадал в брак, хотя
        # исполнялся верно.
        if кем.lower() in ("all", "все", "всех", "любой", "любые", "any"):
            кем = ""
        if кем and кем not in ПОЛИТИКА["виды_бойцов"]:
            брак.append(f"{c} who={кем}: не знаю такого вида. Можно: "
                        f"{', '.join(ПОЛИТИКА['виды_бойцов'])}. Иду всеми")
            кем = ""
        поля = ", ".join(sorted(k for k in item if k != "cmd"))
        try:
            if role and role in ЗАПРЕТ:
                брак.append(f"{c} {role}: запрещено настройками этой партии")
                continue
            # ПРАВИЛО ИГРОКА 27.09: офицер и барабанщик — ТОЛЬКО при построенной
            # академии. Движок нам их даёт и без неё (мост зовёт _unit_ProduceUnit
            # мимо проверки access control, `country.script:3051` req0 = aca), и в
            # серии wood_academy они вышли на 537-й секунде без академии вовсе. Но
            # человек в интерфейсе так не может, значит это обход правил, а правила
            # запрещают ДЕЙСТВИЕ, а не только способ. Отвергаем ВСЛУХ (правило 1).
            # КЛЮЧ `academies`, а не роль `academi`: с ролью ворота отвергали найм
            # ВСЕГДА, даже при стоящей академии, и серия wood_academy2 измерила
            # этот дефект вместо идеи — 18 / 25 / 14 отказов в трёх копиях при
            # академии с 597 / 610 / 872 секунды, офицер не заказан ни разу.
            if (c == "TRAIN" and role in ("officer17", "drummer17")
                    and _чис(st.get(СЧЁТЧИК["academi"])) <= 0):
                брак.append(f"{c} {role}: НЕЛЬЗЯ БЕЗ АКАДЕМИИ. Движок их отдаёт и так, но "
                            f"человек за тем же экраном не может — это обход правил. "
                            f"Сначала BUILD academi (1050 дерева, 1230 камня), потом найм")
                continue
            # ВОЕННЫЙ НАЙМ — НЕ ДЕЛО ОБЫЧНОГО ТАКТА, если так велит ключ.
            # Замысел игрока 21.09: состав врага меняется быстрее, чем идёт
            # такт, и решать «кем воевать» должен узкий канал, который можно
            # звать хоть каждые десять секунд. Крестьяне остаются здесь: они
            # к составу врага отношения не имеют. Молча не отбрасываем —
            # правило 1 проекта: отброшенное неотличимо от ненаписанного.
            # `из_события` — не поблажка, а суть ключа: военных заказывает
            # именно событийный канал. Без этой оговорки отбор глушил бы и
            # его, и нанимать было бы НЕКОМУ — поймано проверкой сразу после
            # правки.
            if (ТОЛЬКО_НАЙМ and not из_события and c == "TRAIN" and role
                    and role in ПОЛИТИКА["виды_бойцов"]):
                брак.append(
                    f"TRAIN {role}: военных заказывает ОТДЕЛЬНЫЙ канал, его "
                    f"мост зовёт сам при достройке и раз в несколько секунд — "
                    f"там свежий состав врага. Твоё дело: экономика, стройки, "
                    f"апгрейды и бой. Крестьян заказывай как обычно")
                continue
            if c == "BUILD":
                # КЛЮЧ --barracks-first: шахты только ПОСЛЕ казармы, и отказ говорит
                # почему. Молчаливый отброс неотличим от бездействия (правило 1).
                if (КАЗАРМА_СНАЧАЛА and role in ("minegold", "mineiron", "minecoal")
                        and st is not None and float(st.get("ba17") or 0) <= 0):
                    брак.append(
                        f"BUILD {role}: ШАХТЫ ТОЛЬКО ПОСЛЕ КАЗАРМЫ (ключ этой партии). "
                        f"На старте у тебя по 1000 каждого ресурса: 500 золота на "
                        f"казарму есть сразу, а 1000 железа — это 50 пикинёров. Шахта "
                        f"сейчас добывает то, что уже в казне, и стоит 100 дерева, 100 "
                        f"камня, пятерых крестьян и 94 секунды. Поставь казарму, потом шахты")
                    continue
                if role not in BUILDABLE:
                    брак.append(f"BUILD {role or '?'}: такую постройку мост не умеет"
                                f" (поля: {поля}). Роли: {', '.join(sorted(BUILDABLE))}")
                elif total <= 0:
                    брак.append(f"BUILD {role}: нужно ИТОГО зданий числом > 0"
                                f" в поле total (поля: {поля})")
                else:
                    cmds.append(build(role, total))
            elif c == "TRAIN":
                if role not in ROLE:
                    брак.append(f"TRAIN {role or '?'}: неизвестный юнит"
                                f" (поля: {поля})")
                elif total == 0:
                    брак.append(f"TRAIN {role}: число 0 — это ничего не значит;"
                                f" отрицательное = бесконечный заказ (поля: {поля})")
                else:
                    # Отрицательное = бесконечное производство, см. train().
                    cmds.append(train(role, max(total, INFINITE)))
            elif c == "UPGRADE":
                # Сверяем с тем, что игра назвала доступным ЭТОЙ нации, а не со
                # статическим списком: тот достался от компьютерного слота, где
                # апгрейды заказывались по движковым константам. На человеческом
                # слоте имена другие (eurmil.1), и ни одно имя из старого списка
                # не могло совпасть никогда — 13.09 это стоило 21 такта.
                if доступные and role not in доступные:
                    брак.append(
                        f"UPGRADE {role or '?'}: у твоей нации такого нет. "
                        f"Доступно: {', '.join(sorted(доступные))}")
                elif not role:
                    брак.append(f"UPGRADE: нужно имя в поле role (поля: {поля})")
                elif взятые and role in взятые:
                    # ПОВТОРНЫЙ ЗАКАЗ ВЗЯТОГО ОТКАТЫВАЕТ СЛЕДУЮЩУЮ СТУПЕНЬ.
                    # Механика из кода игры (`lib/player.script:1986-1998`):
                    # апгрейды связаны в цепочки `upgradelinks`, и взятие звена
                    # ВКЛЮЧАЕТ следующее, ставя ему `done := False`. Для первого
                    # взятия это верно — ступень открылась. Но заказ УЖЕ ВЗЯТОГО
                    # проходит снова, платно, и сбрасывает `done` у следующей.
                    #
                    # Живая партия 20.09, дважды подряд и одинаково: заказ
                    # `bar.pikeman.2.1` на 9:06 — потеря `bar.pikeman.2.2` на
                    # 9:59; заказ того же на 11:00 — потеря на 11:46. Атака
                    # пикинёра всё это время стояла на 8. В `base21` то же на
                    # 6:02 -> 6:23. Похоже, отсюда и 56 приказов UPGRADE за
                    # четыре партии при верхней взятой ступени 3-5.
                    #
                    # Мост ПРОСИЛ не повторять словами («второй раз их не
                    # заказывают») — этого мало: просьба не мешает команде уйти
                    # в игру. Отбрасываем и говорим вслух, иначе отброс
                    # неотличим от бездействия.
                    брак.append(
                        f"UPGRADE {role}: он УЖЕ ВЗЯТ, и повторный заказ не "
                        f"усиливает, а ОТКАТЫВАЕТ следующую ступень — в игре "
                        f"ступени связаны цепочкой, и повторное взятие снимает "
                        f"отметку со следующей. Команда отброшена. Бери "
                        f"СЛЕДУЮЩУЮ ступень или другую линейку")
                else:
                    cmds.append(upgrade(role))
            elif c == "STAGE":
                # НАКОПЛЕНИЕ (19.09, предложение игрока). MOVE — приказ РАЗОВЫЙ:
                # он уводит тех, кто свободен СЕЙЧАС, а выкованные следом
                # остаются дома. Поэтому кулак собирался только в миг удара и
                # шёл к цели 92-142 с, пока его отряды доходили за 18-22.
                # STAGE — приказ СТОЯЧИЙ: мост сам досылает свежих в ту же
                # клетку каждый такт, пока его не отменят.
                #
                # Зачем вообще: волна без сбора растягивается (замер 16.09 —
                # с пятерых разрыв 22 единицы, и он держится всю дорогу) и
                # бьётся по ЛИНЕЙНОМУ закону, а собранный кулак — по корню из
                # размена. Накопление меняет не аккуратность, а формулу.
                if str(item.get("off", "")).strip() not in ("", "0", "false"):
                    if НАКОПЛЕНИЕ:
                        НАКОПЛЕНИЕ.clear()
                        брак.append("STAGE отменён: свежие бойцы снова копятся дома")
                    STAGE_ЗА_ТАКТ.update(что="отменено")
                    continue
                кл = _клетка_из(item)
                if кл is None:
                    брак.append(f"STAGE: нужна клетка сетки, поля cx и cy от 0 "
                                f"до 15 (поля: {поля})")
                else:
                    try:
                        _дома = max(0, int(float(item.get("keep", 0) or 0)))
                    except (TypeError, ValueError):
                        _дома = 0
                    # `st` сюда не приходит — время проставит тот, кто зовёт.
                    НАКОПЛЕНИЕ.update(cx=кл[0], cy=кл[1], keep=_дома,
                                      who=кем or "")
                    STAGE_ЗА_ТАКТ.update(что="включено", cx=кл[0], cy=кл[1],
                                         keep=_дома, who=кем or "")
            elif c == "MOVE":
                # То же движение, что у ATTACK, но без режима атаки: бойцы идут
                # и не ищут врага по дороге. Человек двигает войска кликом и не
                # обязан вести их в бой; у бота такой возможности не было вовсе.
                if total > 0:
                    движение = max(движение, total)
                    цель = str(item.get("target", item.get("where", ""))).strip().lower()
                    if цель in ПОЛИТИКА["цели_MOVE"]:
                        цель_движения = цель
                        if цель == "cell":
                            кл = _клетка_из(item)
                            if кл is None:
                                цель_движения = "home"
                                брак.append(
                                    f"MOVE target=cell: нужна клетка сетки, "
                                    f"поля cx и cy от 0 до 15 (поля: {поля}). "
                                    f"Иду на home")
                            else:
                                клетка = кл
                        кем_движение = кем
                    elif цель:
                        брак.append(f"MOVE target={цель}: не знаю такой цели; "
                                    f"можно home, peasants, base, army, cell")
                else:
                    брак.append(f"MOVE: нужно число бойцов > 0 в поле count"
                                f" (поля: {поля})")
            elif c == "RETREAT":
                # Отзыв волны: бойцы дальше 60 от ратуши идут домой без боя.
                # Едет тем же файлом приказа, что MOVE, режимом retreat.
                if total > 0:
                    движение = max(движение, total)
                    цель_движения = "retreat"
                    кем_движение = кем
                else:
                    брак.append(f"RETREAT: нужно число бойцов > 0 в поле count"
                                f" (поля: {поля})")
            elif c == "ATTACK":
                if total > 0:
                    attack = max(attack, total)
                    кем_атака = кем
                    цель = str(item.get("target", item.get("where", ""))).strip().lower()
                    if цель in ПОЛИТИКА["цели_ATTACK"]:
                        цель_атаки = цель
                        if цель == "cell":
                            кл = _клетка_из(item)
                            if кл is None:
                                цель_атаки = "peasants"
                                брак.append(
                                    f"ATTACK target=cell: нужна клетка сетки, "
                                    f"поля cx и cy от 0 до 15 (поля: {поля}). "
                                    f"Иду на peasants")
                            else:
                                клетка = кл
                        # Контракт марша. Каждое поле — решение модели, и
                        # каждое непринятое поле называется вслух.
                        via = item.get("via")
                        if via is not None:
                            кл_via = _клетка_из(via) if isinstance(via, dict) else None
                            if кл_via is None:
                                брак.append(f"ATTACK via: нужна клетка сбора вида "
                                            f'{{"cx":x,"cy":y}} от 0 до 15 (поля: '
                                            f"{поля}). Иду без сбора, прямо из дома")
                            elif цель_атаки == "cell" and tuple(кл_via) == tuple(клетка):
                                # Сбор В САМОЙ ЦЕЛИ — это сбор, которого нет:
                                # «дойти до клетки сбора» означает «дойти до
                                # места боя», и группа собирается там, где её
                                # уже бьют. 19.09, via_rally: такой марш из 59
                                # бойцов дал «дошли 0 из 39» за 120 с, mil_hurt
                                # 41, и отменился, а три марша с отдельной
                                # клеткой сбора в той же серии собрались все.
                                # Идём обычным ударом: намерение модели —
                                # ударить по клетке — исполняется, отброшен
                                # только бессмысленный сбор. Молча этого делать
                                # нельзя, иначе отказ неотличим от исполнения.
                                брак.append(
                                    f"ATTACK via ({кл_via[0]},{кл_via[1]}): клетка сбора "
                                    f"совпала с целью — это не сбор, а тот же удар: "
                                    f"дойти до неё значит дойти до боя, и собираться "
                                    f"группа будет под огнём. Иду обычным ударом, БЕЗ "
                                    f"сбора. Нужен сбор — ставь via на СВОЕЙ половине "
                                    f"пути, между твоей базой и целью")
                            elif БЕЗ_СБОРА:
                                # --no-gather: сбор выключен ключом. Говорим
                                # ВСЛУХ — молчаливый отброс неотличим от
                                # исполнения, и модель должна знать, что её
                                # via не взята, иначе она будет ждать сбора,
                                # которого нет.
                                брак.append(
                                    f"ATTACK via ({кл_via[0]},{кл_via[1]}): сбор "
                                    f"ВЫКЛЮЧЕН ключом --no-gather, клетка сбора не "
                                    f"заводится. Иду обычным ударом прямо по цели. "
                                    f"Причина: по 614 тактам трёх серий убийства "
                                    f"идут там, где наши бойцы стоят В ОДНОЙ КЛЕТКЕ "
                                    f"с его крестьянами, и решает присутствие, а не "
                                    f"число: 98 из 102 убитых при медианно 7,5 "
                                    f"бойцах в клетке. Сбор же только откладывает — "
                                    f"до клетки сбора доходит меньше трети колонны")
                            else:
                                контракт["via"] = кл_via
                        порог = item.get("hold_if_outnumbered")
                        if порог is not None:
                            try:
                                контракт["hold"] = float(порог)
                                if контракт["hold"] <= 0:
                                    raise ValueError
                            except (TypeError, ValueError):
                                контракт.pop("hold", None)
                                брак.append(f"ATTACK hold_if_outnumbered={порог}: "
                                            f"нужно число больше нуля, например 1.3")
                        срок = item.get("expires")
                        if срок is not None:
                            try:
                                контракт["expires"] = int(float(срок))
                                if контракт["expires"] <= 0:
                                    raise ValueError
                            except (TypeError, ValueError):
                                контракт.pop("expires", None)
                                брак.append(f"ATTACK expires={срок}: нужно число "
                                            f"секунд больше нуля")
                        при_стоим = item.get("if_held")
                        if при_стоим is not None:
                            при_стоим = str(при_стоим).strip().lower()
                            if при_стоим in ("wait", "retreat", "attack"):
                                контракт["if_held"] = при_стоим
                            else:
                                брак.append(f"ATTACK if_held={при_стоим}: можно wait, "
                                            f"retreat или attack; беру wait")
                        при_перехвате = item.get("if_intercepted")
                        if при_перехвате is not None:
                            при_перехвате = str(при_перехвате).strip().lower()
                            if при_перехвате in ("push", "retreat", "fight"):
                                контракт["if_intercepted"] = при_перехвате
                            else:
                                брак.append(f"ATTACK if_intercepted={при_перехвате}: можно push, "
                                            f"retreat или fight; беру push")
                        доля = item.get("retreat_below")
                        if доля is not None:
                            # Доля ПОСЛАННЫХ, ниже которой мост отзывает волну
                            # домой (RETREAT в блоке команд с 18.09). Считается по
                            # mil_away: бойцы дальше 60 от ратуши.
                            try:
                                контракт["retreat"] = float(доля)
                                if not (0 < контракт["retreat"] < 1):
                                    raise ValueError
                            except (TypeError, ValueError):
                                контракт.pop("retreat", None)
                                брак.append(f"ATTACK retreat_below={доля}: нужна доля "
                                            f"между 0 и 1, например 0.5")
                    elif цель:
                        брак.append(f"ATTACK target={цель}: не знаю такой цели; "
                                    f"можно peasants, base, army, cell, wave")
                else:
                    брак.append(f"ATTACK: нужно число бойцов > 0 в поле count"
                                f" (поля: {поля})")
            elif c == "FORMATION":
                # ОТКЛЮЧЕНА 16.09. Строй в нынешнем виде собирается вокруг
                # офицера, а офицер и барабанщик делаются ТОЛЬКО в академии
                # (country.script:3047,3051 — требование csid+'aca'), и она
                # была запрещена ключом --ban. То есть команда не могла
                # сработать ни разу.
                #
                # 20.09 ОСНОВАНИЕ ОТПАЛО: академия разрешена (запретить её
                # настройкой карты нельзя, а односторонний запрет был той самой
                # асимметрией — у врага академия стояла в каждой партии).
                # Значит офицер и барабанщик достижимы, и строй снова можно
                # проверять. Пока НЕ включаю: это отдельная идея и отдельный
                # замер, а в Cossacks строй даёт боевой бонус — то есть бьёт
                # ровно в нашу беду, что армия дерётся растянуто (связка 8).
                #
                # Отброс не молчаливый (правило 1): говорим причину. Из промпта
                # команда убрана, но если модель вспомнит её по памяти — она
                # услышит, почему нет, а не получит тишину.
                # 24.09 ВКЛЮЧЕНА (ветка idea/formation). Проверка тут же, а не
                # в игре: без обоих блок откажет и скажет почему, но такт уже
                # потрачен. Сам отряд собирает блок: свободная пехота вокруг
                # офицера, самый широкий строй с бонусом, что помещается.
                # Без состояния (старые вызовы, самопроверки) команда уходит в
                # блок как есть: он сам откажет и назовёт причину в квитанции.
                _оф = _чис(st.get("my_officers")) if st else 1
                _бар = _чис(st.get("my_drummers")) if st else 1
                if _оф > 0 and _бар > 0:
                    cmds.append(formation())
                else:
                    брак.append(
                        f"FORMATION: нужны ОБА — офицер и барабанщик, у тебя "
                        f"офицеров {_оф}, барабанщиков {_бар}. TRAIN officer17 и "
                        f"TRAIN drummer17 делаются в академии (BUILD academi)")
            elif c == "SEED":
                # ЧИСЛО ТЕПЕРЬ НУЖНО (21.09, наблюдение игрока): выкошенную
                # четверть поля засевают НЕСКОЛЬКИМИ полями подряд, а не одним.
                # Раньше команда всегда заказывала одно, и пересев растягивался
                # на такты по двадцать секунд. Без числа — по-прежнему одно.
                cmds.append(seed(total if total and total > 0 else 1))
            elif c == "BUILDERS":
                if total > 0:
                    cmds.append(builders(total))
                else:
                    # BUILDERS 0 отвергался 39 раз (замер 27.09): модель этим
                    # говорит «никого лишнего», а мост требовал числа. Поправляем
                    # на 1 и говорим вслух — ход не теряется.
                    if total == 0:
                        брак.append("BUILDERS 0: это «по минимуму», ВЫПОЛНИЛ как 1;"
                                    " чтобы вообще не занимать людей, просто не"
                                    " закладывай стройку")
                        cmds.append(builders(1))
                        continue
                    брак.append(f"BUILDERS {total}: нужно число > 0 — сколько "
                                f"крестьян максимум на одну стройку")
            elif c == "BALANCE":
                if role not in RESOURCE:
                    брак.append(f"BALANCE {role or '?'}: ресурс не опознан"
                                f" (поля: {поля}). Только: "
                                f"{', '.join(RESOURCE)}")
                else:
                    cmds.append(balance(role, total))
            else:
                брак.append(f"{c or '?'}: нет такой команды (поля: {поля})")
        except ValueError as e:
            брак.append(f"{c} {role}: {e}")
    # ДВА ПРИКАЗА ОДНОГО РОДА в одном ответе. Файл приказа ОДИН
    # (coss3_atk_P<n>.dat): блок читает его и удаляет за тик, так что второй
    # затирает первый ещё до того, как игра заберёт. До 19.09 лишний приказ
    # пропадал МОЛЧА — модель просила «мушкетёров в одну клетку, драгун в
    # другую», а уходили только вторые, и в трассе это выглядело её решением.
    for _род, _имя in (("ATTACK", "ATTACK"), ("MOVE", "MOVE"), ("RETREAT", "RETREAT")):
        _сколько = sum(1 for _i in _все
                       if str(_i.get("cmd", _i.get("command", ""))).upper().strip() == _род)
        if _сколько > 1:
            брак.append(
                f"{_имя} в ответе {_сколько} раза: файл приказа ОДИН, и выполнен "
                f"будет ПОСЛЕДНИЙ — остальные пропадут. Дели по тактам: один "
                f"удар за такт. Если нужен другой вид бойцов, отдай его "
                f"следующим ходом")
    # Атака важнее движения: если модель отдала обе, идём в бой, а про
    # проглоченный MOVE говорим вслух - молчаливый отброс неотличим от отказа.
    if attack and движение:
        брак.append("MOVE и ATTACK в одном ответе: выполнен ATTACK, "
                    "движение пропущено — файл приказа один")
        движение = 0
    return (cmds, attack, str(data.get("why", ""))[:200], брак, цель_атаки,
            движение, цель_движения, клетка, контракт, кем_атака, кем_движение)


MAX_TOKENS = 1200         # с запасом: обрезанный ответ теряет весь такт
LAST_TOKENS = 0           # токенов в последнем ответе: отличить болтливость от очереди
LAST_PROVIDER = ""        # кто обслужил: у OpenRouter это решает всё
# Провайдеры, через которых OpenRouter НЕ должен вести запрос. Два источника:
#   * не обслуживают наш регион - отказ постоянный, запоминаются на сессию
#     по ходу (AUTOBAN ниже);
#   * МЕДЛЕННЫЕ ПО ЗАМЕРУ - перечислены здесь заранее. 18.09, 2700 вызовов по
#     всем трассам 17-18.09: DigitalOcean - медиана 16,9 с при бюджете такта
#     20, каждый шестой вызов дольше 30 с, худший 269 с. Каждый такой ответ -
#     полторы минуты партии без бота. Таблица в preset_gamer.md.
# Уходит в запрос полем provider.ignore и действует ПОВЕРХ пресета на сайте
# OpenRouter, так что правка здесь не ждёт правки пресета. --provider-ignore
# добавляет к списку, --provider-only его обходит целиком.
BANNED: set[str] = {"DigitalOcean"}
ЗАПРЕТ: set[str] = set()   # роли, запрещённые настройками партии (--ban)
# Военный найм отдан событийному каналу: TRAIN на бойцов от ОБЫЧНОГО такта
# мост в игру не пропускает и говорит об этом модели. Ключ --hire-only, по
# умолчанию выключено. Ответы самого события проходят (параметр `из_события`).
ТОЛЬКО_НАЙМ: bool = False
ONLY: list[str] = []      # если задан — маршрут только через этих, без запасных
AUTOBAN = True            # выключается --no-provider-ban, чтобы проверить руками
REPLAY: list[dict] = []   # заранее записанные ответы вместо вызова модели
_REPLAY_I = 0
_REPLAY_LOCK = threading.Lock()


def загрузить_реплей(путь: str) -> int:
    """Ответы модели из файла: по JSON на строку, либо несколько подряд.

    Зачем: ключ живёт на игровой машине, а петлю надо проверять на маке. С
    реплеем `llm_policy.py` против `mock_game.py` прогоняется целиком и без
    сети — видно, доезжают ли до модели новые блоки запроса, живут ли счётчики
    между тактами, отбрасывается ли урок. Ответы из настоящего лога достаёт
    `log_review.py --replay-out`, и тогда это прогон по исторической партии:
    мост обязан ругаться там, где в тот раз промолчал.
    """
    текст = open(путь, encoding="utf-8").read()
    ответы = []
    for строка in текст.splitlines():
        строка = строка.strip()
        if not строка or строка.startswith("#"):
            continue
        try:
            ответы.append(json.loads(строка))
        except ValueError:
            ответы.extend(json_objects(строка))
    if not ответы:                          # не построчный файл — разберём целиком
        ответы = json_objects(текст)
    REPLAY.extend(ответы)
    return len(ответы)


def следующий_ответ() -> dict:
    global _REPLAY_I
    with _REPLAY_LOCK:
        if _REPLAY_I >= len(REPLAY):
            raise RuntimeError(f"ответы для --replay кончились ({len(REPLAY)} шт.)")
        _REPLAY_I += 1
        return REPLAY[_REPLAY_I - 1]


def json_objects(text: str) -> list[dict]:
    """Разобранные ответы модели, по порядку.

    Пробуем от КАЖДОЙ «{», а не считаем баланс скобок с начала: модель бросает
    недописанный объект и начинает заново, и одна незакрытая скобка в начале
    иначе проглатывает весь остальной текст.
    """
    dec = json.JSONDecoder()
    out = []
    for i, ch in enumerate(text):
        if ch != "{":
            continue
        try:
            obj, _ = dec.raw_decode(text, i)
        except ValueError:
            continue                       # огрызок — идём к следующей скобке
        if isinstance(obj, dict) and ("commands" in obj or "why" in obj):
            out.append(obj)                # внутренние {"cmd":...} сюда не попадут
    return out


# --- СХЕМА ОТВЕТА (нативный structured output) ---------------------------
#
# До 16.09 мост ПРОСИЛ вернуть JSON словами и разбирал что придёт: ловил
# огрызки, синонимы полей ('count' вместо 'total', 'building' вместо 'role')
# и куски текста вокруг скобок. Сколько такого было, видно в отчёте: строка
# «команд отвергнуто» и блок «Команды, которые НЕ УШЛИ В ИГРУ».
#
# Схема описывает РОВНО то, что мост и так разбирает, и ничего сверх: имена
# полей канонические, число у BUILD/TRAIN/BALANCE/BUILDERS это total, у
# ATTACK/MOVE — count, у UPGRADE имя лежит в role. Разбор остаётся прежним:
# схема сужает вход, а не заменяет проверку. Провайдер, который схемы не
# знает, ответит отказом — тогда мост снимает её, говорит об этом вслух и
# доигрывает как раньше.
_КОМАНДА_СХЕМА = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "cmd": {"type": "string",
                # FORMATION вернулась 24.09: см. комментарий у "команды".
                "enum": ["BUILD", "TRAIN", "BALANCE", "BUILDERS",
                         "SEED", "UPGRADE", "ATTACK", "MOVE", "RETREAT",
                         "FORMATION"]},
        "role": {"type": ["string", "null"],
                 "description": "роль здания/юнита/ресурса; для UPGRADE — имя апгрейда"},
        "total": {"type": ["integer", "null"],
                  "description": "желаемый ИТОГ для BUILD/TRAIN/BALANCE/BUILDERS; -1 — без счёта"},
        "count": {"type": ["integer", "null"],
                  "description": "сколько бойцов для ATTACK и MOVE"},
        "target": {"type": ["string", "null"],
                   "enum": ["peasants", "base", "army", "home", "cell", "wave", None]},
    },
    "required": ["cmd", "role", "total", "count", "target"],
}

СХЕМА_ОТВЕТА = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "why": {"type": "string", "description": "что делаешь сейчас и зачем, одно предложение"},
        "ok": {"type": "string", "description": "что получается; пусто, если сказать нечего"},
        "stuck": {"type": "string", "description": "что НЕ получается; пусто, если всё идёт"},
        "cause": {"type": "string", "description": "почему не получается"},
        "lesson": {"type": "string", "description": "вывод из СЛУЧИВШЕГОСЯ; пусто, если ничего не произошло"},
        "idea": {"type": "string", "description": "гипотеза об устройстве игры; пусто, если нет"},
        "question": {"type": "string", "description": "один вопрос человеку; пусто, если нет"},
        "commands": {"type": "array", "items": _КОМАНДА_СХЕМА},
    },
    "required": ["why", "ok", "stuck", "cause", "lesson", "idea",
                 "question", "commands"],
}

СХЕМОЙ = False         # --schema включает; отказ провайдера снимает обратно


class Родной:
    """Клиент РОДНОГО пути ollama: схема идёт ГРАММАТИКОЙ, а не просьбой.

    Замер 23.09 на тех же девяти событийных запросах, что и всё остальное.
    Через `/v1/chat/completions` думающая `qwen3:30b-a3b` сперва рассуждает —
    700-1400 токенов, 48-344 с, один вызов сорвался по таймауту вовсе, другой
    занял 1190 токенов при потолке 1200. Ни один из ШЕСТИ выключателей думания
    на этом пути не работает: `reasoning_effort=none` и `low`,
    `chat_template_kwargs.enable_thinking=false`, `think=false`, `/no_think` в
    тексте, схема ответа.

    На `/api/generate` со схемой ollama строит ГРАММАТИКУ: модель физически не
    может выдать токен вне JSON, и рассуждению негде начаться. Те же запросы:
    **2,2-2,5 с и 27 токенов**. То есть негодна была не модель, а путь.

    Две ловушки родного пути, обе куплены стендом 22.09 (`bench_local.py`):
      * со схемой ollama кладёт готовый ответ в поле `thinking`, оставляя
        `response` пустым — пустой `response` тут НЕ молчание модели;
      * `num_predict` обрывает ответ по длине, и обрыв неотличим от «не JSON».
        Событийный ответ укладывается в 27 токенов, потолок 200 с запасом.
    """

    def __init__(self, база: str):
        # Адрес приходит с хвостом /v1 (его ждёт OpenAI-клиент) — родному пути
        # нужен корень.
        self.база = база.rstrip("/")
        if self.база.endswith("/v1"):
            self.база = self.база[:-3]

    def __repr__(self):
        return f"Родной({self.база})"


def _спросить_ollama(кл: "Родной", model: str, prompt: str, system: str,
                     схема: dict | None, потолок: int) -> dict:
    """Один вызов родным путём. Возвращает разобранный JSON, как `ask`."""
    тело = {"model": model, "prompt": prompt, "stream": False,
            "options": {"num_predict": потолок, "temperature": 0.4}}
    if system:
        тело["system"] = system
    if схема is not None:
        тело["format"] = схема
    req = urllib.request.Request(кл.база + "/api/generate",
                                 json.dumps(тело).encode(),
                                 {"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=EVENT_TIMEOUT) as r:
        d = json.load(r)
    global LAST_TOKENS, LAST_PROVIDER
    LAST_TOKENS = d.get("eval_count") or 0
    LAST_PROVIDER = "ollama"
    текст = (d.get("response") or "").strip() or (d.get("thinking") or "")
    # Под грамматикой ответ — РОВНО один объект заданной формы, поэтому
    # разбираем прямо. `json_objects` здесь не годится: он пропускает только
    # объекты с `why` или `commands` (форма обычного такта), а схема повода
    # может быть любой — и тогда годный ответ был бы выброшен как мусор.
    try:
        прямо = json.loads(текст)
        if isinstance(прямо, dict):
            return прямо
    except ValueError:
        pass
    объекты = json_objects(текст)
    if not объекты:
        обрыв = d.get("done_reason") == "length"
        raise ValueError(
            f"родной путь ollama: JSON не разобран"
            f"{' (ОБРЫВ по num_predict=%d)' % потолок if обрыв else ''}. "
            f"Хвост: ...{текст[-160:]}")
    return объекты[-1]


EVENT_TIMEOUT = 90       # родной путь: событие короткое, ждать дольше незачем


def ask(client, model: str, prompt: str, think: bool = False,
        retry: int = 1, max_tokens: int = 0, system: str = "",
        схема: dict | None = None, усилие: str = "") -> dict:
    """Один вызов модели. `system` задаётся ЯВНО там, где роль другая.

    Подменять глобальный SYSTEM для этого нельзя: событийный вопрос о найме
    уходит из ФОНОВОГО потока, и подмена гонялась бы с обычным тактом.
    Пусто — берётся общий SYSTEM, как было.

    `схема` — СВОЯ форма ответа для ЭТОГО вызова, поверх глобального флага
    --schema и независимо от него. Нужна событийному каналу на локальной
    модели (22.09): без схемы qwen2.5:7b на вопросе «куда людей» выдумал поля
    («people», «destination») и назвал ресурс по-русски — мост такой ответ
    отверг бы; со схемой поля и перечисление соблюдены. Обычный такт этого
    параметра не получает и играет как прежде.

    `усилие` — `reasoning_effort` ДУМАЮЩЕЙ модели (`--event-reasoning none`).
    Замер 22.09 через `/v1` на qwen3:30b-a3b, один и тот же вопрос найма: со
    схемой — 48 с и ПУСТОЙ content (обрыв по max_tokens на рассуждении); без
    схемы — 28,8 с и верный JSON после 864 токенов рассуждения; со схемой и
    `reasoning_effort="none"` — 1,1 с, 19 токенов, тот же ответ. `think=false`
    и `chat_template_kwargs.enable_thinking=false` через `/v1` не делают
    НИЧЕГО (34 и 35 с с полным рассуждением) — выключатель один. Пусто —
    ключ не посылается вовсе: облачным он чужой.
    """
    if REPLAY:                              # --replay: модель не зовём вовсе
        return следующий_ответ()
    if isinstance(client, Родной):
        # Родной путь ollama: схема грамматикой. `усилие` здесь не нужно —
        # выключать нечего, рассуждению негде начаться.
        return _спросить_ollama(client, model, prompt, system or SYSTEM,
                                схема, max_tokens or 200)
    kw = dict(
        model=model,
        messages=[{"role": "system", "content": system or SYSTEM},
                  {"role": "user", "content": prompt}],
        temperature=0.4,
        max_tokens=max_tokens or MAX_TOKENS,
    )
    if схема is not None:
        kw["response_format"] = {
            "type": "json_schema",
            "json_schema": {"name": "coss3_event", "strict": True,
                            "schema": схема},
        }
    elif СХЕМОЙ:
        kw["response_format"] = {
            "type": "json_schema",
            "json_schema": {"name": "coss3_move", "strict": True,
                            "schema": СХЕМА_ОТВЕТА},
        }
    extra: dict = {}
    if усилие:
        extra["reasoning_effort"] = усилие
    if ONLY:
        extra["provider"] = {"order": list(ONLY), "allow_fallbacks": False}
    elif BANNED:
        extra["provider"] = {"ignore": sorted(BANNED)}
    # nemotron-3.5 по умолчанию рассуждает вслух и съедает лимит, не дойдя до
    # JSON. В такт это не влезает, поэтому рассуждения гасим. Модель, которая
    # такого ключа не знает, ответит 400 — тогда повторяем без него.
    if not think:
        extra["chat_template_kwargs"] = {"enable_thinking": False}
        # То же самое на языке OpenRouter. Ключ выше понимают NIM и vLLM, а
        # OpenRouter — нет, и рассуждающая модель через него съедает лимит,
        # не дойдя до JSON. Замер 11.09.2026 на deepseek-v4.1-flash, один и
        # тот же запрос: без этого поля 75 с и ответ обрезан на 1200 токенах,
        # с ним — 1,8 с и 84 токена. Провайдер, который поля не знает, ответит
        # 400, и весь extra_body снимается ниже.
        extra["reasoning"] = {"enabled": False}
    if extra:
        kw["extra_body"] = extra
    try:
        r = client.chat.completions.create(**kw)
    except Exception as e:
        msg = str(e)
        # Регион не поддерживается — отказ навсегда. Запоминаем провайдера и
        # сразу пробуем ещё раз, попросив OpenRouter его обойти.
        if AUTOBAN and not ONLY and "unsupported_country_region_territory" in msg:
            имя = re.search(r"'provider_name':\s*'([^']+)'", msg)
            if имя and имя.group(1) not in BANNED:
                BANNED.add(имя.group(1))
                print(f"        {имя.group(1)} не обслуживает наш регион — "
                      f"исключаю его из маршрутизации")
                return ask(client, model, prompt, think, retry,
                           max_tokens, system, схема, усилие)
        if "404" in msg or "not found" in msg.lower():
            # Пресет — не модель, и совет про каталог NVIDIA тут вреден: он
            # уводит от настоящей причины. 12.09 на этом потеряли круг: мост
            # подменил ответ сервера догадкой. Показываем, что сказал сервер.
            if model.startswith("@preset/"):
                raise RuntimeError(
                    f"пресет {model} не найден. Что проверить, по порядку:\n"
                    f"        1) пресет создан и СОХРАНЁН на openrouter.ai/settings/presets;\n"
                    f"        2) Slug совпадает буква в букву: "
                    f"{model.split('/', 1)[1]!r} (он не равен названию);\n"
                    f"        3) ключ из nim_key.txt принадлежит ТОМУ ЖЕ аккаунту, "
                    f"где лежит пресет;\n"
                    f"        4) в пресете выбрана хотя бы одна модель.\n"
                    f"        Ответ сервера: {msg[:300]}") from e
            raise RuntimeError(
                f"модель {model} не отвечает — её убрали из каталога?\n"
                f"        сверьтесь с openrouter.ai/models и задайте другую: "
                f"--model <id> или COSS3_MODEL\n"
                f"        Ответ сервера: {msg[:300]}") from e
        # Схему понимают не все провайдеры. Снимаем её НАВСЕГДА для этого
        # прогона и говорим вслух: молчаливый откат неотличим от того, что
        # схема работает, и в отчёте потом не понять, что именно проверялось.
        if "response_format" in kw and any(
                w in msg.lower() for w in
                ("response_format", "json_schema", "structured output",
                 "schema", "json mode")):
            kw.pop("response_format")
            if схема is not None:
                # Своя схема на вызов: глобальный флаг НЕ трогаем — отказ
                # одного адреса не повод раздевать обычный такт.
                print("        сервер не принял СХЕМУ СОБЫТИЯ — этот вызов идёт "
                      "без неё, просьбой вернуть JSON")
            else:
                globals()["СХЕМОЙ"] = False
                print("        провайдер не принял СХЕМУ ОТВЕТА — снимаю её до конца "
                      "прогона, дальше как раньше: просьбой вернуть JSON")
            return_r = client.chat.completions.create(**kw)
            r = return_r
        else:
            # Откат делаем ТОЛЬКО на отказ разобрать запрос. На таймауте и обрыве
            # повторять нельзя: вторая попытка удвоит и без того съеденный такт.
            отказ = any(w in msg.lower() for w in
                        ("400", "422", "extra", "not permitted", "unexpected",
                         "unrecognized", "invalid"))
            if "extra_body" not in kw or not отказ:
                raise
            kw.pop("extra_body")            # ключ рассуждений понимают не все
            if усилие:
                # Молчать тут нельзя: без reasoning_effort думающая модель
                # уходит на 48 с и возвращает ПУСТО, а в трассе это выглядит
                # как молчание модели, а не как отвергнутый ключ.
                print(f"        сервер не принял reasoning_effort={усилие!r} — "
                      f"думание НЕ выключено, ответа можно ждать десятки секунд")
            r = client.chat.completions.create(**kw)
    global LAST_TOKENS, LAST_PROVIDER
    LAST_TOKENS = getattr(getattr(r, "usage", None), "completion_tokens", 0) or 0
    LAST_PROVIDER = str(getattr(r, "provider", "") or "")
    ch = r.choices[0]
    text = ch.message.content or ""
    objs = json_objects(text)
    if objs:
        rich = [o for o in objs if o.get("commands")]
        return (rich or objs)[-1]          # последний непустой: он и есть ответ
    fin = getattr(ch, "finish_reason", "") or "?"
    if retry > 0:                          # мусор бывает разовым — переспросим
        # Переспрашивать ТЕМ ЖЕ вызовом. До 23.09 здесь терялись и роль, и
        # схема, и выключатель думания: событийный переспрос уходил с ролью
        # общего такта, без схемы и с думанием обратно включённым — то есть
        # заведомо в пустой ответ за 48 с.
        return ask(client, model, prompt, think, retry - 1,
                   max_tokens, system, схема, усилие)
    if fin == "length":
        raise ValueError(
            f"ответ обрезан на {MAX_TOKENS} токенах, до JSON модель не дошла. "
            f"Хвост: ...{text[-160:]}")
    # Показываем ответ ЦЕЛИКОМ (до 2000 символов). 14.09 здесь стояло 300, и
    # четыре подряд неудачи критика выглядели как «ответ обрезан провайдером»,
    # хотя обрезал их сам этот print. Чинить по обрезанной улике нельзя.
    raise ValueError(f"нет разбираемого JSON (finish_reason={fin}), "
                     f"длина {len(text)}: {text[:2000]}")


def одна_партия(a, client, br: Bridge, plind: int,
                номер_эпизода: int = 1) -> str:
    """Ведёт одну партию до конца. Возвращает исход:
    «цель» — крестьянин убит, «горизонт» — время вышло,
    «обрыв» — состояние перестало обновляться.
    """
    # ВАЖНО: сначала проглотить то, что лежит в файле, и только потом ждать
    # новую запись. После NEW в файле ещё состояние ПРОШЛОЙ партии — с её
    # игровым временем. Первый запрос уходил на нём, next_call назначался в
    # будущее прошлой партии, и цикл молчал полторы минуты.
    br.read_state()
    # Дебют скриптом — свой на каждую партию; пометка прошлой партии из
    # дописок убирается, иначе модель прочтёт чужой отчёт.
    дебют = None
    ДОПИСКИ[:] = [x for x in ДОПИСКИ if not str(x).startswith("ДЕБЮТ СДЕЛАН СКРИПТОМ")]
    if int(getattr(a, "debut", 0) or 0) > 0:
        import debut as _debut
        дебют = _debut.Дебют(int(a.debut))
        print(f"дебют скриптом до {a.debut} бойцов, модель подключится после", flush=True)
    # После NEW игра ГЕНЕРИРУЕТ карту, и первого состояния приходится ждать
    # дольше обычного такта. 13.09 на живой игре переход между эпизодами занял
    # больше 31 с, а здесь стояли жёсткие 30 — и исправная загрузка была
    # объявлена обрывом, с диагностикой про «игра свёрнута или на паузе».
    # Ждём столько же, сколько ждёт сам запуск партии, и говорим, чего ждём:
    # молчащее ожидание неотличимо от зависания.
    первое_ожидание = float(a.new_timeout) if (a.new or номер_эпизода > 1) else 30.0
    st = None
    _крайний = time.time() + первое_ожидание
    while st is None:
        _осталось = _крайний - time.time()
        if _осталось <= 0:
            break
        try:
            st = br.wait_state(timeout=min(15.0, max(1.0, _осталось)))
        except TimeoutError:
            if _крайний - time.time() > 0:
                print(f"жду первое состояние новой партии: прошло "
                      f"{int(первое_ожидание - (_крайний - time.time()))} с из "
                      f"{int(первое_ожидание)} (после NEW игра генерирует карту)",
                      flush=True)
    if st is None:
        # Партия могла кончиться ДО того, как мы к ней подключились: так бывает
        # в контейнере, где политика встаёт после игры. Спрашиваем игру, но
        # только про свежие файлы — замороженное состояние прошлой партии лежит
        # рядом и назвало бы её исход вместо нынешнего.
        исход = br.outcome(свежесть=30)
        if исход:
            return конец_партии(a, br, исход, br.raw.get("gametime", 0))
        if первое_ожидание > 30:
            print(f"новая партия не подала состояния за {int(первое_ожидание)} с "
                  f"после NEW. Если карта всё ещё грузится — поднимите "
                  f"--new-timeout")
        stalled(br.save_dir, plind, no_mode=a.no_mode)
        return "обрыв"
    # НА КАКОЙ СЕКУНДЕ мы подключились. Это первое, что решает, сравним ли
    # прогон с другими. 12.09 партию заводили руками: сначала игра и бой, потом
    # отдельной командой политика — и бот не существовал первые полторы минуты.
    # По трассе это выглядело как «бот полторы минуты ничего не строил», то есть
    # инструмент показывал артефакт запуска как поведение модели.
    старт_gt = int(st.get("gametime", 0) or 0)
    if старт_gt > ПОЗДНО:
        мм, сс = divmod(старт_gt, 60)
        print(f"\n{'!' * 60}\n"
              f"ПОДКЛЮЧИЛИСЬ К ИДУЩЕЙ ПАРТИИ: она уже на {мм}:{сс:02d}.\n"
              f"Всё это время бот не играл, а игра шла. С прогонами, начатыми\n"
              f"с нуля, этот НЕ СРАВНИМ: разница будет не про идею, а про то,\n"
              f"сколько партия прожила без бота.\n"
              f"Начинать партию и политику надо одной командой: `--new` здесь\n"
              f"или COSS3_EXPERIMENT в контейнере.\n"
              f"{'!' * 60}")
        if a.max_start and старт_gt > a.max_start:
            print(f"--max-start {a.max_start}: не играю на такой партии")
            return "поздно"
    первый = not globals().get("_ШАПКА")
    globals()["_ШАПКА"] = True
    print(f"слот P{plind}, модель {a.model}, решение раз в {a.every} игровых секунд")
    if первый:                               # это одно и то же каждый эпизод
        _h = load_hints(a.hints)
        _в_промпте = отобрать_подсказки(_h, st)
        print(f"подсказки из {a.hints}, читаются перед каждым решением")
        print(f"  файл {len(_h)} симв., в промпт идёт {len(_в_промпте)} "
              f"(~{len(_в_промпте) // 3} токенов): # и пройденные звенья отброшены")
        if отброшенные_метки:
            print(f"  ОТБРОШЕНЫ ПО ЗВЕНЬЯМ: {', '.join(sorted(отброшенные_метки))} — "
                  f"эти строки в промпт НЕ пойдут.\n"
                  f"  Осторожно с [экономика]: звено проходится при peasants>=15, "
                  f"а партия начинается с 18,\n"
                  f"  то есть такая подсказка не дойдёт до модели ни разу. "
                  f"Снимите метку, если она нужна всегда")
        _плохие = неизвестные_метки(_h)
        if _плохие:
            print(f"  ВНИМАНИЕ: метки не из звеньев — {', '.join(sorted(set(_плохие)))}."
                  f"\n  Такие строки видны всегда. Звенья: {', '.join(ЗВЕНЬЯ)}")
        if len(_в_промпте) > 2500:
            print("  великовато. Пометьте строки звеном — [кузница], [казарма],\n"
                  "  [армия], [волна], [экономика] — они исчезнут, когда звено пройдено.\n"
                  "  Устойчивые правила держите в SYSTEM или в policy.py")
    if первый and a.world:
        # Канал вопросов включён — сказать об этом вслух и показать, что уже
        # накоплено. Молчащий канал неотличим от выключенного, а цена ошибки
        # здесь высокая: модель потратит вопрос, а человек его не увидит.
        try:
            _сыр = open(a.world, encoding="utf-8").read()
        except OSError:
            _сыр = ""
            print(f"КАНАЛ ВОПРОСОВ: файла {a.world} ещё нет — будет создан "
                  f"первым же вопросом модели")
        _зн, _воп = разобрать_мир(_сыр)
        _отв = [1 for _, о in _воп if о]
        if _сыр:
            print(f"мир из {a.world}: {len(_зн)} строк знания, "
                  f"{len(_отв)} отвеченных вопросов, "
                  f"{len(_воп) - len(_отв)} открытых — всё идёт в промпт целиком")
        print(f"  модель может задать {a.questions} вопрос(а) за партию; "
              f"ответы писать строкой «  ответ: ...» под вопросом")
        if _зн and not any(m in " ".join(_зн) for m in ("[код]", "[игрок]", "[замер]")):
            print("  ВНИМАНИЕ: ни у одной строки нет метки источника "
                  "([код]/[игрок]/[замер]) — модель не отличит проверенное от слов")
    print()

    if a.max_commands != ПОЛИТИКА["команд_за_такт"]:
        _старое = ЧИСЛИТЕЛЬНОЕ[ПОЛИТИКА["команд_за_такт"]]
        _новое = ЧИСЛИТЕЛЬНОЕ.get(a.max_commands, str(a.max_commands))
        ПОЛИТИКА["команд_за_такт"] = a.max_commands
        globals()["SYSTEM"] = SYSTEM.replace(
            f"Не больше {_старое} команд.", f"Не больше {_новое} команд.")
        print(f"предел команд за такт: {a.max_commands} (умолчание 7). "
              f"Шестёрка до 16.09 пришла из первого коммита человеческого слота "
              f"и ничем не обоснована; в 33 тактах из 153 модель упиралась в неё")
    globals()["КРИТИК_ВПЕРЁД"] = bool(getattr(a, "critic_forward", False))
    if getattr(a, "critic_forward", False):
        print("гипотеза критика ВОЗВРАЩАЕТСЯ в следующую партию как задание на "
              "проверку (--critic-forward)")
    globals()["СХЕМОЙ"] = bool(a.schema)
    if a.schema:
        print("ответ по СХЕМЕ (нативный structured output): поля и команды "
              "описаны json-схемой, а не просьбой вернуть JSON.")
        print("  провайдер без схемы — мост скажет и доиграет по-старому "
              "(--no-schema — выключить заранее)")
    else:
        print("схема ответа не просится (умолчание): JSON просим словами, как "
              "играли base9-base11. Включить: --schema")
    globals()["ЧЕСТНО"] = bool(a.fair)
    if a.fair:
        print("честная игра: числа противника в запрос не идут, ПОКА карта "
              "закрыта. Открыта (монгольфьер всем, --balloon 2) — идут: там их "
              "видит и человек")
    else:
        print("открытая информация (умолчание с 18.09 по новым правилам хакатона): "
              "мост подсказывает модели всё, что знает о партии. С сериями до "
              "18.09 под --fair сравнивать нельзя")
    globals()["КАНАЛ_ВОПРОСОВ"] = bool(a.world)
    globals()["ВОПРОС_ЗАДАН"] = ""       # счёт на партию, не на прогон
    globals()["ОТРЕЗОК"] = max(0, int(a.stop_at))
    if ОТРЕЗОК:
        _м, _с = divmod(ОТРЕЗОК, 60)
        print(f"учебный отрезок: партия обрывается на {_м}:{_с:02d} и начинается "
              f"новая (цель прежняя, горизонт {a.horizon} не отменён)")
    globals()["WAVE_MIN"] = max(0, int(a.wave_min))
    globals()["ОКНО_ИСТОРИИ"] = max(0, int(a.history))
    if a.history != 5:
        print(f"окно истории: {a.history} прошлых ходов "
              f"(по умолчанию 5; 0 — не показывать; больше числа тактов = вся партия)")
    # Размер запроса — не мелочь: бюджет такта 20 секунд, и он тратится на
    # ожидание ответа. Замер 13.09: SYSTEM 16 159 символов (~5 400 токенов) и
    # уходит КАЖДЫЙ такт, обстановка при окне 5 — около 630 токенов, при полной
    # истории партии — около 2 570. То есть голова втрое тяжелее хвоста, и
    # спорить про размер истории, не зная этого, бессмысленно.
    # Разделы дописываем ДО замера. Раньше и человеческий раздел, и канал
    # вопросов приклеивались ниже, и строка называла размер, которого в запросе
    # не будет: 16 159 символов она показывала и с ними, и без них.
    if a.human and SYSTEM_HUMAN not in SYSTEM:
        globals()["SYSTEM"] = SYSTEM + SYSTEM_HUMAN
    if a.world and SYSTEM_QUESTION not in SYSTEM:
        globals()["SYSTEM"] = SYSTEM + SYSTEM_QUESTION
    print(f"SYSTEM: {len(SYSTEM)} симв. (~{len(SYSTEM)//3} токенов), "
          f"уходит в каждом запросе"
          + (" (+раздел человека)" if a.human else "")
          + (" (+канал вопросов)" if a.world else ""))
    globals()["ЧЕЛОВЕК"] = bool(a.human)
    print("порог волны снят 18.09: мост не отвергает ATTACK по числу, уйдёт столько, "
          "сколько просит модель и сколько свободно"
          + (f" (--wave-min {a.wave_min} принят и НЕ действует)" if a.wave_min else ""))
    if a.human:
        # На человеческом слоте выключать нечего: ProgressAI там не запускается
        # вовсе (progress.inc зовёт его только для bai или человека с советником).
        print("человеческий слот: нативного ИИ нет по построению, MODE не шлём")
        print("проверь в игре: свой слот ЧЕЛОВЕК, советник ВЫКЛЮЧЕН")
    elif not a.no_mode and br.send([mode(True, own_war=not a.native_war)]):
        # Не ждём wait_consumed: игра забирает файл на своём тике и без нас, а
        # ожидание стоило целого тика до первого решения.
        print("нативный билд-ордер выключен, ведёт модель")
        print("нативная атака " + ("ОСТАВЛЕНА: волны шлёт движок"
                                   if a.native_war else
                                   "выключена: волны идут только по команде ATTACK"))

    history: list[str] = []
    вопросов_задано = 0                  # один за партию: человек — узкое место
    дневник = Дневник() if a.memo else None
    ТРАССА_ПАРТИИ.clear()
    ВЕХА_УБИЙСТВО.clear()
    ГОЛОД_ВРАГА.clear()
    ПОТ_ВРАГА_БЫЛО.clear()
    ЧИСТО_НА_ВОЛНЕ.clear()
    УРОКИ_ПАРТИИ.clear()
    УДАР.clear()
    ОТПРАВКА.clear()
    НАКОПЛЕНИЕ.clear()
    STAGE_ЗА_ТАКТ.clear()
    ПОСЕВ.clear()
    РЕСУРСЫ_ИСТОРИЯ.clear()
    РЕСУРСЫ_РУК.clear()
    МАРШ.clear()
    ТЫЛ.clear()                # тыл стрелков живёт одну партию, как и марш
    НОМЕР_ПОХОДА[0] = 0
    ВТОРАЯ_КАЗАРМА.clear()
    ПОЛЕ.clear()
    # Критик живёт в main, а дневник — здесь; отдаём его наружу, чтобы разбор
    # видел ту же партию, а не собирал её заново из трассы.
    globals()["ПОСЛЕДНИЙ_ДНЕВНИК"] = дневник
    прошлый_мир = load_world(a.world)    # чтобы заметить ответ, данный на ходу
    next_call = 0
    # СОБЫТИЕ: (вид из ПОВОДОВ, данные). Предложение игрока 20.09: мост не
    # должен ждать своего такта, когда здание уже готово и стоит пустым. То же
    # верно и для крестьян, вставших после стройки. Ставится при чтении
    # состояния, снимается в момент вопроса.
    СОБЫТИЕ = None
    зданий_было: dict = {}
    стройка_была: dict = {}              # on_build прошлого чтения — для «рук»
    долг_простоя: dict = {}              # крестьяно-секунды простоя — второй повод «рук»
    запас_еды: dict = {}                 # еда прошлого чтения — повод «запас»
    отказ_денег: dict = {}               # отказ BUILD по деньгам — повод «докупка»
    base_enemy = None
    pending = None                       # (поток, коробка) с решением в работе
    # ВТОРОЙ СЛОТ — под СОБЫТИЯ (реестр ПОВОДЫ). До 21.09 слот был один, и событийный вопрос
    # ВЫТЕСНЯЛ такт: замер серии hire_channel — обычных тактов 32,8 на
    # партию против 47,6 у базы, минус 31 процент общих решений. Вопрос о
    # найме узкий и дешёвый (33 токена ответа против 233), ждать под него
    # такт незачем. ОТПРАВКА команд при этом остаётся в ОДНОМ потоке:
    # Bridge.send при гонке молча затирает чужую пачку, а молчаливый
    # отброс неотличим от бездействия.
    pending_событие = None
    ведёт_раш = a.fallback               # эталон раша, только если попросили
    волна_была = False                   # уходил ли хоть кто-то в атаку
    волны: list = []                     # (игровая секунда, сколько бойцов)
    чужая_волна: list = []               # сказали ли уже про волну прошлой партии
    # Первое состояние новой партии приходит с полем ПРОШЛОЙ: эпизод сменился,
    # а парсер br_hwave в игре — нет.
    снять_чужую_волну(st, волны, чужая_волна)
    сбоев_подряд = 0
    next_fb = 0
    next_alive = 0
    next_attack = 0                      # не гнать волны чаще, чем они доходят
    next_hire = 0                        # когда снова спросить «кого нанимать»
    next_hands = 0                       # не чаще ПАУЗА_РУК на вопрос «куда людей»
    снимок_когда: dict = {}              # когда последний раз писали снимок
    руки_порог = int(getattr(a, "free_hands", 0) or 0)
    запас_вкл = int(getattr(a, "restock", 0) or 0)
    докупка_вкл = int(getattr(a, "rebuy", 0) or 0)
    if докупка_вкл:
        print("вопрос «докладывать ли постройку»: когда игра отказала "
              "по деньгам, а теперь хватает")
    if запас_вкл:
        print(f"вопрос «какую пачку купить»: когда еда переходит "
              f"{ПОРОГ_ЕДЫ} снизу вверх")
    if руки_порог:
        print(f"вопрос «куда людей»: свободных {руки_порог} и больше, не чаще "
              f"раза в {ПАУЗА_РУК} с. ДВА повода: стройка кончилась, либо "
              f"простоя накопилось на {ДОЛГ_ПРОСТОЯ} крестьяно-секунд")
    найм_мин, найм_макс = срок_найма(getattr(a, "hire_every", 0))
    if найм_мин:
        print(f"вопрос о найме: каждые "
              + (f"{найм_мин} с" if найм_макс == найм_мин
                 else f"{найм_мин}-{найм_макс} с СЛУЧАЙНО")
              + " плюс на каждой достройке")
    сказано_про_403 = False
    было_st: dict | None = None          # состояние на миг прошлого решения
    прошлый_заказ: list = []             # что тогда заказали, для проверки
    расхождение: list[str] = []          # названо в тексте, но не отдано командой
    брак: list[str] = []                 # что мост не разобрал в прошлом ответе
    вето_волны = ""                      # волну отверг сам мост, а не игра
    вмешательство = ""                   # мост подменил команду — сказать модели
    повторы: dict = {}                   # сколько тактов подряд заказ не проходит
    прошлые_подсказки = ""               # чтобы заметить правку на ходу
    if ведёт_раш:
        print("до первого ответа модели строит эталон раша — игра не простаивает")
    t0, gt0 = time.time(), int(st.get("gametime", 0)) if st else 0
    паузы: list[float] = []              # реальные секунды между записями состояния
    прошлое_чтение = time.time()

    def темп_игры() -> None:
        """Как часто игра писала состояние. Цикл забирает готовый ответ только
        после свежей записи, поэтому её темп — нижняя граница запаздывания."""
        if len(паузы) > 2:
            п = sorted(паузы)
            print(f"игра писала состояние: медиана {п[len(п)//2]:.1f} с, "
                  f"худшая пауза {п[-1]:.1f} с, записей {len(п)}")

    # Первый вызов уходит сразу, на уже прочитанном состоянии: ожидание свежего
    # стоило ещё одного тика ИИ, то есть 2-5 секунд до первого решения.
    if st:
        gt_н = int(st.get("gametime", 0))
        next_call = gt_н + a.every
        прошлые_подсказки = load_hints(a.hints)
        коробка: dict = {"gt": gt_н, "t": time.time()}
        поток = threading.Thread(
            target=think_worker,
            args=(коробка, client, a.model,
                  situation(st, br.read_map() or {}, [], прошлые_подсказки,
                            None, [], a.allow_restart, мир=load_world(a.world)),
                  a.think, a.tries, a.spare),
            daemon=True)
        поток.start()
        pending = (поток, коробка)
        print(f"первый запрос ушёл на {gt_н} игровой секунде")
    slow_after = a.every / 1.38          # 1,38× — замер из HANDOFF, уточним по факту
    while True:
        try:
            st = br.wait_state(timeout=СТОП_ТИШИНЫ)
            снять_чужую_волну(st, волны, чужая_волна)
        except TimeoutError:
            # Состояние встало. Это НЕ повод гадать: у игры надо спросить.
            # Пульс интерфейса переживает паузу конца партии, а последняя
            # строка состояния успевает назвать исход в большинстве случаев.
            исход = br.outcome()
            if исход:
                return конец_партии(a, br, исход, br.raw.get("gametime", 0))
            # d здесь не существует: каталог знает только мост. Из-за этого
            # диагностика конца партии падала NameError поверх TimeoutError.
            stalled(br.save_dir, plind, no_mode=a.no_mode)
            return "обрыв"
        _т = time.time()
        паузы.append(_т - прошлое_чтение)
        прошлое_чтение = _т
        # ЗДАНИЕ ДОСТРОИЛОСЬ — БУДИМ МОДЕЛЬ СРАЗУ. Кующие бойцов здания сюда
        # и попадают: казарма и конюшня. Считаем по числу зданий в состоянии —
        # оно растёт в тот такт, когда стройка кончилась.
        # Снимок пишется ДО разбора поводов: он должен быть у нас, даже если
        # такт кончится обрывом или партия оборвётся на следующем чтении.
        писать_снимок(a, st, снимок_когда)
        _достроено = достройка_здания(st, зданий_было)
        if _достроено:
            СОБЫТИЕ = ("найм", _достроено)
        # СТРОЙКА КОНЧИЛАСЬ — ЛЮДИ ВСТАЛИ. Второй повод, заведён 21.09 по
        # [замеру] 9 партий base24: свободные крестьяне есть в 44-49 тактах из
        # 49-53, и это 12,8 процента всего их труда впустую. Ловим переход
        # `on_build` в ноль (5-6 раз за партию, медиана 5 человек), а не сам
        # простой: тот срабатывал бы 24 раза за партию и был бы вторым тактом,
        # а не событием. Найм важнее: если оба повода пришли разом, руки ждут
        # следующего чтения состояния — здание простаивает дороже.
        if руки_порог:
            # Наполняем историю прихода КАЖДОЕ чтение, а не в момент вопроса:
            # к событию окно 20-90 с должно быть готово. При выключенном ключе
            # не делаем и этого — тогда мост побайтно повторяет базу.
            чистый_приход(st, РЕСУРСЫ_РУК, 150)
        if not СОБЫТИЕ and руки_порог:
            # ДВА СПОСОБА, и оба нужны. Переход `on_build` в ноль ловит руки,
            # освободившиеся ПАЧКОЙ после стройки. Долг простоя ловит то, чего
            # переход не видит вовсе: крестьян, рождённых в ратуше сразу
            # свободными. 21.09 игрок увидел глазами провал в 604 игровых
            # секунды при 27 свободных — переходов там не случилось ни одного.
            _руки = руки_освободились(st, стройка_была, руки_порог)
            _долгом = False
            if not _руки:
                _руки = простой_накопился(st, долг_простоя, руки_порог,
                                          ДОЛГ_ПРОСТОЯ)
                _долгом = bool(_руки)
            else:
                # Переход считаем и по долгу тоже, иначе его секунды пропадут.
                простой_накопился(st, долг_простоя, руки_порог, ДОЛГ_ПРОСТОЯ)
            if _руки and _чис(st.get("gametime")) >= next_hands:
                next_hands = _чис(st.get("gametime")) + ПАУЗА_РУК
                сбросить_долг(долг_простоя)      # гасит ЛЮБОЙ вопрос про руки
                СОБЫТИЕ = ("руки", _руки)
                if _долгом:
                    print(f"        (руки по ДОЛГУ простоя, не по достройке)")
        else:
            руки_освободились(st, стройка_была, 0)   # счётчики ведём всегда
            простой_накопился(st, долг_простоя, 0, 0)
        # ДЕНЕГ ХВАТИЛО НА ТО, В ЧЁМ ОТКАЗАЛИ. Четвёртый повод, заведён 21.09
        # по наблюдению игрока «ресурсы есть, а вторую казарму не ставит».
        # Разбор живой партии: на 533 с заказ при золоте 2184 и цене 2500, игра
        # отказала, мост честно сказал это полем last_fail; к 565 с золота стало
        # 2698, и никто не вернулся. Ставим ПЕРВЫМ среди поводов: упущенная
        # постройка дороже и найма, и перестановки людей. Память ведём ВСЕГДА,
        # иначе отказ, случившийся при занятом событии, потеряется.
        _докупка = отказ_по_деньгам(st, отказ_денег, докупка_вкл)
        if not СОБЫТИЕ and _докупка:
            СОБЫТИЕ = ("докупка", _докупка)
        # ЕДА ВЕРНУЛАСЬ — МОЖНО КУПИТЬ ПАЧКУ ЧИСЛОМ. Третий повод, заведён
        # 21.09 по находке того же дня: конечный заказ платит ВПЕРЁД за всю
        # пачку и переживает следующее падение, бесконечный платит поштучно и
        # встаёт. [замер] 9 партий base24: модель отдала 191 бесконечный приказ
        # и НИ ОДНОГО конечного. Счётчик ведём ВСЕГДА, иначе первый же переход
        # после чужого события потеряется.
        _вернулась = еда_вернулась(st, запас_еды, запас_вкл)
        if not СОБЫТИЕ and _вернулась:
            СОБЫТИЕ = ("запас", _вернулась)
        # СОСТАВ ВРАГА МЕНЯЕТСЯ БЫСТРЕЕ, ЧЕМ ИДЁТ ТАКТ. Замысел игрока 21.09:
        # здание достроилось, модель назвала вид — а через полминуты у врага
        # другой состав, и нужен другой боец. Обычный такт идёт раз в 20 с и
        # занят всем сразу; узкий вопрос стоит доли секунды, и его можно
        # задавать чаще. Спрашиваем про здание, которое СЕЙЧАС ПУСТО, — ему
        # ответ нужнее всего; если пустых нет, про первое своего вида, чтобы
        # можно было сменить состав на ходу.
        if найм_мин and not СОБЫТИЕ and _чис(st.get("gametime")) >= next_hire:
            _пауза = следующий_найм(найм_мин, найм_макс)
            next_hire = _чис(st.get("gametime")) + _пауза
            _кого = кого_спросить_по_сроку(st)
            if _кого:
                СОБЫТИЕ = ("найм", _кого)
        gt = int(st.get("gametime", 0))
        # Исход приходит той же строкой состояния, что и всё остальное. Ждать
        # тридцатисекундного обрыва, чтобы узнать о поражении, незачем.
        if st.get("victory") in ("win", "lose"):
            return конец_партии(a, br, str(st["victory"]), gt)
        mp = br.read_map()
        # Марш по контракту модели живёт МЕЖДУ её решениями: такт 20 игровых
        # секунд плюс ответ модели, а сбор и удар надо вести каждый такт.
        шаг_марша(st, br, gt, волны, дневник)
        if int(st.get("my_agressors", 0) or 0) > 0:
            волна_была = True
        # ГОЛОД ВРАГА ОТДЕЛЯЕТСЯ ОТ НАШЕГО УДАРА (24.09). Раз в такт и ДО счёта
        # вехи: прирост pea_lost, случившийся при нулевой еде врага, — не наша
        # работа, и в счёт не идёт. Молчаливо не отбрасываем: каждый такой
        # случай называется вслух, иначе исчезнувшие смерти не с чем свести.
        _пв = поле_врага(st, mp, "pea_lost")
        try:
            _пв = int(float(_пв)) if _пв is not None else None
        except (TypeError, ValueError):
            _пв = None
        if _пв is not None:
            _еда_вр = поле_врага(st, mp, "food")
            try:
                _еда_вр = int(float(_еда_вр)) if _еда_вр is not None else None
            except (TypeError, ValueError):
                _еда_вр = None
            _прирост = _пв - (ПОТ_ВРАГА_БЫЛО[0] if ПОТ_ВРАГА_БЫЛО else 0)
            if _прирост > 0 and _еда_вр == 0:
                if not ГОЛОД_ВРАГА:
                    ГОЛОД_ВРАГА.append(0)
                ГОЛОД_ВРАГА[0] += _прирост
                _мм, _сс = divmod(gt, 60)
                print(f"  {_мм}:{_сс:02d}  у врага кончилась еда: крестьян "
                      f"погибло {_прирост} С ГОЛОДУ (всего голодных "
                      f"{ГОЛОД_ВРАГА[0]}) — это не наш удар, в веху и в счёт "
                      f"убитых не идёт")
            if ПОТ_ВРАГА_БЫЛО:
                ПОТ_ВРАГА_БЫЛО[0] = _пв
            else:
                ПОТ_ВРАГА_БЫЛО.append(_пв)
        # Миг ухода первой волны: с него и считается НАШ счёт, а не с начала
        # партии. Без этого голодные смерти четвёртой минуты становились вехой
        # ровно тогда, когда уходила волна, — дошла она или нет.
        if волна_была and not ЧИСТО_НА_ВОЛНЕ:
            ЧИСТО_НА_ВОЛНЕ.append(max(0, (ПОТ_ВРАГА_БЫЛО[0] if ПОТ_ВРАГА_БЫЛО else 0)
                                      - (ГОЛОД_ВРАГА[0] if ГОЛОД_ВРАГА else 0)))
        for p in range(8):
            # Человеческий блок кладёт крестьян врага прямо в состояние: файла
            # карты он не пишет, вся картина собирается одним проходом.
            _ист = mp if f"p{p}_peasants" in mp else st
            if st.get(f"p{p}_enemy") and f"p{p}_peasants" in _ист:
                en = int(_ист[f"p{p}_peasants"])
                # Сравниваем с ПРОШЛЫМ значением, а не с начальным.
                #
                # 13.09: прежняя проверка держала base_enemy = первое
                # увиденное число (18) и требовала упасть НИЖЕ него. Враг при
                # этом растёт до 55, и чтобы мост заметил ОДНОГО убитого,
                # пришлось бы убить тридцать семь. Разбор семи прогонов: в пяти
                # из них крестьяне врага падали после наших волн — 54->51,
                # 58->55, 54->47->44, 56->52, 56->53 — и каждый раз мост
                # отрапортовал «цель не взята».
                #
                # То есть бот брал цель, а инструмент этого не видел. Хуже
                # молчания: он говорил обратное.
                # ПОБЕДА: у противника не осталось крестьян. Это и есть цель
                # эпизода с 17.09. Движок засчитывает выбывание, когда у игрока
                # нет ни ратуши, ни ЗАНЯТЫХ ЖИЛЫХ МЕСТ (progress.inc:130), а
                # занимают их люди — значит ноль крестьян это та же черта,
                # только видимая нам числом в состоянии.
                # ВЕХА ПО СЧЁТУ ДВИЖКА (20.09). Поле p<n>_pea_lost — сколько
                # его крестьян погибло (gPlayer[pl].stat.killed, захват
                # исключён). Пока его нет в состоянии (старый блок), работает
                # прежнее правило по падению счётчика ниже.
                _пот = поле_врага(st, mp, "pea_lost")
                if _пот is not None:
                    try:
                        _пот = int(float(_пот))
                    except (TypeError, ValueError):
                        _пот = 0
                    # ПРИРОСТ ПОСЛЕ УХОДА ВОЛНЫ И БЕЗ ГОЛОДА (24.09). Прежде
                    # здесь стояло `_пот > 0`, то есть НАКОПЛЕННЫЙ итог с
                    # начала партии: голодные смерти четвёртой минуты
                    # объявлялись вехой в тот миг, когда уходила первая волна,
                    # в любой партии, дошла она или нет.
                    _голод = ГОЛОД_ВРАГА[0] if ГОЛОД_ВРАГА else 0
                    _чисто = max(0, _пот - _голод)
                    _порог = ЧИСТО_НА_ВОЛНЕ[0] if ЧИСТО_НА_ВОЛНЕ else 0
                    if _чисто > _порог and волна_была and not ВЕХА_УБИЙСТВО:
                        ВЕХА_УБИЙСТВО.append(gt)
                        mm, ss = divmod(gt, 60)
                        print(f"\n{mm}:{ss:02d}  ВЕХА (счёт движка): у врага "
                              f"погибло крестьян {_чисто - _порог} ПОСЛЕ ухода "
                              f"волны и не с голоду (всего по счёту {_пот}, из "
                              f"них с голоду {_голод}). Партия идёт до нуля "
                              f"крестьян у врага")
                if en == 0 and волна_была:
                    mm, ss = divmod(gt, 60)
                    print()
                    темп_игры()
                    print(f"ПОБЕДА на {mm}:{ss:02d}: у противника НОЛЬ крестьян")
                    отметить_конец(a, st, gt, "победа")
                    return "победа"
                if base_enemy is None:
                    base_enemy = en
                elif en < base_enemy and _пот is None:
                    mm, ss = divmod(gt, 60)
                    if not волна_была:
                        # 11.09.2026: партия без единого бойца и без единой
                        # ATTACK отрапортовала «цель достигнута». Крестьяне у
                        # врага убывают и сами по себе, так что падение счётчика
                        # без нашей волны — не результат, а совпадение.
                        print(f"\n{mm}:{ss:02d}  у врага стало меньше крестьян "
                              f"({base_enemy} -> {en}), НО МЫ НИКОГО НЕ ПОСЫЛАЛИ "
                              f"— это не наша заслуга, партия продолжается")
                        base_enemy = en
                        continue
                    # ВЕХА, А НЕ КОНЕЦ. С 17.09 цель эпизода — ВЫИГРАТЬ партию,
                    # то есть довести крестьян врага до нуля. Убитый крестьянин
                    # показывает, что волна дошла и способна убивать, — партия
                    # после этого ПРОДОЛЖАЕТСЯ. До 17.09 мост обрывал её здесь,
                    # и по 43 волнам base14 нельзя было сказать ничего о том,
                    # что бывает дальше: данных за пределом первой убыли не было.
                    if not ВЕХА_УБИЙСТВО:
                        ВЕХА_УБИЙСТВО.append(gt)
                        print(f"\n{mm}:{ss:02d}  ВЕХА: волна дошла и убила "
                              f"крестьянина ({base_enemy} -> {en}). Это не конец: "
                              f"партия идёт до нуля крестьян у врага")
                    base_enemy = en
                else:
                    # Враг вырос — запоминаем новое число. Без этого сравнение
                    # навсегда остаётся привязанным к старту.
                    base_enemy = en
        el = time.time() - t0
        if el > 60 and gt > gt0:
            slow_after = a.every * el / (gt - gt0)

        # Модель думает в фоне. Пока она думает, цикл продолжает читать
        # СОБЫТИЕ ДУМАЕТ ОДНОВРЕМЕННО С ТАКТОМ, а не вместо него. Свой слот,
        # своя модель, свой системный текст. Какой именно — знает реестр
        # ПОВОДЫ: здесь второй и любой следующий повод не добавляют ни ветки.
        # Полный situation() для события не строится вовсе.
        # ПОКА ИДЁТ ДЕБЮТ, МОДЕЛЬ НЕ ЗОВЁМ ВОВСЕ — ни тактом, ни событием.
        # 21.09, найдено живой игрой при слиянии: блок события стоит ВЫШЕ
        # перехвата дебюта, поэтому событие успевало поднять запрос и запустить
        # поток, а `continue` дебюта пропускал разбор. Ответ выбрасывался,
        # токены тратились впустую, и трасса при этом оставалась пустой — по
        # ней defect был невидим. Событие не теряется: СОБЫТИЕ остаётся
        # взведённым и сработает первым же тактом после передачи хода.
        _дебют_ведёт = дебют is not None and not дебют.передан
        if СОБЫТИЕ and pending_событие is None and not _дебют_ведёт:
            _вид, _данные = СОБЫТИЕ
            СОБЫТИЕ = None
            _повод = ПОВОДЫ[_вид]
            box_н: dict = {"gt": gt, "t": time.time(),
                           "событие": _повод["метка"](_данные), "повод": _вид}
            box_н["prompt"] = _повод["запрос"](st, mp, _данные, a.every)
            # ЛЮБОЙ повод, а не только найм: все они узкие и дешёвые, и
            # локальные модели отвечают на них верно СО СХЕМОЙ — 13 из 13 на
            # найме, 21 из 21 на руках (bench_hire.py, bench_hands.py).
            _кл = getattr(a, "_client_событий", None) or client
            _мд = getattr(a, "_модель_событий", "") or a.model
            # Запасной облачной у локального события нет: см. --event-model.
            _зп = "" if getattr(a, "_client_событий", None) else a.spare
            # ЗАПАСНОЕ ОБЛАКО ДЛЯ ЛОКАЛЬНОГО СОБЫТИЯ. До 23.09 запасного не
            # было вовсе: ollama на маке дважды переставала слушать порт, и
            # повод пропадал молча. Теперь при отказе локальной вопрос уходит
            # облаком, а трасса хранит, КТО ответил (поле model), — чтобы при
            # разборе было видно, сколько событий прошло не тем путём.
            _зпк = ((client, a.model)
                    if getattr(a, "_client_событий", None) else None)
            # СХЕМА — ТОЛЬКО ЛОКАЛЬНОЙ МОДЕЛИ. Облачные события идут как в
            # base25, иначе у любого плеча появилась бы вторая разница и база
            # снова стала бы негодной — ровно как погиб base24. Локальной же
            # схема нужна: без неё она выдумывает поля и имена (замер 22.09).
            _сх = (_повод["схема"](st, _данные)
                   if getattr(a, "_client_событий", None) else None)
            print(f"        СОБЫТИЕ: {_повод['словами'](_данные)} "
                  f"(параллельно такту{', со схемой' if _сх else ''})")
            # Выключатель думания идёт ровно там же, где схема: у локального
            # клиента. Думающая модель без него отвечает ПУСТО за 48 с, и в
            # трассе это неотличимо от молчания.
            _ус = (getattr(a, "_усилие_событий", "")
                   if getattr(a, "_client_событий", None) else "")
            th_н = threading.Thread(
                target=think_worker,
                args=(box_н, _кл, _мд, box_н["prompt"], a.think,
                      a.tries, _зп, _повод["system"](), _сх, _ус, _зпк),
                daemon=True)
            th_н.start()
            pending_событие = (th_н, box_н)

        # состояние и следить за целью — иначе задержка тира ослепляет нас
        # на минуты, а она гуляет от 3 до 240 с и не лечится выбором модели.
        # ДЕБЮТ СКРИПТОМ (20.09). Пока бойцов меньше N, команды даёт debut.py
        # на каждом обновлении состояния, модель молчит. Неполное чтение
        # состояния (файл ещё дописывается, ключа victory нет) пропускаем:
        # на нём очередь казармы читается пустой, и заказ ушёл бы дважды.
        if дебют is not None and not дебют.передан:
            if "victory" not in st:
                continue
            if not дебют.готов(st):
                _дк, _дс = дебют.такт(st, gt)
                if _дк and br.send(_дк):
                    for _с in _дс:
                        print(f"     дебют {gt} с: {_с}", flush=True)
                continue
            дебют.передан = True
            _отч = дебют.отчёт(st)
            print(f"\n{_отч}", flush=True)
            ДОПИСКИ.append(_отч)          # с этого запроса и до конца партии
            next_call = gt                # модель — с этого же такта
        if pending is None and gt >= next_call:
            next_call = gt + a.every
            box: dict = {"gt": gt, "t": time.time()}
            подсказки = load_hints(a.hints)
            if подсказки != прошлые_подсказки:
                if прошлые_подсказки:
                    print(f"        подсказки изменились ({len(подсказки)} симв.) — "
                          f"учтены с этого решения")
                прошлые_подсказки = подсказки
            мир_текст = load_world(a.world)
            if a.world and мир_текст != прошлый_мир:
                if прошлый_мир:
                    print(f"        мир изменился ({len(мир_текст)} симв.) — "
                          f"учтён с этого решения")
                прошлый_мир = мир_текст
            prompt = situation(st, mp, history, подсказки,
                               было_st, прошлый_заказ, a.allow_restart,
                               расхождение, повторы, брак, волны, вето_волны,
                               вмешательство, мир=мир_текст,
                               дневник=дневник.строки() if дневник else None)
            # События сюда больше не попадают — с 21.09 у них СВОЙ слот
            # выше, и обычный такт ими не вытесняется. Чем спрашивать и
            # как разбирать ответ, знает реестр ПОВОДЫ.
            # Кладём запрос в коробку: ответ приходит асинхронно, и к моменту
            # записи трассы контекст такта уже сменился. Без этого в трассе
            # осталось бы решение без обстановки, из которой оно выросло.
            box["prompt"] = prompt
            # Что мост подменил в ПРОШЛОЙ отправке (урезание BALANCE и
            # прочее) уходит модели в этом запросе — кладём в коробку, чтобы
            # оно попало и в трассу. 22.09 счёт «урезано 0 из 440» оказался
            # ложным нулём: текст жил только в промпте, и частота перезапроса
            # людей была неизмерима, хотя модель цитировала его в уроках.
            box["вмешательство"] = вмешательство
            if a.dump_prompt:
                try:
                    # дописываем, а не перезаписываем: при --replay нужен весь
                    # ряд запросов, чтобы видеть, как блоки меняются по тактам.
                    # Файл обнуляется один раз при запуске, в main().
                    with open(a.dump_prompt, "a", encoding="utf-8") as f:
                        f.write(f"\n\n# решение на {gt} игровой секунде\n\n")
                        f.write("### SYSTEM\n" + SYSTEM + "\n\n### ЗАПРОС\n" + prompt)
                except OSError:
                    pass                    # диагностика не должна ронять партию
            # КУДА спрашиваем. Узкий вопрос о найме можно увести в другую
            # модель (--hire-model / --hire-base-url): он не требует ни мира,
            # ни истории, и локальные отвечают на него верно СО СХЕМОЙ. Запасной
            # модели у него нет НАРОЧНО: `spare` держит очередь облачных, а если
            # локальная молчит, честнее пропустить найм, чем тихо уехать в
            # облако и сжечь токены, которых мы и хотели избежать.
            th = threading.Thread(target=think_worker,
                                  args=(box, client, a.model, prompt, a.think,
                                        a.tries, a.spare, ""),
                                  daemon=True)
            th.start()
            pending = (th, box)

        # Пока модель молчит, игра не должна стоять: держим цели эталона раша.
        # Команды декларативные, так что перехват модели ничего не ломает.
        if ведёт_раш and gt >= next_fb:
            next_fb = gt + 10
            фб = rush_plan(st, a.wave, minimal=True)
            if фб and br.send(фб):
                br.wait_consumed(timeout=15)
            # Раш молчалив, и без этой строки лог выглядит мёртвым, хотя
            # партия идёт. Раз в минуту показываем, что мы живы.
            if gt >= next_alive:
                next_alive = gt + 60
                mm, ss = divmod(gt, 60)
                цепь = " ".join(("+" if ok else "-") + n for n, ok, _ in stages(st))
                кто = "раш" if фб else "раш (целей нет)"
                print(f"{mm}:{ss:02d}  [{кто}] {цепь}")

        # ЗА ПРОХОД РАЗБИРАЕТСЯ ОДИН ОТВЕТ. Харвест ниже шлёт команды, а две
        # пачки подряд игра не заберёт: Bridge.send вернёт False и вторая
        # пропала бы молча.
        #
        # РАЗБИРАЕТСЯ ТОТ, КТО ДОЛЬШЕ ЖДЁТ. Сперва стояло «найм первым» — он
        # дешевле и быстрее. На моке это заморило такт голодом: при
        # --hire-every 10-25 событие готово почти всегда, такт ждал очереди, и
        # его решение применялось к обстановке на 274 игровых секунды новее
        # той, из которой выросло (9 нарушений порядка gt на 62 записи).
        # Порядок по времени запроса лечит это без перекосов в другую сторону.
        _готовы = [(с[1]["t"], имя, с) for имя, с in
                   (("найм", pending_событие), ("такт", pending))
                   if с is not None and not с[0].is_alive()]
        if not _готовы:
            continue                        # решение ещё готовится — не ждём
        _готовы.sort(key=lambda x: x[0])    # меньше t — раньше попросили
        _кто, (_, box) = _готовы[0][1], _готовы[0][2]
        if _кто == "найм":
            pending_событие = None
        else:
            pending = None
        wait = time.time() - box["t"]
        if "err" in box:
            if REPLAY and _REPLAY_I >= len(REPLAY):
                # Реплей кончился — эпизод окончен. По горизонту это не поймать:
                # у мока игровое время своё и с нуля не начинается.
                print()
                темп_игры()
                print(f"ответы для --replay кончились ({len(REPLAY)}) — эпизод окончен")
                return "реплей"
            сбоев_подряд += 1
            print(f"модель не ответила за {wait:.0f} с:")
            for стр in box.get("log", []):
                print(f"        {стр}")
            текст = str(box["err"])
            if "402" in текст or "insufficient" in текст.lower():
                print("        ДЕНЬГИ КОНЧИЛИСЬ на счету провайдера (402). Ни один\n"
                      "        вызов не пройдёт, партия доиграется вслепую.\n"
                      "        Пополнить: openrouter.ai/credits, проверить остаток:\n"
                      "        python llm_policy.py --credits")
            if ("403" in текст or "401" in текст) and not сказано_про_403:
                сказано_про_403 = True
                if "rate-limited" in текст or "429" in текст:
                    print("        провайдер держит лимит на эту модель. Свой ключ\n"
                          "        провайдера даёт собственные лимиты:\n"
                          "        openrouter.ai/settings/integrations")
                elif "unsupported_country" in текст:
                    print("        провайдер не обслуживает регион — исключён,\n"
                          "        следующие запросы пойдут мимо него")
                else:
                    print("        403/401 — проверьте баланс openrouter.ai/credits\n"
                          "        и настройки openrouter.ai/settings/privacy")
            if сбоев_подряд >= 2 and not ведёт_раш and a.fallback:
                ведёт_раш = True
                print("        два сбоя подряд — за пульт эталон раша, партия идёт")
            if сбоев_подряд == 5:
                print("        пять сбоёв подряд: модель фактически недоступна,\n"
                      "        дальше играет раш. Прервать — Ctrl+C")
            continue
        сбоев_подряд = 0
        подхват = ведёт_раш
        ведёт_раш = False
        # Имена апгрейдов берём из состояния: список зависит от нации и
        # приходит в поле upg_avail как «eurmil.1=food+140,...».
        _дост = {x.split("=", 1)[0].strip()
                 for x in str(st.get("upg_avail", "") or "").split(",")
                 if x.strip()}
        # ОТВЕТ НА СОБЫТИЙНЫЙ ВОПРОС приходит в своей, короткой схеме — у
        # найма {"role": ..., "total": ...}, у рук {"куда": ..., "сколько": ...}.
        # Переводит его в обычные команды сам повод, чтобы дальше по коду не
        # плодить второй путь разбора.
        if box.get("повод") and isinstance(box.get("data"), dict):
            _перевод = ПОВОДЫ[box["повод"]]["ответ"](box["data"], st)
            if _перевод is not None:
                box["data"] = _перевод
                # Мост ничего не сделал — говорим вслух и с причиной. Молчаливый
                # отброс неотличим от бездействия (правило 1 проекта).
                if not _перевод.get("commands"):
                    print(f'        СОБЫТИЕ: мост никого не тронул — '
                          f'{str(_перевод.get("why", ""))[:70]}')
        (cmds, attack, why, брак, цель_атаки,
         движение, цель_движения, клетка, контракт,
         кем_атака, кем_движение) = to_commands(box["data"], _дост,
                                                взятые_апгрейды(st),
                                                из_события=bool(box.get("событие")),
                                                st=st)
        # Снимок того, что попросила МОДЕЛЬ, до того как мост добавит своё.
        # Ниже досылка накопления кладёт в `движение` своё число и цель, и
        # после неё приказ модели от вмешательства моста не отличить.
        # 20.09: MOVE, RETREAT и `who` в трассу не писались вовсе, и по ней
        # выходило «модель их не отдаёт». Для RETREAT это оказалось неправдой:
        # в `assess_local` он отдан не меньше 13 раз, и видно это только в
        # логе, который обрезан до последних 400 строк. Принятие команды надо
        # считать по трассе, а не по обрезку лога.
        _просила = {"move": ((int(движение), str(цель_движения),
                              str(кем_движение or "")) if движение else None),
                    "who_attack": str(кем_атака or "")}
        # Заниженная волна. Считаем ЗДЕСЬ, а не у отправки ниже: трасса такта
        # пишется раньше отправки, и вето, посчитанное позже, в неё не попало бы
        # — а именно по трассе потом разбирают партию.
        #
        # Порога накопления НЕТ: мост не держит волну, когда бойцов мало (вето
        # в этом проекте уже съедало волны — 11.09 так пропали все 15 команд
        # ATTACK). Порог «меньше 20 не волна» (12.09-18.09) СНЯТ 18.09: он
        # отвергал приказ модели по числу оператора, а это нарушает правило
        # «управление через модель». 18.09 он же отверг отпор восьмерыми у
        # своей ратуши. Число волны — решение модели; знание о цене горстки
        # осталось в запросе и подсказках. Переменная вето_волны оставлена
        # пустой: её читают трасса и запрос.
        вето_волны = ""
        вмешательство = ""
        # Пока ратуши нет — потолок строителей ставит МОСТ, а не модель.
        # Проверяется идея игрока от 13.09: партия начинается БЕЗ ратуши
        # (centers=0, замерено по трассе), а бот ставил её тремя строителями из
        # восемнадцати, хотя в котлован влезает двенадцать (wip='center/12').
        # Всё это время остальные рубили дерево, которое некуда сдавать.
        #
        # Почему потолок, а не приказ строить: BUILDERS действует на КАЖДУЮ
        # НОВУЮ стройку, поднимать его после закладки бесполезно. Значит поднять
        # надо ДО того, как модель закажет ратушу, — то есть с первого такта.
        принуждение = ""

        def сказать(текст: str) -> None:
            """Мост вмешался — записать это, НЕ СТИРАЯ прежнего.

            До 20.09 четыре места писали `вмешательство = принуждение = ...`,
            и второе за такт стирало первое: накопление затирало прицел,
            авто-еда затирала накопление. Та же ошибка, что чинилась 18.09 у
            отказов такта, и с тем же следствием — модель видела одно
            вмешательство из двух, а в трассе оставалось одно из двух.
            """
            nonlocal вмешательство, принуждение
            вмешательство = (вмешательство + "; " if вмешательство else "") + текст
            принуждение = (принуждение + "; " if принуждение else "") + текст

        # ПРИЦЕЛ. Цель партии - крестьяне врага, а base и army ведут волну к
        # ЗДАНИЮ: block_hcmd.inc:970, `if (hatrg <> 'peasants') and (haeb)`.
        # Модель это знает - 17.09 промпту добавили прямую фразу, - и всё равно
        # шлёт подкрепления к постройке: доля приказов по крестьянам выросла с 6
        # процентов лишь до 9. Здесь мост правит цель и говорит об этом вслух,
        # чтобы модель видела подмену, а не гадала.
        if getattr(a, "aim_peasants", False) and attack and цель_атаки in ("base", "army"):
            было_цель = цель_атаки
            цель_атаки = "peasants"
            сказать(
                f"ATTACK {attack} -> {было_цель} ПЕРЕВЕДЁН МОСТОМ на peasants: "
                f"{было_цель} ведёт бойцов к ЗДАНИЮ, а победа считается по "
                f"крестьянам врага. Отключается ключом --aim-peasants")
        # НАКОПЛЕНИЕ: досылаем свежих в стоячую клетку сбора. Приказ STAGE
        # держится, пока его не отменят, и каждый такт мост отправляет тех, кто
        # освободился с прошлого раза. Ради этого всё и затевалось: MOVE уводит
        # только тех, кто свободен СЕЙЧАС, а выкованные следом оставались дома.
        #
        # НЕ ТРОГАЕМ, если модель в этот же такт отдала свой ATTACK или MOVE:
        # её приказ старше нашего, и дёргать одних и тех же бойцов дважды за
        # такт значит водить их по кругу (та же причина, по которой BALANCE
        # одной пачки делит людей).
        if (НАКОПЛЕНИЕ and not attack
                and not any(c.cmd in ("ATTACK", "MOVE", "RETREAT") for c in cmds)):
            _своб = _чис(st.get("my_freewar"))
            _надо = _своб - int(НАКОПЛЕНИЕ.get("keep") or 0)
            if _надо > 0:
                движение = max(движение, _надо)
                цель_движения = "cell"
                клетка = (НАКОПЛЕНИЕ["cx"], НАКОПЛЕНИЕ["cy"])
                кем_движение = НАКОПЛЕНИЕ.get("who") or кем_движение
                сказать(
                    f"НАКОПЛЕНИЕ: {_надо} свободных отправлены МОСТОМ в клетку "
                    f"сбора ({НАКОПЛЕНИЕ['cx']},{НАКОПЛЕНИЕ['cy']}), дома "
                    f"оставлено {НАКОПЛЕНИЕ.get('keep') or 0}. Так велел твой "
                    f"STAGE; отменяется командой {{\"cmd\":\"STAGE\",\"off\":1}}")
        if a.builders_first and int(st.get("centers", 0) or 0) == 0:
            было = next((c for c in cmds if c.cmd == "BUILDERS"), None)
            if not было or было.a1 != a.builders_first:
                cmds = [c for c in cmds if c.cmd != "BUILDERS"]
                # ПЕРВОЙ в списке, а не последней: блок команд исполняет их по
                # порядку, и потолок, поставленный после BUILD, применился бы
                # только к следующей стройке — то есть ровно не к той ратуше,
                # ради которой всё и затевалось.
                cmds.insert(0, builders(a.builders_first))
                сказать(
                    f"BUILDERS {a.builders_first} ПОСТАВЛЕН МОСТОМ вместо "
                    f"{('BUILDERS ' + str(было.a1)) if было else 'ничего'}: "
                    f"ратуши ещё нет (centers=0), и до неё потолок строителей "
                    f"держит мост. Отключается ключом --builders-first 0")

        # ПОЛЕ СОЗРЕЛО, А ЛЮДЕЙ НЕТ — мост сажает их сам. Случай узкий и
        # однозначный: поле готово, на еде НОЛЬ, и запас уже ниже порога найма,
        # то есть производство встало целиком. 19.09 такое поле простояло ТРИ
        # МИНУТЫ (готовых участков 25), модель повторяла «поле зреет» и слала
        # людей на дерево — партия умерла от голода, хотя мост писал «## Поле
        # СОЗРЕЛО, ставь людей прямо сейчас».
        #
        # Берётся ПОЛОВИНА крестьян, а не все: BALANCE перераспределяет и
        # занятых (замер 17.09 — «команда досылает недостающих»), и снять всех
        # с дерева значило бы остановить стройку. Больше готовых участков тоже
        # не берём — лишним там делать нечего.
        if getattr(a, "auto_food", 1) and not any(
                c.cmd == "BALANCE" and c.a1 == RESOURCE["food"] for c in cmds):
            _гот = _чис(st.get("food_ready"))
            _мельниц = _чис(st.get("mills"))
            _на_еде = _чис(st.get("on_food"))
            _еда = _чис(st.get("food"))
            _крестьян = _чис(st.get("peasants"))
            if (_мельниц > 0 and _гот > 0 and _на_еде == 0
                    and 0 < _еда < 500 and _крестьян > 0):
                _сколько = max(1, min(_гот, _крестьян // 2))
                cmds.insert(0, balance("food", _сколько))
                сказать(
                    f"BALANCE food {_сколько} ПОСТАВЛЕН МОСТОМ: поле созрело "
                    f"(готовых участков {_гот}), на еде НИКОГО, а еды {_еда} — "
                    f"ниже порога 500, и весь найм стоит. Отключается ключом "
                    f"--auto-food 0")

        # --- МЕХАНИЧЕСКИЕ КОМАНДЫ: их ставит мост, а не модель (20.09) ------
        #
        # Счёт по 734 тактам четырёх серий показал, из чего состоит ответ
        # модели: BALANCE 49 процентов, TRAIN 17, BUILD 11, BUILDERS 8,
        # UPGRADE 7, SEED 6, ATTACK 2. Три из них решения почти не несут, и
        # каждая измеримо портится от того, что её отдаёт модель:
        #   SEED     — 188 приказов, 98 процентов отданы, когда участки УЖЕ
        #              созрели, и 38 процентов повторены в пределах 25 с;
        #   BUILDERS — 26 приказов без BUILD в том же такте пропали впустую
        #              (блок читает потолок ТОЛЬКО вместе с закладкой), а 54
        #              закладки ушли с потолком по умолчанию 3, от которого
        #              котлован собирался из двух-пяти человек при двадцати;
        #   TRAIN    — 99 процентов это «бесконечный заказ», и в 4 процентах
        #              тактов с едой выше порога крестьян не куёт никто.
        # Каждая правка своим ключом и по умолчанию ВЫКЛЮЧЕНА: меряет серия,
        # а не уверенность автора.

        # SEED. Ставим, когда поле ВЫКОШЕНО: мельница есть, готовых участков
        # ноль. Повтор чаще, чем раз в половину срока созревания, смысла не
        # имеет — поле ещё не выросло, а каждое стоит 5 золота.
        if getattr(a, "auto_seed", 0):
            _мельниц = _чис(st.get("mills"))
            _гот = st.get("food_ready")
            try:
                _гот = int(float(_гот)) if _гот is not None else None
            except (TypeError, ValueError):
                _гот = None
            _сам = any(c.cmd == "SEED" for c in cmds)
            _когда = ПОСЕВ.get("t")
            _свежо = _когда is not None and (gt - _когда) < СОЗРЕВАНИЕ_С / 2
            if _сам:
                ПОСЕВ["t"] = gt              # модель посеяла — срок считаем от неё
                if _гот is not None and _гот > 0 and _свежо:
                    cmds = [c for c in cmds if c.cmd != "SEED"]
                    сказать(
                        f"SEED СНЯТ МОСТОМ: участки уже созрели ({_гот}) и "
                        f"сеяли {gt - _когда} с назад. Поле растёт не быстрее "
                        f"от повторов, а каждое стоит 5 золота. "
                        f"Отключается ключом --auto-seed 0")
            elif _мельниц > 0 and _гот == 0 and not _свежо:
                # СКОЛЬКО СЕЯТЬ. Наблюдение игрока 21.09: когда участок у
                # мельницы выкошен весь, сеять надо несколько полей подряд, а не
                # одно. По одному пересев растягивался на такты по двадцать
                # секунд, и еда всё это время не росла. Берём по числу тех, кто
                # будет на еде работать, но не больше пяти за раз: каждое поле
                # стоит 5 золота, а золото — узкое место в 61-98 процентах
                # тактов.
                _сеять = max(1, min(5, _чис(st.get("on_food")) or _мельниц))
                cmds.append(seed(_сеять))
                ПОСЕВ["t"] = gt
                сказать(
                    f"SEED {_сеять} ПОСТАВЛЕН МОСТОМ: мельниц {_мельниц}, готовых "
                    f"участков НОЛЬ — поле выкошено, и без посева еда не "
                    f"вырастет. Сеем {_сеять} полей сразу, а не одно: по одному "
                    f"пересев занял бы {_сеять} тактов. Отключается ключом "
                    f"--auto-seed 0")

        # ДЕЛИМ ПОТОЛОК МЕЖДУ ЗАКЛАДКАМИ ТАКТА (23.09). Блок применяет одно
        # число к каждой стройке и НИКОГДА не снимает людей с недостроя, так
        # что первая закладка забирает всех до потолка, а вторая получает
        # «nobody to build it - no peasants at all». Замер по дебюту base27:
        # на 12 с заказаны ратуша и мельница при BUILDERS 18 — ратуша встала
        # сразу, мельница отложилась на 41 и 70 секунд в двух копиях. Она
        # открывает еду, и простой первых 200 секунд стоит 44,5 процента
        # труда деревни.
        if getattr(a, "split_builders", 1):
            _зкл = [c for c in cmds if c.cmd == "BUILD"]
            _пот = next((c for c in cmds if c.cmd == "BUILDERS"), None)
            if len(_зкл) > 1 and _пот is not None:
                _своб = int(_чис(st.get("idle_pea")))
                _доля = max(1, _своб // len(_зкл))
                if _пот.a1 > _доля:
                    cmds = [builders(_доля) if c.cmd == "BUILDERS" else c
                            for c in cmds]
                    сказать(
                        f"BUILDERS {_пот.a1} -> {_доля}: закладок в такте "
                        f"{len(_зкл)}, свободных {_своб}. Потолок один на такт "
                        f"и действует на КАЖДУЮ стройку, а людей с недостроя "
                        f"блок не снимает — с прежним числом первая закладка "
                        f"забрала бы всех, а остальные получили бы «некому "
                        f"строить». Хочешь одну стройку большой артелью — "
                        f"заказывай её одну. Отключается --split-builders 0")

        # BUILDERS. Потолок читается блоком ТОЛЬКО вместе с BUILD в том же
        # такте. Поэтому: без закладки — команда пропадает, скажем об этом; с
        # закладкой и без потолка — ставим свой, иначе движок возьмёт 3.
        if getattr(a, "auto_builders", 0):
            _есть_build = any(c.cmd == "BUILD" for c in cmds)
            _есть_cap = any(c.cmd == "BUILDERS" for c in cmds)
            if _есть_cap and not _есть_build:
                cmds = [c for c in cmds if c.cmd != "BUILDERS"]
                сказать(
                    "BUILDERS СНЯТ МОСТОМ: в этом такте нет BUILD, а потолок "
                    "читается только вместе с закладкой — команда пропала бы "
                    "молча. Отключается ключом --auto-builders 0")
            elif _есть_build and not _есть_cap:
                cmds.insert(0, builders(a.auto_builders))
                сказать(
                    f"BUILDERS {a.auto_builders} ПОСТАВЛЕН МОСТОМ: закладка "
                    f"без потолка, а по умолчанию движок зовёт троих — от них "
                    f"котлован собирается из двух-пяти человек при двадцати. "
                    f"Выше геометрии здания это число всё равно не поднимет. "
                    f"Отключается ключом --auto-builders 0")

        # TRAIN крестьян. Бесконечный заказ снимает потолок «один за раз»
        # (train(), coss3_bridge.py). Если еды хватает, а крестьян не куёт
        # никто — заказ ставит мост.
        if getattr(a, "auto_train", 0):
            _еда = _чис(st.get("food"))
            _оч = str(st.get("train_now") or "")
            _сам = any(c.cmd == "TRAIN" for c in cmds)
            # РАТУША ОБЯЗАТЕЛЬНА. Поймано живой партией на маке 20.09: правило
            # срабатывало на 0:22 и 0:42, когда ратуша была на 13 процентах, и
            # заказ уходил в пустоту — движок отвечает «НЕТ РАТУШИ» и крестьян
            # не растёт (33->33 в прежних замерах). Самопроверка этого не
            # видела: в ней поля centers не было вовсе.
            _ратуша = _чис(st.get("centers"))
            if _ратуша > 0 and _еда >= 500 and "pea" not in _оч and not _сам:
                cmds.append(train("peasant", INFINITE))
                сказать(
                    f"TRAIN peasant бесконечно ПОСТАВЛЕН МОСТОМ: еды {_еда:.0f} "
                    f"выше порога 500, а в очереди ратуши крестьян нет вовсе. "
                    f"Отключается ключом --auto-train 0")

        # Что РЕАЛЬНО уйдёт в игру. Не по JSON модели: команду с негодной ролью
        # to_commands выбрасывает молча, и для проверок это тоже «не отдано».
        # Вето мостом сюда НЕ входит: команда в ответе была, и упрёк «написала
        # про ATTACK, а команды нет» стал бы ложью. Про вето говорит свой блок.
        отдано_слова = {c.cmd for c in cmds} | ({"ATTACK"} if attack else set())
        mm, ss = divmod(box["gt"], 60)
        n = box.get("tries", 1)
        помета = f"   [с {n}-й попытки]" if n > 1 else ""
        # У СОБЫТИЯ своя основная модель (--event-model): сравнивать с a.model
        # значило бы клеить «запасная» на каждый локальный ответ. 22.09 в
        # смоуке так и было: [запасная: qwen2.5:7b] при том, что запасной у
        # локального события нет по построению.
        положено = (getattr(a, "_модель_событий", "") or a.model) if box.get("повод") else a.model
        if box.get("model") and box["model"] != положено:
            помета += f" [запасная: {box['model'].split('/')[-1]}]"
        print(f"{mm}:{ss:02d}  {why}{помета}")
        if подхват:
            print("        модель забирает пульт у эталона раша")
        for строка in рассказ(box["data"]):
            print(строка)
        if a.lessons:
            _лж = притязание_без_команды(
                str(box["data"].get("lesson", "") or ""), отдано_слова)
            if _лж:
                # Урок про действие, которого не было, — не материал для
                # проверки гипотез, а ложь, которую следующий читатель примет
                # за факт. В журнал не пишем, но показываем, что отбросили.
                print(f"        УРОК ОТБРОШЕН: пишет «{_лж[0]}», а команды "
                      f"{_лж[1]} в этом ответе не было")
            else:
                _у = записать_урок(box["data"], a.lessons, номер_эпизода, gt,
                                   a.lessons_after)
                if _у:
                    print(f"        УРОК -> {a.lessons}: {_у}")
        if a.world:
            _в = " ".join(str(box["data"].get("question", "") or "").split())
            if _в and _в.lower() not in ("none", "null", "-"):
                if len(_в) < 12:
                    print(f"        ВОПРОС ОТБРОШЕН: слишком короткий — «{_в}»")
                elif вопросов_задано >= a.questions:
                    print(f"        ВОПРОС ОТБРОШЕН: за партию их {a.questions}, "
                          f"а этот уже {вопросов_задано + 1}-й — «{_в[:70]}»")
                else:
                    _зап = записать_вопрос(a.world, _в, номер_эпизода, gt)
                    if _зап:
                        вопросов_задано += 1
                        globals()["ВОПРОС_ЗАДАН"] = _зап
                        print(f"        ВОПРОС -> {a.world}: {_зап}")
                    else:
                        print(f"        ВОПРОС ОТБРОШЕН: такой уже задан и ждёт "
                              f"ответа — «{_в[:70]}»")
        # Модель может попросить новую партию. Порог в 120 игровых секунд —
        # чтобы «плохое начало» не превращалось в бесконечный перезапуск.
        if a.allow_restart and box["data"].get("restart") and gt >= 120:
            print(f"        модель просит новую партию: "
                  f"{str(box['data'].get('restart_why', ''))[:100]}")
            return "рестарт"
        if wait > slow_after:
            печ = max(0, int(gt - box["gt"]))
            думала = (box.get("ready", 0) - box["t"]) if box.get("ready") else 0
            лежало = wait - думала if думала else 0
            # 11.09.2026: на игровой машине --check давал 1,5-2 с, а эта строка
            # показывала 48 — потому что мерила не работу модели, а время до
            # момента, когда цикл забрал готовый ответ. Между тем цикл сидит в
            # wait_state и ждёт, пока игра запишет новое состояние. Теперь
            # видно, кто именно виноват.
            кто_и_сколько = ""
            if box.get("provider") or box.get("tokens"):
                кто_и_сколько = (f", {box.get('tokens', 0)} токенов"
                                 + (f" через {box['provider']}" if box.get("provider") else ""))
            откуда = (f" (модель {думала:.0f} с, ждал забора {лежало:.0f} с"
                      f"{кто_и_сколько})" if думала else "")
            print(f"        решение готовилось {wait:.0f} с при бюджете такта "
                  f"{slow_after:.0f} с{откуда} — применяется на {печ} "
                  f"игровых секунд позже")
        for c in cmds:
            print(f"        {c.cmd} {c.a1} -> {c.a2}" + (f" {c.upg}" if c.upg else ""))
        if attack:
            print(f"        ATTACK {attack} -> {цель_атаки}"
                  + (f", только {кем_атака}" if кем_атака else ""))
            # МАЛО ЛИ ПОСЛАНО. Мост считает, сколько нужно одним кулаком, и
            # молчать об этом в миг отправки нельзя: 19.09 модель слала 40 при
            # 82 свободных, а по размену на тот состав требовалось втрое больше.
            try:
                _св = combat_math.разобрать(st.get("fighters"))
                _чж, _ = чужие_со_строем(st, mp)
                _общ = [combat_math.размен(_св[и], _чж[и])["нужен_кулаком"]
                        for и in _св if и in _чж
                        and _св[и].get("atk") and _чж[и].get("atk")]
                _враг_всего = _чис(st.get("p1_army")) or 0
                if _общ and _враг_всего and attack < 9999:
                    _надо = int(round(_враг_всего * max(_общ) / combat_math.ЗАПАС))
                    if attack < _надо:
                        print(f"          мало: по размену на его {_враг_всего} "
                              f"нужно около {_надо} одним кулаком, послано {attack}"
                              f" — count:\"all\" отдаст всех свободных")
            except Exception:
                pass
        if движение:
            print(f"        MOVE {движение} -> {цель_движения}")
        if вето_волны:
            print(f"        ВЕТО МОСТА: {вето_волны}")
        if принуждение:
            print(f"        МОСТ ВМЕШАЛСЯ: {принуждение}")
        for _б in брак:
            print(f"        НЕ УШЛО В ИГРУ: {_б}")
        # Сжатая строка такта для критика: ресурсы, люди, армия, команды.
        # Тело — в `строка_такта`: тот же текст нужен разбору готовой трассы.
        try:
            _мм, _сс = divmod(int(float(st.get("gametime", 0) or 0)), 60)
            ТРАССА_ПАРТИИ.append(строка_такта(st, mp, cmds, attack, цель_атаки,
                                              событие=str(box.get("событие") or "")))
            _у = " ".join(str(box["data"].get("lesson", "") or "").split())
            if _у:
                УРОКИ_ПАРТИИ.append(f"{_мм}:{_сс:02d} {_у}")
        except Exception:
            pass                        # разбор не должен ронять партию
        if a.botlog:
            # По строке на такт: решение, отданные команды, брак и результат.
            # Лог партии писан для человека, этот — чтобы считать статистику по
            # серии и показывать на защите, что именно делал бот.
            try:
                with open(a.botlog, "a", encoding="utf-8") as _f:
                    _д = box["data"]
                    # Трасса пишется ДЛЯ ОБУЧЕНИЯ, а не для отчёта, поэтому в
                    # ней должно лежать всё, из чего решение выросло: снимок
                    # мира, итог прошлого хода, рассуждение модели целиком и её
                    # гипотезы. Раньше сюда шло только why, и по такой строке
                    # нельзя ни воспроизвести решение, ни оценить его.
                    _снимок = {k: st.get(k) for k in (
                        "gametime", "food", "wood", "stone", "gold", "iron", "coal",
                        "peasants", "idle_pea", "on_food", "on_wood", "on_stone",
                        "on_mine", "on_build", "centers", "mills", "smiths", "ba17",
                        "my_stores", "mines_iron", "mines_gold", "mines_coal",
                        "mil_inf", "mil_shooters", "my_freewar", "my_farm",
                        "my_farmused", "building_now", "wip", "last_fail",
                        # Судьба волны: без неё по трассе снова нельзя отличить
                        # «погибли по дороге» от «дошли и не справились».
                        "wave_sent", "mil_away", "mil_hurt", "mil_far",
                        # ЧТО МОЖНО КУПИТЬ — иначе окупаемость не пересчитать.
                        # Поля `upg_avail` в снимке не было ВОВСЕ, и 20.09 это
                        # дало ложный ноль: счёт по трассе сказал «академические
                        # апгрейды не попадали в список ни разу», тогда как в
                        # живом состоянии их было тридцать шесть, с ценами.
                        # Целиком список длинный (183 имени), поэтому в трассу
                        # идут академические — те, по которым считается новая
                        # окупаемость, — и общее число остальных.
                        # Кто в какой шахте и сколько там мест: без этого
                        # BALANCE gold нечем проверить задним числом.
                        "on_gold", "on_iron", "on_coal",
                        "cap_gold", "cap_iron", "cap_coal",
                        "work_gold", "work_iron", "work_coal",
                        "mil_near", "mil_side", "academi",
                        "can_now", "cant_now", "fighters", "build_cost",
                        "wood_slots_near", "wood_slots_free",
                        "stone_slots_near", "stone_slots_free",
                        "ore_gold_dist", "ore_gold_near", "ore_gold_side",
                        "ore_iron_dist", "ore_iron_near", "ore_iron_side",
                        "ore_coal_dist", "ore_coal_near", "ore_coal_side",
                        "map_open", "upg_done", "upg_doing", "train_now", "ba_queues", "food_ready",
                        # Сами сетки в трассу не кладём: 32 строки на такт это
                        # мегабайты за серию. Кладём метки — по ним видно, была
                        # ли карта в запросе и где стояла наша база.
                        "grid_n", "my_cx", "my_cy",
                        # Слагаемые готовности к удару. Без них по трассе
                        # нельзя ответить на главный вопрос: с чем модель
                        # посылала волну и был ли строй — а значит нельзя и
                        # сравнить идею с базой.
                        "mil_guns", "my_officers", "my_drummers",
                        "squads", "squad_units", "squad_form",
                        "squad_dmg", "squad_def", "squad_hdmg", "squad_hdef",
                        "can_pea", "can_inf", "famine", "en_near_dist",
                        # Где стоит свой кулак и своя волна: без этого по трассе
                        # не видно, что армия стояла врозь, когда пришёл враг.
                        "my_army_cx", "my_army_cy", "my_army_n",
                        "wave_cx", "wave_cy", "wave_n",
                        # Конюшня и конница: без них серия dragoons 18.09
                        # считалась по строке стройки, а не по факту.
                        "stables", "mil_cav")
                        if st.get(k) is not None}
                    # Враг у НАШЕЙ базы считается в python по сетке; в трассу
                    # кладём число, иначе набеги по серии не посчитать задним
                    # числом — а 17.09 именно так и потерялись 36 крестьян.
                    _снимок["en_at_base"] = coss3_map.у_базы(st).get("бойцов", 0)
                    _пот = {"en_pea": поле_врага(st, mp, "pea_lost"),
                            "en_mil": поле_врага(st, mp, "mil_lost"),
                            "my_pea": st.get("my_pea_lost"),
                            "my_mil": st.get("my_mil_lost")}
                    _пот_такт = {
                        к: max(0, (_пот.get(к) or 0) - (ПОТЕРИ_БЫЛО.get(к) or 0))
                        for к in ("en_pea", "en_mil", "my_pea", "my_mil")}
                    ПОТЕРИ_БЫЛО.update({к: в for к, в in _пот.items() if в is not None})
                    # Открытая информация (18.09): что мост знал о противнике
                    # в этот такт, иначе по серии не проверить ни «шёл ли враг»,
                    # ни «была ли клетка без охраны». Ключи en_<поле>.
                    for _k in ("food", "wood", "stone", "gold", "iron", "coal",
                               "upg_done", "train", "mv_n", "mv_base", "mv_cx", "mv_cy",
                               "fighters"):
                        _v = поле_врага(st, mp, _k)
                        if _v is not None:
                            _снимок["en_" + _k] = _v
                    # ТОЧНЫЕ ЧИСЛА КЛЕТОК КОНТАКТА (26.09, поле `cells` блока).
                    # Кладём в трассу ВСЕГДА, когда поле есть, даже пустым
                    # списком: сетка упирается в 61 даже с двумя алфавитами, а
                    # бой, из-за которого потолок и поднимали, шёл при 194
                    # наших против 36 его в одной клетке. Отсутствие ключа и
                    # измеренное «клеток нет» должны различаться, иначе счёт по
                    # серии даст ложный ноль.
                    # ТЫЛ СТРЕЛКОВ в трассу (27.09): без этого мера «стрелки и
                    # пикинёры в РАЗНЫХ клетках» по серии не считается вовсе.
                    if ТЫЛ.get("клетка"):
                        _снимок["тыл"] = [ТЫЛ["клетка"][0], ТЫЛ["клетка"][1],
                                          _чис(ТЫЛ.get("когда"))]
                    if coss3_map.есть_точные_клетки(st):
                        _снимок["cells"] = coss3_map.клетки_боя(st)
                        _снимок["cells_n"] = _чис(st.get("cells_n"))
                    _кл = coss3_map.крестьяне_врага(st)
                    if _кл:
                        _снимок["en_pea_cells"] = _кл
                    # СЕТКИ ЦЕЛИКОМ. Модель их видит каждый такт, а в трассе их
                    # не было, и задним числом нельзя было спросить, ГДЕ стояла
                    # его армия: 19.09, считая гарнизон, пришлось идти окольно
                    # через p1_mv_n — «сколько в движении» вместо «где стоят».
                    # Три сетки стоят около 1,2 КБ на такт при записи в 5,7 КБ;
                    # за возможность считать расстановку по серии это дёшево.
                    # frow — его бойцы, prow — его крестьяне, arow — наши: по
                    # ней считается растянутость волны, которую тоже мерили
                    # руками по одной партии.
                    # brow — его и наши здания (24.09): без неё «у его базы» по
                    # серии было не посчитать, а новая цель ровно про это.
                    for _сетка in ("frow", "prow", "arow", "brow", "drow"):
                        _строки = [str(st.get(f"{_сетка}{_y}") or "")
                                   for _y in range(_чис(st.get("grid_n")) or 16)]
                        if any(c != "." for _s_ in _строки for c in _s_):
                            _снимок[_сетка] = _строки
                    # Оценка обстановки со слагаемыми: по ней серия скажет, при
                    # каком перевесе волны убивали, и поставит порог. Считать
                    # надо по серии НА НЫНЕШНЕЙ формуле: до починки 19.09
                    # «перевес» мерил глобальный перевес, и старые числа к нему
                    # не относятся (`assess_report.py`).
                    _пох = coss3_map.походы_врага(st)
                    if _пох:
                        _снимок["en_march"] = [[o["n"], o["x"], o["y"], o["сек"]] for o in _пох[:6]]
                    _база = coss3_map.база_врага(st)
                    if _база:
                        _снимок["en_base"] = [_база["cx"], _база["cy"], _база["клеток"]]
                    _оц = оценка_обстановки(st, mp)
                    if _оц:
                        _снимок["assess"] = {"режим": _оц["режим"], "прогноз": _оц["прогноз"],
                                             "клетки": _оц["клетки"]}
                    # Всё, что состояние знает о чужих слотах: их имена вида
                    # p<номер>_<что>. Перечислять хвосты руками уже нельзя —
                    # 16.09 полей врага стало двадцать, и список бы отстал.
                    _снимок.update({k: v for k, v in st.items()
                                    if _ПОЛЕ_ВРАГА.match(k)})
                    # Академические апгрейды с ценами — отдельным полем, чтобы
                    # окупаемость академии можно было пересчитать по трассе.
                    _ак = [x for x in str(st.get("upg_avail") or "").split(",")
                           if x.strip().startswith("aca.")]
                    _снимок["upg_aca"] = ",".join(_ак) or None
                    _снимок["upg_avail_n"] = len(
                        [x for x in str(st.get("upg_avail") or "").split(",") if x.strip()])
                    # Что из апгрейдов модель ВИДЕЛА. Целиком `upg_avail` в
                    # трассу не кладём — двести двадцать имён в каждом такте,
                    # это сотни килобайт на партию. А без показанного списка
                    # разбор слеп: 15.09 по трассе серии `upgrades` нельзя было
                    # понять, что военных имён в запросе не было вовсе, и
                    # пришлось читать состояние из живого контейнера.
                    _уа = [у for у in str(st.get("upg_avail", "") or "").split(",")
                           if у.strip()]
                    if _уа:
                        _снимок["upg_shown"] = ",".join(
                            отобрать_апгрейды(_уа, st)[0])
                    _f.write(json.dumps({
                        "gt": box["gt"], "why": why,
                        "ok": str(_д.get("ok", "") or ""),
                        "stuck": str(_д.get("stuck", "") or ""),
                        "cause": str(_д.get("cause", "") or ""),
                        "lesson": str(_д.get("lesson", "") or ""),
                        "idea": str(_д.get("idea", "") or ""),
                        # Вопрос в трассе нужен, даже если мост его отбросил:
                        # по серии видно, о чём модель спрашивает раз за разом,
                        # и это само по себе показывает дыру в описании мира.
                        "question": str(_д.get("question", "") or ""),
                        # Марш по контракту модели: фаза, клетка сбора, порог,
                        # что мост сделал. Без этого по трассе не отличить
                        # «собрались и ударили» от «истёк срок».
                        "march": ({k: v for k, v in МАРШ.items() if k != "отчёт"}
                                  if МАРШ else None),
                        # Чем проверялась эта партия. Без этой строки по трассе
                        # нельзя отделить партии, где гипотеза критика была в
                        # запросе, от партий без неё — а значит нельзя и
                        # измерить, помогает ли она.
                        "critic_hyp": (ГИПОТЕЗА_КРИТИКА.get("гипотеза", "")
                                       if КРИТИК_ВПЕРЁД else ""),
                        # Когда волна впервые дошла и убила: веха отделена от
                        # победы 17.09, и по серии её надо считать отдельно.
                        "веха_убийства": (ВЕХА_УБИЙСТВО[0] if ВЕХА_УБИЙСТВО else None),
                        # Потери по счёту движка (20.09): его и наши, крестьяне
                        # и бойцы С НАЧАЛА ПАРТИИ, накопительно. None — старый
                        # блок.
                        "потери": _пот,
                        # И ТО ЖЕ ЗА ЭТОТ ТАКТ (23.09). Накопительный счётчик
                        # читается неверно на раз: 23.09 я сложил его по тактам
                        # и получил 11432 убитых при пике армии 191, после чего
                        # объявил поле сломанным. Оно не сломано — сложение
                        # было не тем действием. Разница за такт считается
                        # здесь, один раз и правильно: откат вниз (новая партия
                        # или перезапуск) даёт ноль, а не отрицательное число.
                        "потери_такт": _пот_такт,
                        # ГОЛОД ВРАГА ОТДЕЛЬНО (24.09): накоплено за
                        # партию. Без него у меры «убито крестьян врага» пол
                        # около пяти, и настоящий ноль неотличим от удара.
                        "голод_врага": (ГОЛОД_ВРАГА[0] if ГОЛОД_ВРАГА else 0),
                        "state": _снимок,
                        "outcome_prev": _раздел(box.get("prompt", ""),
                                                "## Итог прошлого решения"),
                        "cmds": [{"cmd": c.cmd, "a1": c.a1, "a2": c.a2, "upg": c.upg}
                                 for c in cmds],
                        "attack": attack, "target": цель_атаки,
                        "вмешательство": str(box.get("вмешательство") or ""),
                        # СТОЯЧИЙ приказ накопления. Два разных факта, и оба
                        # нужны: `stage` — что модель сделала В ЭТОМ такте
                        # (включила, отменила или не трогала), `stage_on` —
                        # стоит ли приказ СЕЙЧАС. Без первого не измерить,
                        # берёт ли модель команду; без второго не отделить
                        # такты под накоплением от тактов без него.
                        # Что модель попросила MOVE/RETREAT и каким видом
                        # бойцов — до вмешательства моста.
                        "move": ({"n": _просила["move"][0],
                                  "target": _просила["move"][1],
                                  "who": _просила["move"][2]}
                                 if _просила["move"] else None),
                        "who": (_просила["who_attack"] or None),
                        # СОБЫТИЙНЫЙ ВЫЗОВ: какое здание разбудило модель вне
                        # такта. Без этого поля событие видно только по префиксу
                        # «по событию» в `why` — то есть косвенно, а по правилу
                        # разбора счёт по полю, которого нет, даёт ложный ноль.
                        # Игрок заметил пропажу первым, 21.09.
                        "событие": box.get("событие"),
                        # ВИД повода отдельно от метки: по серии надо считать
                        # «сколько раз спросили про руки» без разбора строки.
                        "повод": box.get("повод"),
                        # ЗАПРОС СОБЫТИЯ ЦЕЛИКОМ. 21.09: разбирая прогон, я
                        # трижды насчитал ложный ноль, пытаясь узнать, ЧТО мост
                        # спросил, — в трассе этого не было, и запрос
                        # приходилось пересобирать вызовом на снимке.
                        #
                        # Пересборка ВРЁТ, и врёт убедительно: она берёт
                        # СЕГОДНЯШНИЙ код. Пересобрав запрос прогона free_hands
                        # (мост до починки «еда предлагалась без созревшего
                        # поля»), получишь починенную версию и решишь, что
                        # дефекта не было. Записанный запрос этого не допускает.
                        #
                        # Пишем ТОЛЬКО событийный: он короткий (600-1500 знаков
                        # против ~7000 токенов у обычного такта), и именно по
                        # нему считают, что мост предлагал и что закрыл.
                        "запрос": (box.get("prompt") if box.get("повод") else None),
                        "stage": (dict(STAGE_ЗА_ТАКТ) if STAGE_ЗА_ТАКТ else None),
                        "stage_on": (dict(НАКОПЛЕНИЕ) if НАКОПЛЕНИЕ else None),
                        # КУДА именно ушла волна. Без этих двух чисел разбор
                        # серии сводил оценку по ЛУЧШЕЙ клетке (`клетки[0]`) —
                        # той, что мост ПРЕДЛАГАЕТ, а не той, что модель
                        # выбрала: 19.09 это было единственное место, где
                        # `assess_report` огрублял счёт. При цели не «cell»
                        # координат нет и быть не может — волна идёт к
                        # ближайшему крестьянину, и это сама по себе улика.
                        "aim": (list(клетка) if (цель_атаки == "cell"
                                                 and клетка and клетка[0] >= 0)
                                else None),
                        "rejected": брак,
                        # Что просила модель, видно в "attack"; ушло ли это в
                        # игру — только здесь. Без поля разбор трассы считал
                        # заниженную волну ушедшей.
                        "veto": вето_волны,
                        # Что мост поставил вместо модели. Без этого поля в
                        # трассе решение выглядело бы решением модели, и разбор
                        # приписал бы ей чужой ход.
                        "forced": принуждение,
                        "model": box.get("model", a.model),
                        "tokens": box.get("tokens", 0),
                        "provider": box.get("provider", ""),
                        "think_s": round((box.get("ready", 0) - box["t"]), 1)
                                   if box.get("ready") else None,
                    }, ensure_ascii=False) + "\n")
            except OSError:
                pass                        # лог не должен ронять партию
        расхождение = названо_но_не_отдано(
            " ".join(str(box["data"].get(k, "") or "")
                     for k in ("why", "ok", "stuck", "cause", "lesson")),
            отдано_слова)
        for _с in расхождение:
            print(f"        сказано, но не сделано: написала про {_с}, "
                  f"команды {_с} в ответе нет")
        history.append(f"{mm}:{ss:02d} {why}")

        if дневник is not None:
            дневник.такт(st, брак)
        for _c in cmds:
            if _c.cmd == "BALANCE" and _c.a1 == RESOURCE["food"]:
                _кр = int(st.get("peasants", 0) or 0)
                if _c.a2 > _кр:
                    print(f"        BALANCE food {_c.a2} — это ЧИСЛО людей, а "
                          f"крестьян всего {_кр}: на еду уйдут все")
        было_st = st
        # Число берём ТЕМ ЖЕ разбором, что и команды: с 19.09 count может быть
        # словом «all», и прямой int() на нём падал — прогон 19.09 умер на
        # ValueError посреди партии, когда модель написала count:"all".
        # РОЛЬ БЕРЁМ ИЗ РАЗБОРА, а не из сырого поля (23.09). Модель пишет её
        # разными словами и числами, `нормализовать` их и сводит — а здесь
        # стояло сырое `role`, и при ответе без этого ключа вердикт выходил
        # безымянным: «BALANCE  16: отправлено, проверить нечем». Пустая роль
        # не попадала ни в одну проверку — ни «нет мельницы», ни счёт людей, —
        # и модель слышала «отправлено» там, где игра отказала.
        прошлый_заказ = [(str(i.get("cmd", "")).upper(),
                          нормализовать(i)[1] or str(i.get("role", "")),
                          нормализовать(i)[2])
                         for i in (box["data"].get("commands") or [])[:6]
                         if str(i.get("cmd", "")).upper()
                         in ("BUILD", "TRAIN", "ATTACK", "BALANCE", "UPGRADE")]
        if вето_волны:
            # «Итог прошлого решения» судит только то, что ушло в игру. Оставь
            # здесь отвергнутую волну — и на следующем такте модель прочтёт
            # «НИКТО НЕ ПОШЁЛ, приказ отвергается целиком, если бойцов меньше
            # запрошенного», то есть ложную причину: бойцов-то хватало, отказал
            # мост. Про вето говорит свой блок, здесь волны быть не должно.
            прошлый_заказ = [т for т in прошлый_заказ if т[0] != "ATTACK"]
        # BALANCE пачки — одно распределение людей на земле (см. распределить_balance).
        cmds, _урез = распределить_balance(cmds, st)
        if _урез:
            print("        " + _урез)
            вмешательство = (вмешательство + "; " if вмешательство else "") + _урез
        if cmds:
            if br.send(cmds):
                br.wait_consumed(timeout=15)
            else:
                # 21.09, со вторым слотом отправок стало вдвое больше, и этот
                # отказ перестал быть редкостью. Молчать нельзя: пачка пропала
                # целиком, а по логу это неотличимо от «модель ничего не
                # решила». Говорим и в лог, и модели следующим тактом.
                _имена = ", ".join(sorted({getattr(c, "cmd", "?") for c in cmds}))
                print(f"        ПАЧКА НЕ ОТПРАВЛЕНА ({_имена}): прошлый приказ "
                      f"ещё не забран игрой")
                вмешательство = (вмешательство + "; " if вмешательство else "") + (
                    f"твои команды ({_имена}) НЕ ДОШЛИ: игра не успела забрать "
                    f"прошлый приказ. Повтори их, если они ещё нужны")
        # MOVE уходит ДО атаки и отдельно от неё: главный случай — движение без
        # боя вовсе, и прятать его внутрь веток ATTACK значило бы потерять.
        # Файл приказа один, поэтому обе команды разом не отдать: to_commands
        # это ловит и говорит вслух.
        if движение and цель_движения == "retreat":
            _вдали = _чис(st.get("mil_away"))
            if _вдали <= 0:
                print(f"        RETREAT {движение} не отправлен: дальше 60 от базы никого нет")
                вмешательство = (вмешательство + "; " if вмешательство else "") + (
                    f"RETREAT {движение} НЕ ОТПРАВЛЕН: дальше 60 от ратуши твоих нет, "
                    f"отзывать некого")
            elif not br.attack(движение, "home", mode="retreat", who=кем_движение):
                print("        RETREAT не отправлен: прошлый приказ ещё не забран игрой")
            else:
                print(f"        RETREAT {движение}: бойцы дальше 60 от базы ({_вдали}) идут домой")
            движение = 0
        if движение:
            св = int(st.get("my_freewar", 0) or 0)
            if св <= 0:
                print(f"        MOVE {движение} не отправлен: свободных бойцов нет "
                      f"— идущие в походе своего приказа не бросают")
            elif not br.attack(движение, цель_движения, mode="move",
                               cx=клетка[0], cy=клетка[1], who=кем_движение):
                print(f"        MOVE {движение} не отправлен: прошлый приказ ещё "
                      f"не забран игрой")
            else:
                print(f"        MOVE {движение} -> {цель_движения} (без боя)"
                      + (f", только {кем_движение}" if кем_движение else ""))
        # Новый приказ модели отменяет идущий марш: решение её, и последнее
        # слово тоже. ИСКЛЮЧЕНИЕ - подкрепление в тот же кулак, пока идёт сбор
        # или группа стоит у сбора. Найдено дважды и порознь 18.09: игроком по
        # home_first копия 2 (марш 50 -> 17 -> 4 -> 10, кулак не ударил ни разу)
        # и маком по мак-тесту (у сбора 10 из 12, подкрепление стёрло контракт).
        # Подкреплением считается: ATTACK с той же клеткой сбора и той же целью,
        # ATTACK target=wave, ATTACK cell в саму клетку сбора.
        if (attack and not вето_волны and МАРШ.get("фаза") in ("сбор", "стоим")
                and ((контракт.get("via") and tuple(контракт["via"]) == tuple(МАРШ["via"])
                      and цель_атаки == МАРШ["цель"]
                      and (цель_атаки != "cell" or tuple(клетка) == tuple(МАРШ["клетка"])))
                     or цель_атаки == "wave"
                     or (цель_атаки == "cell" and tuple(клетка) == tuple(МАРШ["via"])))):
            св = int(st.get("my_freewar", 0) or 0)
            n = min(int(attack), св)
            _с = примкнуть_к_маршу(st, br, gt, n) if n > 0 else (
                f"ATTACK {attack} (марш) — подкрепление не отправлено: свободных нет, "
                f"сбор в ({МАРШ['via'][0]},{МАРШ['via'][1]}) идёт")
            print("        " + str(_с))
            attack = 0
        # Любой ДРУГОЙ новый приказ отменяет идущий марш. Но люди у сбора не
        # исчезают - сказать, где они и что удара не будет.
        elif (attack or движение) and МАРШ:
            if МАРШ.get("фаза") in ("сбор", "стоим"):
                vx, vy = МАРШ["via"]
                вмешательство = (вмешательство + "; " if вмешательство else "") + (
                    f"МАРШ ОТМЕНЁН твоим новым приказом: {МАРШ.get('у_сбора', 0)} бойцов "
                    f"стоят у сбора ({vx},{vy}) без приказа, {МАРШ.get('в_пути', 0)} ещё шли. "
                    f"Удара по ({МАРШ['клетка'][0]},{МАРШ['клетка'][1]}) не будет; "
                    f"следующий ATTACK заберёт их, где стоят")
            МАРШ.clear()
        # УДАР В ЭТОМ ТАКТЕ — отдельный флаг, ПОТАКТОВЫЙ. `волна_была` живёт всю
        # партию (это веха «уходил ли кто-то в атаку»), и условие «в такт без
        # удара» на нём не срабатывало ни разу после первой волны: смоук 27.09
        # показал это сразу — подмена вида шла, а отвода стрелков не было.
        удар_в_такте = False
        # ATTACK target=wave: К ВОЛНЕ, а не мимо неё. Клетку волны блок пишет
        # только когда кто-то идёт с приказом (wave_n > 0); иначе идти некуда.
        _было_wave = bool(attack and цель_атаки == "wave")
        if attack and not вето_волны and цель_атаки == "wave":
            _кв = _клетка_волны(st)
            if _кв is not None:
                клетка = _кв
                цель_атаки = "cell"
                print(f"        ATTACK {attack} -> wave: к волне в клетку "
                      f"({клетка[0]},{клетка[1]})")
            else:
                print(f"        ATTACK {attack} -> wave не отправлен: в поле нет своих "
                      f"дальше двух клеток от базы, идти не к кому")
                вмешательство = (вмешательство + "; " if вмешательство else "") + (
                    f"ATTACK {attack} -> wave НЕ ОТПРАВЛЕН: в поле нет ни одной твоей "
                    f"волны (своих дальше двух клеток от ратуши на карте нет). "
                    f"Дай цель peasants, base или cell")
                attack = 0
        # «К ВОЛНЕ» БЕЗ МАРША -> МАРШ НА КЛЕТКУ ВОЛНЫ (24.09, --wave-march).
        # Счёт по девяти партиям: 1484 такта с атакой, из них 1206 «к волне»,
        # и в 971 из них марша в этот миг НЕ БЫЛО. Все они уходили простым
        # движением - без сбора, порога, срока и удара. Намерение модели
        # здесь не искажается: она просила идти к волне, туда люди и пойдут;
        # разница в том, что вместо струйки будет сбор, а удар - по ближайшей
        # клетке крестьян врага, ради которых партия и играется. Если клеток
        # крестьян нет, бьём по клетке волны - там бой и так идёт.
        if (attack and not вето_волны and цель_атаки == "cell"
                and _было_wave and not контракт.get("via")
                and getattr(a, "wave_march", 0) and not МАРШ):
            контракт["via"] = tuple(клетка)
            _кр = coss3_map.крестьяне_врага(st) or []
            if _кр:
                _бл = min(_кр, key=lambda к: max(abs(к["x"] - клетка[0]),
                                                  abs(к["y"] - клетка[1])))
                клетка = (_бл["x"], _бл["y"])
            вмешательство = (вмешательство + "; " if вмешательство else "") + (
                f"ATTACK -> wave заведён МАРШЕМ: сбор в клетке волны "
                f"({контракт['via'][0]},{контракт['via'][1]}), удар по "
                f"({клетка[0]},{клетка[1]}) — "
                f"{'ближайшая клетка крестьян врага' if _кр else 'клетка волны, крестьян врага на карте не видно'}. "
                f"Без этого подкрепление шло бы струйкой мимо сбора. "
                f"Отключается --wave-march 0")
        # МАРШ: ATTACK с клеткой сбора. Бойцы уходят MOVE в клетку via, дальше
        # мост ведёт марш по контракту (шаг_марша) и бьёт, когда соберутся.
        if attack and not вето_волны and контракт.get("via"):
            св = int(st.get("my_freewar", 0) or 0)
            vx, vy = контракт["via"]
            if st.get("peacemode"):
                print(f"        ATTACK {attack} (марш) не отправлен: перемирие")
            elif св <= 0:
                print(f"        ATTACK {attack} (марш) не отправлен: свободных бойцов нет")
            elif not br.attack(min(attack, св), "cell", mode="move", cx=vx, cy=vy):
                print("        ATTACK (марш) не отправлен: прошлый приказ ещё не забран игрой")
            else:
                n = min(attack, св)
                if n < attack:
                    print(f"        ATTACK {attack} урезан до {n}: столько сейчас свободно")
                начать_марш(gt, n, цель_атаки, клетка, контракт, st)
                волна_была = True
                удар_в_такте = True
                print(f"        марш: {n} бойцов идут БЕЗ боя в клетку сбора ({vx},{vy}); "
                      f"удар по {цель_атаки}"
                      + (f" ({клетка[0]},{клетка[1]})" if цель_атаки == "cell" else "")
                      + f" — когда соберутся, срок {МАРШ['expires']} с"
                      + (f", порог {МАРШ['hold']}" if МАРШ.get("hold") else ""))
            attack = 0
        # КЛЮЧ --rear-shooters: удар уходит ПИКИНЁРАМИ, стрелков мост отводит
        # сам (ниже, в свой такт). Подменяем только когда модель вида НЕ назвала:
        # её собственный выбор мост не переписывает.
        if (attack and not вето_волны and getattr(a, "rear_shooters", 0)
                and not кем_атака and _чис(st.get("mil_shooters")) > 0
                and _чис(st.get("mil_inf")) > 0):
            кем_атака = "infantry17"
            ТЫЛ["ждёт"] = True
            вмешательство = (вмешательство + "; " if вмешательство else "") + (
                f"УДАР УХОДИТ ПИКИНЁРАМИ (ключ --rear-shooters {a.rear_shooters}): "
                f"стрелков {_чис(st.get('mil_shooters'))} мост отведёт в тыл сам, "
                f"за {a.rear_shooters} клеток от боя к нашей базе — ближе шести "
                f"мушкетёр не стреляет, а отходит. Тебе их вести не нужно")
        if attack and not вето_волны:
            св = int(st.get("my_freewar", 0) or 0)
            аг = int(st.get("my_agressors", 0) or 0)
            if st.get("peacemode"):
                print(f"        ATTACK {attack} не отправлен: перемирие")
            elif a.human and attack > св + аг and св + аг > 0:
                # На ЧЕЛОВЕЧЕСКОМ слоте правила «всё или ничего» нет: block_hcmd
                # набирает волну до запрошенного числа и шлёт сколько набрал.
                # Прежнее вето было списано с компьютерного слота и просто
                # теряло волны: состояние устаревает на время ответа модели
                # (в прогоне 12.09 до 38 с), число свободных за это время
                # меняется, и приказ отменялся целиком. Урезаем и шлём.
                урезано = св + аг
                print(f"        ATTACK {attack} урезан до {урезано}: столько сейчас "
                      f"свободно (свободных {св}, в пуле {аг})")
                attack = урезано
                if not br.attack(attack, цель_атаки,
                                 cx=клетка[0], cy=клетка[1], who=кем_атака):
                    print("        ATTACK не отправлен: прошлый приказ ещё не забран игрой")
                else:
                    next_attack = gt + a.attack_every
                    волны.append((gt, attack, цель_атаки))
                    ОТПРАВКА.update(gt=gt, послано=attack, армия=_чис(st.get("mil_inf"))
                                    + _чис(st.get("mil_shooters")),
                                    дома=(цель_атаки == "cell"
                                          and _дома(st, клетка[0], клетка[1])))
                    if дневник is not None:
                        дневник.волна(gt, attack, цель_атаки, st)
                    волна_была = True
                    удар_в_такте = True
                    print(f"        волна {len(волны)}: {attack} бойцов ушли на {цель_атаки}")
            elif not a.native_war and attack > св + аг:
                # Раньше здесь стояло вето «агрессоров больше нуля — не слать».
                # Оно било мимо: my_agressors — это ПУЛ бойцов, назначенных в
                # агрессоры, а не идущая волна, и он не пустеет. За серию
                # 11.09.2026 все 15 команд ATTACK были отвергнуты этим правилом.
                # Причину (заказ переформировывал идущую армию) вылечили в
                # block_war.inc: волна набирается СНАЧАЛА из свободных бойцов.
                # Осталась честная проверка: приказ отвергается целиком, если
                # свободных меньше запрошенного.
                print(f"        ATTACK {attack} не отправлен: бойцов всего "
                      f"{св + аг} (свободных {св}, в пуле {аг}) — "
                      + ("собирать некого" if ЧЕЛОВЕК else
                         "игра отвергнет приказ целиком"))
            elif a.native_war and аг > 0:
                print(f"        ATTACK {attack} не отправлен: волна из {аг} уже в пути, "
                      f"повторный приказ переформирует её (нативная атака включена)")
            elif gt < next_attack:
                print(f"        ATTACK {attack} не отправлен: прошлая волна ушла "
                       f"{gt - (next_attack - a.attack_every)} игровых секунд назад, "
                       f"жду до {next_attack}")
            # who=кем_атака ЗДЕСЬ БЫЛО ПОТЕРЯНО (найдено 27.09). Ветка выше, с
            # урезанием, поле передавала, а эта — нет, и это ОБЫЧНЫЙ путь удара:
            # верхняя срабатывает только когда запрошено больше, чем свободно.
            # То есть «бей пикинёрами» модели молча превращалось в «бей всеми», и
            # серия split_control мерила не то, что думала: приказов по виду в
            # трассе 2 / 2 / 1, а до игры не дошёл НИ ОДИН. Молчаливый отброс
            # неотличим от бездействия — правило №1 проекта.
            elif not br.attack(attack, цель_атаки,
                               cx=клетка[0], cy=клетка[1], who=кем_атака):
                print(f"        ATTACK {attack} не отправлен: прошлый приказ "
                      f"ещё не забран игрой")
            else:
                next_attack = gt + a.attack_every
                волны.append((gt, attack, цель_атаки))
                ОТПРАВКА.update(gt=gt, послано=attack, армия=_чис(st.get("mil_inf"))
                                + _чис(st.get("mil_shooters")),
                                дома=(цель_атаки == "cell"
                                      and _дома(st, клетка[0], клетка[1])))
                волна_была = True
                удар_в_такте = True
                print(f"        волна {len(волны)}: {attack} бойцов ушли на "
                      f"{цель_атаки}"
                      + (f", КЕМ: {кем_атака}" if кем_атака else ""))
                if цель_атаки == "cell":
                    ТЫЛ["бой"] = (клетка[0], клетка[1])

        # СТРЕЛКИ В ТЫЛ — в такт, где удара НЕ БЫЛО: файл приказа один, и удар
        # модели всегда важнее. Ставим, когда ждём постановки, и переставляем,
        # когда бой ушёл на три клетки и больше (число из подсказки мака).
        if getattr(a, "rear_shooters", 0) and not удар_в_такте and not st.get("peacemode"):
            _стрелков = _чис(st.get("mil_shooters"))
            _бой = ТЫЛ.get("бой")
            _надо = bool(ТЫЛ.get("ждёт"))
            _где = ТЫЛ.get("клетка")
            if _бой and _где and not _надо:
                if max(abs(_бой[0] - _где[0]), abs(_бой[1] - _где[1])) >= a.rear_shooters + 3:
                    _надо = True         # бой ушёл — переставить
            if _надо and _стрелков > 0 and _бой:
                _цель = тыловая_клетка(st, _бой, a.rear_shooters)
                # Файл приказа ОДИН: не тратим такт на повтор той же клетки от
                # того же боя — смоук 27.09 показал два одинаковых отвода в (2,10)
                # от боя (1,4) подряд, и второй был впустую.
                if (_цель is not None and _цель == ТЫЛ.get("клетка")
                        and _бой == ТЫЛ.get("бой_отвода")):
                    ТЫЛ["ждёт"] = False
                    _цель = None
                    print("        стрелки уже в тылу той же клетки — приказ не трачу")
                if _цель is None:
                    print(f"        стрелков в тыл НЕ ОТВЁЛ: от боя "
                          f"({_бой[0]},{_бой[1]}) до нашей базы тыла не находится")
                elif br.attack(_стрелков, "cell", mode="move", cx=_цель[0],
                               cy=_цель[1], who="musk17"):
                    ТЫЛ.update(ждёт=False, клетка=_цель, когда=gt, бой_отвода=_бой)
                    print(f"        СТРЕЛКИ В ТЫЛ: {_стрелков} мушкетёров идут в "
                          f"({_цель[0]},{_цель[1]}) — за {a.rear_shooters} клеток от "
                          f"боя ({_бой[0]},{_бой[1]}) к нашей базе")
                    вмешательство = (вмешательство + "; " if вмешательство else "") + (
                        f"МОСТ ОТВЁЛ СТРЕЛКОВ: {_стрелков} мушкетёров в клетку "
                        f"({_цель[0]},{_цель[1]}), за {a.rear_shooters} клеток от боя. "
                        f"Они бьют подходящих из-за пикинёров; переставлю сам, когда "
                        f"бой сместится")
                else:
                    print("        стрелков в тыл не отвёл: прошлый приказ ещё не забран")
            elif _надо and _стрелков <= 0:
                print("        стрелков в тыл не отвёл: мушкетёров нет ни одного")

        # Горизонт считаем ОТ НАЧАЛА ЭПИЗОДА, а не по абсолютному времени: в
        # игре после NEW часы идут с нуля и разницы нет, а у мока своё время,
        # и абсолютный горизонт обрывал прогон на первом же такте.
        if a.stop_at and gt - gt0 >= a.stop_at:
            # Учебный отрезок: партия обрывается задолго до горизонта, чтобы за
            # то же время сыграть больше партий. Цель при этом НЕ меняется —
            # меняется только длина куска, который мы смотрим.
            print()
            темп_игры()
            _м, _с = divmod(int(a.stop_at), 60)
            print(f"учебный отрезок {_м}:{_с:02d} пройден — начинаю новую партию")
            отметить_конец(a, st, gt, "отрезок")
            return "отрезок"
        if gt - gt0 >= a.horizon:
            print()
            темп_игры()
            print(f"горизонт {a.horizon} исчерпан, цель не достигнута")
            отметить_конец(a, st, gt, "горизонт")
            return "горизонт"


ПОЛЯ_КРИТИКА = ("причина", "узкое_место", "гипотеза", "как_проверить")
ПОЛЯ_КРИТИКА_СЕРИИ = ("различие", "это_эффект_или_разброс", "механизм",
                      "что_мерить_дальше")


def поля_из_текста(текст: str, ключи=ПОЛЯ_КРИТИКА) -> dict:
    """Поля критика из текста, даже если JSON битый.

    Модель отвечает коротко и по схеме, но иногда ставит лишнее вокруг скобок
    или кавычку внутри строки — и json.loads отказывается. Сам ответ при этом
    полезен, а второй вызов стоит денег и времени.

    Ключи передаются списком: у разбора серии поля ДРУГИЕ, и 20.09 первый же
    живой прогон серии пропал впустую — ответ пришёл разумный, а разборщик
    искал в нём имена полей разбора партии и не нашёл ничего.
    """
    из = {}
    for ключ in ключи:
        м = re.search(rf'"{ключ}"\s*:\s*"(.*?)"\s*[,}}\n]', текст, re.S)
        if not м:
            м = re.search(rf'"{ключ}"\s*:\s*"([^"]*)', текст, re.S)
        if м:
            з = " ".join(м.group(1).split())
            if з:
                из[ключ] = з
    return из


def строка_такта(st: dict, mp: dict, cmds, attack, цель_атаки,
                 событие: str = "") -> str:
    """Сжатая строка такта для критика: ресурсы, люди, армия, команды.

    Вынесена из петли 20.09, чтобы тот же текст собирался и при разборе
    ГОТОВОЙ трассы (`--critic-trace`). Двух копий этой строки быть не должно:
    разбор задним числом обязан видеть ровно то, что видел бы критик вживую,
    иначе выводы двух путей разойдутся и сравнивать их станет нельзя.
    """
    _ц = lambda k: st.get(k, "?")
    _кмд = " ".join(f"{c.cmd}:{c.a1}={c.a2}" for c in cmds) or "—"
    if attack:
        _кмд += f" ATTACK:{attack}->{цель_атаки}"
    _мм, _сс = divmod(int(float(st.get("gametime", 0) or 0)), 60)
    # Крестьяне врага — наша мера цели; ключ зависит от номера слота.
    # ТОЛЬКО чужие слоты: имена вида p<номер>_<что>. Хвост "_inf"
    # ловит и СВОЁ mil_inf, и строка критика показала бы нашу пехоту
    # как вражескую — поймано на моке 16.09.
    _взято_апгр = len(взятые_апгрейды(st))
    _вражьи = {k: v for k, v in st.items() if _ПОЛЕ_ВРАГА.match(k)}
    _вражкр = next((v for k, v in _вражьи.items()
                    if k.endswith("_peasants")), "?")
    _вражарм = next((v for k, v in _вражьи.items()
                     if k.endswith("_army")), "?")
    _вражшахт = next((v for k, v in _вражьи.items()
                      if k.endswith("_mines")), "?")
    def _вражпо(*хвосты):
        "п12/с8/к4 — состав врага, только ненулевое; пусто, если нечего сказать"
        _ч = []
        for _х, _б in хвосты:
            _з = next((v for k, v in _вражьи.items() if k.endswith(_х)), 0)
            try:
                _з = int(float(_з or 0))
            except (TypeError, ValueError):
                _з = 0
            if _з:
                _ч.append(f"{_б}{_з}")
        return "(" + "/".join(_ч) + ")" if _ч else ""
    _вражсост = _вражпо(("_inf", "п"), ("_shoot", "с"), ("_cav", "к"))
    _вражшсост = _вражпо(("_mgold", "з"), ("_miron", "ж"), ("_mcoal", "у"))
    _хвост = ""
    # Открытая информация (18.09): ресурсы врага и его движение — в
    # строку критика, иначе он додумает, шёл ли враг и был ли богат.
    _вз, _вж = поле_врага(st, mp, "gold"), поле_врага(st, mp, "iron")
    if _вз is not None:
        _хвост += f" вр.рес=з{_вз}/ж{_вж}"
    _вд, _вб = поле_врага(st, mp, "mv_n"), поле_врага(st, mp, "mv_base")
    if _вд is not None:
        _хвост += f" вр.движ={_вд}(к нам {_вб or 0})"
    # Потери по счёту движка (20.09): иначе критик судит об ударе по
    # падению счётчика крестьян, а тот падает и от ухода в шахты.
    _впк = поле_врага(st, mp, "pea_lost")
    if _впк is not None:
        _хвост += (f" потери=вр.кр{_впк}/б{поле_врага(st, mp, 'mil_lost') or 0}"
                   f" наши.кр{st.get('my_pea_lost', 0)}/б{st.get('my_mil_lost', 0)}")
    # СКОЛЬКО ЕГО УЖЕ У НАШЕЙ БАЗЫ. «Идут к нам» и «дерутся у нас» -
    # разные вещи, и по одному `вр.движ` критик их не различал: волна
    # могла уже дойти и выйти из счёта идущих. Это же число - тот
    # знаменатель, по которому считается перевес у базы.
    try:
        _сб = ({} if (ЧЕСТНО and not карта_открыта(st))
               else (coss3_map.у_базы(st) or {}))
        _уб = _чис(_сб.get("бойцов"))
        if _уб:
            _хвост += f" у нашей базы={_уб} своб.бойцов={_чис(st.get('my_freewar'))}"
    except Exception:
        pass
    _с = str(st.get("wip", "") or "")
    if _с:
        _хвост += f" строится={_с}"
    _н = str(st.get("cant_now", "") or "").strip()
    if _н:
        _хвост += f" НЕ ПО КАРМАНУ: {_н}"
    _о = " ".join(str(st.get("last_fail", "") or "").split())
    if _о:
        _хвост += f" | отказ: {_о[:90]}"
    # ПОВОД ТАКТА. Событийный такт узкий нарочно: у модели там один вопрос и
    # одна команда. Без этой пометки критик разбирает его как обычный и
    # объясняет бедность решения недомыслием модели.
    if событие:
        _хвост += f" | ВНЕОЧЕРЕДНОЙ ВОПРОС ПО СОБЫТИЮ: {событие}"
    return (
        f"{_мм}:{_сс:02d} еда={_ц('food')} дер={_ц('wood')} кам={_ц('stone')} "
        f"зол={_ц('gold')} жел={_ц('iron')} уг={_ц('coal')} | "
        f"крест={_ц('peasants')} своб={_ц('idle_pea')} "
        f"еда/дер/кам/шахта/стройка="
        f"{_ц('on_food')}/{_ц('on_wood')}/{_ц('on_stone')}/"
        f"{_ц('on_mine')}/{_ц('on_build')} "
        f"(в шахтах з{_ц('on_gold')}/ж{_ц('on_iron')}/у{_ц('on_coal')} "
        f"мест з{_ц('cap_gold')}/ж{_ц('cap_iron')}/у{_ц('cap_coal')}) | "
        f"мест={_ц('my_farmused')}/{_ц('my_farm')} | "
        f"ратуш={_ц('centers')} мельн={_ц('mills')} "
        f"кузн={_ц('smiths')} казарм={_ц('ba17')}"
        # Цена СЛЕДУЮЩЕЙ казармы — тот самый расход, который критик
        # 16.09 принял за нехватку добычи: вторая стоит впятеро дороже.
        + (f"(следующая {цена_построек(st).get('ba17', {}).get('gold', 0)} зол)"
           if цена_построек(st).get("ba17", {}).get("gold") else "")
        + f" склад={_ц('my_stores')} "
        f"шахты з{_ц('mines_gold')}/ж{_ц('mines_iron')}/у{_ц('mines_coal')} | "
        f"пехота={_ц('mil_inf')} стрелки={_ц('mil_shooters')} "
        f"свободбойц={_ц('my_freewar')} волна={_ц('wave_sent')} "
        f"ушли={_ц('mil_away')} ранены={_ц('mil_hurt')} "
        f"от={_ц('mil_near')}до={_ц('mil_far')} сторона={_ц('mil_side')} | "
        f"апгр_взято={_взято_апгр} "
        f"крестьян_врага={_вражкр} армия_врага={_вражарм}"
        f"{_вражсост} шахты_врага={_вражшахт}{_вражшсост} "
        f"досюда={_ц('en_near_dist')} "
        # Враг у НАШЕЙ базы — иначе критик припишет набег походу.
        f"враг_у_базы={coss3_map.у_базы(st).get('бойцов', 0)} "
        f"марш={МАРШ.get('фаза', '-')} | "
        f"мест_на_земле дер={_ц('wood_slots_free')}/{_ц('wood_slots_near')} "
        f"кам={_ц('stone_slots_free')}/{_ц('stone_slots_near')} | "
        f"{_кмд}{_хвост}")


def разбор_партии(a, client, номер: int, итог: str, дневник) -> str:
    """Критик: один вызов после партии. Возвращает записанное или пусто.

    Зачем отдельной ролью, а не полем в такте: в бою модель занята ходом, и
    выводы у неё получаются про последний такт. Здесь она видит партию целиком
    и не платит за это задержкой — партия уже кончилась.
    """
    if not a.critic:
        return ""
    строки = дневник.строки() if дневник else []
    if not строки and not ТРАССА_ПАРТИИ:
        print("        разбор не делаю: ни дневника, ни трассы (нужен --memo)")
        return ""
    # 15.09: критику давали ТОЛЬКО дневник, и он пять раз из девяти написал «не
    # видно из данных», а в остальных случаях достроил недостающее сам —
    # предлагал строить лесопилку и каменоломню, которых в игре нет. Теперь он
    # получает то же, что видим мы: такты с ресурсами и людьми, и уроки, которые
    # модель писала по ходу партии.
    части = [f"# Партия {номер}, исход: {итог}"]
    if строки:
        части += ["", "## Дневник партии", *строки]
    if ТРАССА_ПАРТИИ:
        части += ["", "## Такты партии (ресурсы, люди, здания, команды)",
                  *ТРАССА_ПАРТИИ]
    if УРОКИ_ПАРТИИ:
        части += ["", "## Что модель заметила по ходу партии", *УРОКИ_ПАРТИИ]
    запрос = "\n".join(части)
    ответ = {}
    try:
        прежний = SYSTEM
        globals()["SYSTEM"] = (SYSTEM_CRITIC + замеры_для_критика()
                                   + уже_проверено())
        try:
            ответ = ask(client, a.model, запрос, a.think, retry=1,
                        max_tokens=3000)
        finally:
            globals()["SYSTEM"] = прежний
    except Exception as e:
        # JSON не собрался — но разбор это не такт, терять его жалко. Ответ
        # критика короткий (замер 14.09: 417 символов), и поля из него
        # вытаскиваются построчно даже когда скобки битые: лишний текст вокруг,
        # кавычка внутри строки, оборванный хвост.
        сырое = str(e)
        ответ = поля_из_текста(сырое)
        if ответ:
            print("        JSON критика битый — разобрал по полям")
        else:
            print(f"        разбор не удался: {сырое[:400]}")
            return ""
    if not ответ:
        print("        разбор пуст: модель не вернула разбираемого JSON")
        return ""
    ГИПОТЕЗА_КРИТИКА.clear()
    ГИПОТЕЗА_КРИТИКА.update(
        {"гипотеза": str(ответ.get("гипотеза", "") or "").strip(),
         "как": str(ответ.get("как_проверить", "") or "").strip(),
         "партия": номер})
    куски = [f"## Партия {номер}: {итог}"]
    for ключ, подпись in (("причина", "Причина"), ("узкое_место", "Узкое место"),
                          ("гипотеза", "Гипотеза"), ("как_проверить", "Как проверить")):
        з = str(ответ.get(ключ, "") or "").strip()
        if з:
            куски.append(f"* **{подпись}:** {з}")
    if len(куски) == 1:
        print("        разбор пуст: модель не заполнила поля")
        return ""
    текст = "\n".join(куски)
    print("\n".join("        " + с for с in текст.splitlines()))
    try:
        with open(a.critic, "a", encoding="utf-8") as f:
            f.write(текст + "\n\n")
    except OSError as e:
        print(f"        разбор не записан ({e})")
    return текст


SYSTEM_CRITIC_SERIES = """\
Ты разбираешь СЕРИЮ партий Cossacks 3, сыгранных ботом через мост. Партий
несколько, и они разбиты на ПЛЕЧИ: плечи отличаются друг от друга ровно одной
вещью — она названа в шапке. Всё остальное одинаково: мост, карта, противник,
горизонт.

Твоя работа — не разобрать партию, а ответить на один вопрос: ВИДНО ЛИ
РАЗЛИЧИЕ МЕЖДУ ПЛЕЧАМИ, и если видно, через какой механизм оно действует.

ГЛАВНАЯ ОПАСНОСТЬ, И ЗДЕСЬ ОНА СИЛЬНЕЕ ВСЕГО. Разброс между партиями ОДНОГО
плеча в этом проекте бывает больше самой разницы между плечами: в одной паре
волн вышло 3 и 21, а пик армии 225 и 97 — в одном и том же плече. Поэтому
«в плече А число больше» само по себе НИЧЕГО не значит. Прежде чем назвать
различие, сравни его с разбросом ВНУТРИ плеча; если оно того же порядка —
так и скажи: различия не видно, это разброс. Такой ответ — правильный ответ,
а не отказ от работы.

Тебе дают по каждой партии сводку: исход, вехи построек со временем, волны и
их размер, ключевые числа по минутам и уроки, которые бот писал по ходу.

Отвечай ТОЛЬКО JSON:
{"различие": "одно предложение: что отличается между плечами, с числами обоих",
 "это_эффект_или_разброс": "эффект или разброс, и почему — через сравнение с разбросом внутри плеча",
 "механизм": "через что идея действует, если действует; иначе - не видно",
 "что_мерить_дальше": "какое число покажет это надёжнее и сколько партий нужно"}

По-русски. КАЖДОЕ ПОЛЕ — ОДНО ПРЕДЛОЖЕНИЕ, не длиннее 25 слов; внутри строк не
переноси строки и не ставь кавычек. Ничего, кроме JSON.
"""


def сводка_партии(такты: list[dict], подпись: str) -> list[str]:
    """Партия в двадцати строках: то, по чему сравнивают плечи.

    Потактовую трассу здесь давать нельзя — четыре партии это больше двухсот
    строк, и главное в них тонет. Берём то, чем мы сами меряем идеи: исход,
    вехи, волны, ключевые числа по минутам, уроки.
    """
    из = [f"### {подпись}"]
    дневник = Дневник()
    волны, уроки, срезы = [], [], []
    итог = "оборвана (горизонта не достигла)"
    пик_наш = пик_его = просадка = 0
    прежний_его = None
    последнее: dict = {}
    последний_его = последние_его_крестьяне = 0
    следующий_срез = 300
    for д in такты:
        if д.get("finish"):
            итог = str(д.get("finish"))
        ст = д.get("state") or {}
        if not ст:
            continue
        ст = dict(ст)
        for имя in ("frow", "arow"):
            ряды = ст.get(имя)
            if isinstance(ряды, list):
                for i, ряд in enumerate(ряды):
                    ст[f"{имя}{i}"] = ряд
        дневник.такт(ст)
        последнее = ст
        gt = int(float(ст.get("gametime", 0) or 0))
        наш = (_чис(ст.get("mil_inf")) + _чис(ст.get("mil_shooters"))
               + _чис(ст.get("mil_cav")))
        его = _чис(поле_врага(ст, ст, "army"))
        пик_наш = max(пик_наш, наш)
        пик_его = max(пик_его, его)
        if прежний_его and его and его < прежний_его:
            просадка += прежний_его - его
        if его:
            прежний_его = его
            последний_его = его
        # Запись `finish` несёт УСЕЧЁННОЕ состояние: своих в нём видно, а полей
        # врага нет. Брать их из последнего такта значило бы написать «крестьян
        # врага 0» там, где минутой раньше их было 139 — ложный ноль на ровном
        # месте, третий за сутки в этом же проекте.
        крест_его = _чис(поле_врага(ст, ст, "peasants"))
        if крест_его:
            последние_его_крестьяне = крест_его
        if д.get("attack"):
            сколько = "все" if д.get("attack") == 9999 else д.get("attack")
            волны.append(f"{_мс(gt)} {сколько}->{д.get('target') or '?'}")
        урок = " ".join(str(д.get("lesson", "") or "").split())
        if урок:
            уроки.append(f"{_мс(gt)} {урок[:110]}")
        if gt >= следующий_срез:
            срезы.append(f"{_мс(gt)} наши {наш} (пех {_чис(ст.get('mil_inf'))}/"
                         f"стр {_чис(ст.get('mil_shooters'))}/кон {_чис(ст.get('mil_cav'))}) "
                         f"его {его} | крест наши {_чис(ст.get('peasants'))} его "
                         f"{_чис(поле_врага(ст, ст, 'peasants'))} | зол "
                         f"{_чис(ст.get('gold'))} еда {_чис(ст.get('food'))} | казарм "
                         f"{_чис(ст.get('ba17'))} конюшен {_чис(ст.get('stables'))}")
            следующий_срез += 300
    из.append(f"  исход: {итог}; тактов {sum(1 for д in такты if д.get('state'))}")
    из.append(f"  армия к пику: наша {пик_наш}, его {пик_его}; просадка его армии "
              f"за партию {просадка}")
    из.append(f"  к концу: пехота {_чис(последнее.get('mil_inf'))} стрелки "
              f"{_чис(последнее.get('mil_shooters'))} конница "
              f"{_чис(последнее.get('mil_cav'))}; у врага армия {последний_его}, "
              f"крестьян {последние_его_крестьяне}")
    if дневник.вехи:
        из.append("  построено: " + "   ".join(дневник.вехи[:12]))
    из.append(f"  волн {len(волны)}" + ((": " + "; ".join(волны[:12])) if волны else ""))
    из += ["  " + с for с in срезы]
    if уроки:
        из.append("  уроки бота:")
        из += ["    " + у for у in уроки[:6]]
    return из


def разбор_серии(a, client) -> int:
    """`--critic-series плечо=трасса`: сравнить ПЛЕЧИ, а не разобрать партию.

    Зачем отдельно от `--critic-trace`. Критик по одной партии расходится сам
    с собой: 20.09 на трёх партиях одного прогона он дал три взаимоисключающих
    совета — не атаковать, атаковать раньше, атаковать непрерывно. Причина не
    в нём: разброс между партиями одного плеча больше измеряемого эффекта, и
    по одной партии вывода нет ни у него, ни у нас. Здесь он видит оба плеча
    сразу, знает, чем они отличаются, и обязан сказать «это разброс», когда
    различие того же порядка, что и разброс внутри плеча.
    """
    if not a.critic:
        print("--critic-series без --critic: некуда писать разбор")
        return 2
    плечи: dict[str, list[str]] = {}
    for пара in a.critic_series:
        if "=" not in пара:
            print(f"--critic-series ждёт «плечо=трасса», а получил: {пара}")
            return 2
        имя, путь = пара.split("=", 1)
        плечи.setdefault(имя.strip(), []).append(путь.strip())
    if len(плечи) < 2:
        print("для сравнения нужно хотя бы два плеча: "
              f"дано {len(плечи)} ({', '.join(плечи) or 'ни одного'})")
        return 2
    части = ["# Серия: сравнение плеч"]
    if a.critic_diff:
        части.append(f"Плечи отличаются ровно этим: {a.critic_diff}")
    else:
        части.append("Чем отличаются плечи — не сказано; суди только по числам.")
    всего = 0
    for имя, пути in плечи.items():
        части += ["", f"## Плечо {имя}"]
        for путь in пути:
            try:
                партии = _партии_из_трассы(путь)
            except OSError as e:
                print(f"  трассу не прочитать ({путь}): {e}")
                continue
            for номер, такты in enumerate(партии, 1):
                всего += 1
                части += сводка_партии(
                    такты, f"{имя}, {os.path.basename(путь)}, партия {номер}")
    if всего < 2:
        print(f"партий набралось {всего} — сравнивать нечего")
        return 2
    print(f"разбор серии: плеч {len(плечи)}, партий {всего}")
    ответ = {}
    try:
        прежний = SYSTEM
        globals()["SYSTEM"] = SYSTEM_CRITIC_SERIES + замеры_для_критика()
        try:
            ответ = ask(client, a.model, "\n".join(части), a.think, retry=1,
                        max_tokens=3000)
        finally:
            globals()["SYSTEM"] = прежний
    except Exception as e:
        ответ = поля_из_текста(str(e), ПОЛЯ_КРИТИКА_СЕРИИ)
        if ответ:
            print("        JSON критика битый — разобрал по полям")
        else:
            print(f"        разбор серии не удался: {str(e)[:400]}")
            return 1
    if not ответ:
        print("        разбор пуст: модель не вернула разбираемого JSON")
        return 1
    куски = [f"## Серия: {' против '.join(плечи)} ({всего} партий)"]
    for ключ, подпись in (("различие", "Различие"),
                          ("это_эффект_или_разброс", "Эффект или разброс"),
                          ("механизм", "Механизм"),
                          ("что_мерить_дальше", "Что мерить дальше")):
        з = str(ответ.get(ключ, "") or "").strip()
        if з:
            куски.append(f"* **{подпись}:** {з}")
    if len(куски) == 1:
        print("        разбор пуст: модель не заполнила поля")
        return 1
    текст = "\n".join(куски)
    print("\n".join("        " + с for с in текст.splitlines()))
    try:
        with open(a.critic, "a", encoding="utf-8") as f:
            f.write(текст + "\n\n")
    except OSError as e:
        print(f"        разбор не записан ({e})")
    return 0


class _Кмд:
    """Команда из трассы в том виде, в каком её ждёт `строка_такта`."""

    __slots__ = ("cmd", "a1", "a2", "upg")

    def __init__(self, d: dict) -> None:
        self.cmd = d.get("cmd")
        self.a1 = d.get("a1")
        self.a2 = d.get("a2")
        self.upg = d.get("upg", "")


def _партии_из_трассы(путь: str) -> list[list[dict]]:
    """Трасса → список партий. Одна строка файла — один такт.

    Трасса ДОПИСЫВАЕТСЯ между партиями и между запусками: 15.09 в одном файле
    оказалось шестнадцать партий, и счёт по всему файлу смешал сегодняшнее со
    вчерашним. Границу даёт падение игрового времени; запись `finish` закрывает
    партию и несёт её исход.
    """
    партии: list[list[dict]] = []
    текущая: list[dict] = []
    прошлое = None
    with open(путь, encoding="utf-8") as ф:
        сырое = ф.readlines()
    for строка in сырое:
        строка = строка.strip()
        if not строка:
            continue
        try:
            д = json.loads(строка)
        except ValueError:
            continue                   # битая строка не должна ронять разбор
        gt = д.get("gt")
        if gt is None:
            gt = (д.get("state") or {}).get("gametime") or 0
        # Порог в минуту: внутри партии время идёт вперёд, но соседние такты
        # могут прийти не по порядку. Новая партия начинается с нуля.
        if прошлое is not None and gt < прошлое - 60:
            партии.append(текущая)
            текущая = []
        прошлое = gt
        текущая.append(д)
        if д.get("finish"):
            партии.append(текущая)
            текущая = []
            прошлое = None
    if текущая:
        партии.append(текущая)
    return [п for п in партии if len(п) > 1]


def разбор_трассы(a, client) -> int:
    """`--critic-trace`: разобрать ГОТОВУЮ трассу, не запуская игру.

    Зачем. Критик вызывается один раз в конце партии, и всё, что оборвалось
    раньше, остаётся без разбора навсегда: 20.09 пара `base22`/`switch4` была
    остановлена после первых партий, и две трассы из четырёх ушли в архив без
    единого слова критика — в том числе ЕДИНСТВЕННАЯ партия, где сработала
    связка 4, ради которой прогон и затевался.

    Что критик получает здесь и чего не получает. Строки тактов и уроки
    модели восстанавливаются ДОСЛОВНО: они собираются тем же
    `строка_такта` и лежат готовыми в поле `lesson`. Дневник
    восстанавливается ПОЧТИ дословно — `Дневник.такт` сам считает вехи и
    неудачи из состояния, но итоги волн он подводит по живым числам через
    минуту после отправки, и здесь они берутся из тех же тактов трассы.
    Чего нет совсем — `mp` (карта чужих полей живого моста): в трассе лежит
    снимок состояния, и поля врага берутся из него же. Об этом сказано вслух
    в шапке разбора, чтобы разбор задним числом не выдавали за живой.
    """
    if not a.critic:
        print("--critic-trace без --critic: некуда писать разбор")
        return 2
    try:
        партии = _партии_из_трассы(a.critic_trace)
    except OSError as e:
        print(f"трассу не прочитать: {e}")
        return 2
    if not партии:
        print(f"в трассе {a.critic_trace} не нашлось ни одной партии")
        return 2
    print(f"разбор готовой трассы: {a.critic_trace}, партий {len(партии)}")
    сделано = 0
    for номер, такты in enumerate(партии, 1):
        ТРАССА_ПАРТИИ.clear()
        УРОКИ_ПАРТИИ.clear()
        дневник = Дневник()
        итог = "неизвестен (партия оборвана)"
        for д in такты:
            if д.get("finish"):
                итог = str(д.get("finish"))
            ст = д.get("state") or {}
            if not ст:
                continue
            # Сетки в снимке лежат списком, а код читает `frow0..frowN`:
            # без разворота блоки, считающие по клеткам, молчат по построению,
            # и это уже дважды давало ложный ноль.
            ст = dict(ст)
            for имя in ("frow", "arow"):
                ряды = ст.get(имя)
                if isinstance(ряды, list):
                    for i, ряд in enumerate(ряды):
                        ст[f"{имя}{i}"] = ряд
            дневник.такт(ст)
            атака = д.get("attack") or 0
            if атака:
                дневник.волна(int(д.get("gt") or ст.get("gametime") or 0),
                              атака, str(д.get("target") or ""), ст)
            cmds = [_Кмд(c) for c in (д.get("cmds") or [])]
            try:
                ТРАССА_ПАРТИИ.append(
                    строка_такта(ст, ст, cmds, атака, str(д.get("target") or ""),
                                 событие=str(д.get("событие") or "")))
            except Exception as e:      # такт не должен ронять разбор партии
                print(f"  такт пропущен: {e}")
            урок = " ".join(str(д.get("lesson", "") or "").split())
            if урок:
                мм, сс = divmod(int(float(ст.get("gametime", 0) or 0)), 60)
                УРОКИ_ПАРТИИ.append(f"{мм}:{сс:02d} {урок}")
        print(f"  партия {номер}: тактов {len(ТРАССА_ПАРТИИ)}, уроков "
              f"{len(УРОКИ_ПАРТИИ)}, исход {итог}")
        if разбор_партии(a, client, номер, итог, дневник):
            сделано += 1
    print(f"разобрано партий: {сделано} из {len(партии)}; записано в {a.critic}")
    return 0 if сделано else 1


def показать_счёт(explicit: str = "") -> int:
    """Остаток на счету OpenRouter. Своя ручка, не через OpenAI-клиент.

    Без этого 402 виден только как строка ошибки внутри сбоя вызова, а в бою
    это выглядит как «модель молчит»: 11.09.2026 половина замера ушла в 402,
    и по счётчику сбоёв было не отличить деньги от лимита провайдера.
    """
    import urllib.request
    key, src = load_key(explicit)
    if not key:
        print("нет ключа")
        return 1
    if "openrouter" not in BASE_URL:
        print(f"счёт умеет показывать только OpenRouter, а адрес {BASE_URL}")
        return 1
    req = urllib.request.Request(BASE_URL.rsplit("/v1", 1)[0] + "/v1/credits",
                                 headers={"Authorization": f"Bearer {key}"})
    try:
        d = json.load(urllib.request.urlopen(req, timeout=20))["data"]
    except Exception as e:
        print(f"счёт не отдался: {str(e)[:120]}")
        return 1
    куплено = float(d.get("total_credits", 0))
    потрачено = float(d.get("total_usage", 0))
    print(f"ключ из {src}\nкуплено ${куплено:.2f}, потрачено ${потрачено:.2f}, "
          f"ОСТАТОК ${куплено - потрачено:.2f}")
    if куплено - потрачено < 1:
        print("  меньше доллара — дорогая модель начнёт отвечать 402 уже сейчас:\n"
              "  запрос отвергается, если возможная цена ответа больше остатка")
    return 0


def предпросмотр_подсказок(a) -> int:
    """Что из подсказок реально уйдёт в модель — по звеньям цепочки.

    Между файлом и моделью стоит фильтр: строки с # отбрасываются, а строка с
    меткой звена исчезает, когда звено пройдено. Поэтому «файл изменился» и
    «модель это увидела» — не одно и то же, и вот это их и разводит.
    """
    сырое = load_hints(a.hints)
    print(f"файл {a.hints}: {len(сырое)} символов, {len(сырое.splitlines())} строк\n")
    d = os.path.expandvars(a.dir)
    plind = a.plind if a.plind is not None else find_ai_plind(d, human=a.human)
    живое = None
    if plind is not None:
        живое = Bridge(d, plind).read_state()
    if живое:
        показ = [("сейчас в партии", живое)]
    else:
        print("живой партии нет — показываю для типовых состояний\n")
        показ = [
            ("голый старт", {"peasants": 5, "smiths": 0, "ba17": 0}),
            ("кузница есть", {"peasants": 20, "smiths": 1, "ba17": 0}),
            ("казарма есть", {"peasants": 20, "smiths": 1, "ba17": 1}),
            ("армия и волна", {"peasants": 20, "smiths": 1, "ba17": 1,
                               "mil_inf": 5, "my_armies": 1}),
        ]
    for имя, st in показ:
        текст = отобрать_подсказки(сырое, st)
        цепь = " ".join(("+" if ok else "-") + n for n, ok, _ in stages(st))
        print(f"=== {имя}: {цепь}")
        print(f"    {len(текст)} симв., ~{len(текст) // 3} токенов")
        for стр in текст.splitlines():
            print(f"    | {стр}")
        print()
    отброшено = [l.strip() for l in сырое.splitlines() if l.strip().startswith("#")]
    if отброшено:
        print(f"строк с # отброшено: {len(отброшено)} — в модель они не идут")
    плохие = неизвестные_метки(сырое)
    if плохие:
        print(f"\nВНИМАНИЕ: метки не из списка звеньев: {', '.join(sorted(set(плохие)))}")
        print(f"  звенья только эти: {', '.join(ЗВЕНЬЯ)}")
        print("  строка с чужой меткой видна ВСЕГДА и не исчезнет по ходу партии")
    # Подсказка, помеченная звеном, которое пройдено уже на старте, не дойдёт
    # до модели НИ РАЗУ. Это записано в шапке hints_human.txt с 12.09, и на
    # этом успели споткнуться дважды — поэтому предпросмотр обязан сказать сам,
    # а не полагаться на то, что кто-то помнит.
    НИКОГДА = {"экономика": "звено проходится при peasants>=15, "
                            "а партия начинается с 18"}
    беда = []
    for строка in load_hints(a.hints).splitlines():
        м = re.match(r"\s*\[([^\]]+)\]", строка)
        if м and м.group(1).strip().lower() in НИКОГДА:
            беда.append((м.group(1).strip().lower(), строка.strip()[:70]))
    if беда:
        print()
        print("!" * 60)
        print("ЭТИ СТРОКИ НЕ ДОЙДУТ ДО МОДЕЛИ НИ РАЗУ:")
        for метка, текст in беда:
            print(f"  [{метка}] {текст}")
            print(f"      {НИКОГДА[метка]}")
        print("Снимите метку, если строка нужна всегда.")
        print("!" * 60)
    return 0


def поднять_окно(log: str) -> None:
    """Запускает overlay.ps1 отдельным процессом. Он читает наш лог, так что
    переживает и смену эпизода, и перезапуск скрипта."""
    здесь = os.path.dirname(os.path.abspath(__file__))
    скрипт = os.path.join(здесь, "overlay.ps1")
    if os.name != "nt":
        print(f"окно поверх игры — только Windows; здесь запустите вручную:\n"
              f"        powershell -ExecutionPolicy Bypass -File {скрипт}")
        return
    if not os.path.exists(скрипт):
        print(f"не нашёл {скрипт} — окно не поднял")
        return
    if not log:
        print("окно нечего показывать: --log пустой")
        return
    try:
        subprocess.Popen(
            ["powershell", "-ExecutionPolicy", "Bypass", "-File", скрипт,
             "-Log", os.path.abspath(log), "-ClickThrough"],
            creationflags=getattr(subprocess, "CREATE_NEW_CONSOLE", 0))
        print("окно поверх игры поднято (клики сквозь него уходят в игру)")
    except Exception as e:
        print(f"окно не поднялось ({e}) — запустите overlay.ps1 руками")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=os.path.expandvars(os.path.expanduser("~/coss3-io")))
    ap.add_argument("--plind", type=int, default=None)
    ap.add_argument("--model", default=(os.environ.get("COSS3_MODEL")
                                    or os.environ.get("NIM_MODEL")
                                    or DEFAULT_MODEL))
    ap.add_argument("--every", type=int, default=15,
                    help="решение раз в N игровых секунд")
    ap.add_argument("--hints", default="hints.txt",
                    help="файл ИЛИ ссылка http(s) — чтобы править с другой машины")
    ap.add_argument("--lessons-after", type=int, default=60,
                    metavar="сек",
                    help="не записывать уроки раньше этой игровой секунды: до неё это планы")
    ap.add_argument("--ban", default="",
                    metavar="роль,роль",
                    help="роли, запрещённые настройками партии: --ban market,ba18")
    ap.add_argument("--lessons", default="lessons.txt",
                    metavar="файл",
                    help="куда складывать наблюдения модели; в промпт они НЕ возвращаются")
    ap.add_argument("--world", default="",
                    metavar="файл",
                    help="файл знаний о мире: уходит в промпт ЦЕЛИКОМ, и туда же "
                         "модель пишет свой вопрос человеку. Пусто — канал выключен")
    ap.add_argument("--max-commands", type=int, default=7, metavar="N",
                    help="сколько команд мост читает за такт (умолчание 7, до 16.09 было 6). "
                         "Меняет и текст промпта: обещать одно, а резать по "
                         "другому нельзя")
    ap.add_argument("--critic-forward", dest="critic_forward",
                    action="store_true",
                    help="возвращать гипотезу критика в СЛЕДУЮЩУЮ партию как "
                         "задание на проверку. Без флага разбор остаётся файлом "
                         "для человека, как было до 17.09")
    ap.add_argument("--schema", dest="schema", action="store_true",
                    help="нативный structured output: форма ответа задаётся "
                         "json-схемой, а не просьбой. Провайдер без схемы — "
                         "мост скажет и доиграет по-старому")
    ap.add_argument("--no-schema", dest="schema", action="store_false",
                    help="не просить нативный structured output. Схему снимают, "
                         "когда провайдер её не держит или когда надо сравнить "
                         "с прежним поведением: доля разобранного брака видна "
                         "в отчёте")
    ap.add_argument("--unfair", dest="fair", action="store_false",
                    help="мост подсказывает всё, что знает о партии, включая "
                         "числа противника сквозь туман войны. С 18.09 это "
                         "УМОЛЧАНИЕ: новые правила хакатона разрешают всю "
                         "информацию о партии, правило «как человек» снято")
    ap.add_argument("--fair", dest="fair", action="store_true",
                    help="прежнее правило игрока от 13.09: не давать модели "
                         "того, чего не видит человек за тем же экраном. "
                         "Нужен только для сравнения со старыми сериями")
    # 18.09: правило «играй как человек» СНЯТО новыми правилами хакатона —
    # использовать можно всю информацию о партии. Умолчание стало --unfair;
    # --fair остаётся для сравнения со старыми сериями.
    ap.set_defaults(fair=False, schema=False)
    ap.add_argument("--critic", default="", metavar="файл",
                    help="разбор партии ПОСЛЕ её конца: один вызов модели на "
                         "дневник партии, ответ дописывается в файл. Нужен "
                         "--memo: разбирать нечего, если дневник не вёлся")
    ap.add_argument("--memo", action="store_true",
                    help="дневник партии в запросе: вехи построек, неудачи без "
                         "повторов, исходы волн. Человек помнит структуру, а не "
                         "протокол; полная история ходов замером 13.09 вредна")
    ap.add_argument("--questions", type=int, default=1,
                    metavar="N",
                    help="сколько вопросов модель может задать за партию (по "
                         "умолчанию один: отвечает человек, и он узкое место)")
    ap.add_argument("--dump-prompt", default="",
                    metavar="файл",
                    help="писать туда промпт последнего решения целиком — видно, что ушло")
    ap.add_argument("--hints-preview", action="store_true",
                    help="показать, что из подсказок уйдёт в модель, и выйти")
    ap.add_argument("--overlay", action="store_true",
                    help="поднять окно поверх игры самому (только Windows)")
    ap.add_argument("--botlog", default="coss3_bot.jsonl",
                    metavar="файл",
                    help="лог ДЕЙСТВИЙ бота по строке JSON на такт: что решил, что "
                         "ушло в игру, что игра ответила. Человеку читать лог партии, "
                         "машине — этот")
    ap.add_argument("--snaplog", default="coss3_snap.jsonl", metavar="файл",
                    help="ЧАСТЫЙ снимок состояния, отдельным файлом от трассы: "
                         "числа без карт и цен, по строке на снимок. Отдельно "
                         "потому, что все инструменты проекта считают тактом "
                         "любую запись с `state` — подмешать снимки в общую "
                         "трассу значит молча сменить смысл каждого замера")
    ap.add_argument("--snap-every", type=int, default=5, metavar="СЕК",
                    help="как часто писать снимок, в игровых секундах (0 = не "
                         "писать). Такт идёт медианно раз в 21 с, а игра пишет "
                         "состояние каждую секунду ([замер]: 1033 записи против "
                         "полусотни тактов за партию) — при шаге 5 с получается "
                         "вчетверо больше точек, чем у трассы, при весе около "
                         "150 КБ на партию")
    ap.add_argument("--log", default="coss3_llm.log",
                    help="куда дублировать вывод; его показывает overlay.ps1")
    # ГОРИЗОНТ 1200 с (20 минут) с 19.09, решение игрока. При 900 живая партия
    # того же дня отдала первый и единственный ATTACK на 14:12, за 48 секунд до
    # конца: волна шла верно (с 14 до 50 единиц за 21 с), но горизонт наступил
    # раньше, чем она прошла свои 80 единиц. Пятнадцати минут не хватало на то,
    # чтобы удар вообще состоялся, и исход решала не игра, а таймер.
    ap.add_argument("--horizon", type=int, default=1200)
    ap.add_argument("--stop-at", type=int, default=0, metavar="сек",
                    help="оборвать партию на этой игровой секунде и начать "
                         "следующую. Цель НЕ меняется — это учебный отрезок: "
                         "за то же время больше партий, а значит больше вопросов")
    ap.add_argument("--episodes", type=int, default=1,
                    help="сколько партий отыграть подряд, начиная каждую заново")
    ap.add_argument("--new", action="store_true",
                    help="начать новую партию сразу при запуске, не подхватывать текущую")
    ap.add_argument("--allow-restart", action="store_true",
                    help="разрешить модели просить новую партию полем restart")
    ap.add_argument("--no-mode", action="store_true", help="не выключать нативный ИИ")
    ap.add_argument("--human", action="store_true",
                    help="играем ЧЕЛОВЕЧЕСКИМ слотом: нативного ИИ там нет вовсе, "
                         "команду MODE слать некому, приказы исполняет наш блок в "
                         "progress.inc (правила хакатона)")
    ap.add_argument("--native-war", action="store_true",
                    help="оставить нативную атаку. По умолчанию она выключена и "
                         "волны водит модель: за серию 11.09.2026 все 15 её команд "
                         "ATTACK были отвергнуты, потому что движок держал волну сам")
    ap.add_argument("--key", default="", help="ключ строкой; обычно не нужен")
